/**
 * 日志端口（抽象）。业务/基础设施只依赖此接口，不绑定具体日志库。
 * 替换实现（console / pino / 上报到日志平台）只改 adapter + container，
 * 见 docs/architecture/06-logging.md。
 */
export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

/** 结构化字段，跟随一条日志一起输出。 */
export type LogFields = Record<string, unknown>;

export interface Logger {
  debug(msg: string, fields?: LogFields): void;
  info(msg: string, fields?: LogFields): void;
  warn(msg: string, fields?: LogFields): void;
  error(msg: string, fields?: LogFields): void;
  /**
   * 派生一个带固定字段的子 logger（如 reqId / userId），
   * 之后该 logger 打的每条日志都自动带上这些字段，便于串联一次请求。
   */
  child(bindings: LogFields): Logger;
}

import type { KernelHttpPort } from '../ports/kernel-http-port.js';
import type { SkillKernelPort } from '../ports/skill-kernel-port.js';
import { toKernelCredentials, type MetaCallContext } from '../types.js';

/**
 * 基于 fetch 的 skill 数据面适配器：POST /v3/skill/{action}。
 *
 * skill body 使用嵌套 pagination（不是顶层 limit/offset），故不做 meta 的
 * sanitizeBody 裁剪，原样透传。凭证与 meta 共用同一套（instance + api_key +
 * user_key），user_key 始终透传（skill 无 auth/verify 这类免鉴权动作）。
 */
export class FetchSkillKernelAdapter implements SkillKernelPort {
  constructor(
    private readonly http: KernelHttpPort,
    private readonly timeoutMs: number,
  ) {}

  invoke(action: string, body: Record<string, unknown>, ctx: MetaCallContext) {
    const cred = toKernelCredentials(ctx, { timeoutMs: this.timeoutMs });
    return this.http.postEnvelope(`/v3/skill/${action}`, body, cred);
  }
}

/**
 * Knowledge HTTP 客户端 — 调 core 的 /v3/wiki/* 和 /v3/code-graph/*.
 *
 * 路径与请求体严格对齐 docs/knowledge/knowledge-api.yaml（07/08/11 定稿）。
 * 注：core router 实际监听 `/v3/wiki/*`、`/v3/code-graph/*`，
 * 故此处 baseUrl 不含 /v3，路径带 /v3 前缀。
 *
 * 与 HttpSkillClient 同模式：Bearer + service-id + envelope 解析。
 */
import { CoreUpstreamError } from '../../domain/errors.js';
import type {
  KnowledgeClientPort,
  WikiDetail,
  WikiListResult,
  WikiIngestResult,
  WikiGraphData,
  WikiSearchResult,
  BatchDeleteResult,
  RawFileEntry,
  PageEntry,
  WikiRawReadItem,
  WikiRawWriteFile,
  WikiRawWriteItem,
  WikiRawRmResult,
  WikiPageReadItem,
  WikiPageWriteItem,
  WikiPageWriteResultItem,
  WikiPageRmResult,
  CodeGraphDetail,
  CodeGraphListResult,
  CodeGraphSyncResult,
  CodeGraphToolResult,
} from '../ports/knowledge-client-port.js';

export interface KnowledgeClientConfig {
  baseUrl: string;
  authToken: string;
  serviceId?: string;
  timeoutMs?: number;
}

interface CoreEnvelope<T> {
  code: number;
  message?: string;
  request_id?: string;
  data?: T;
}

export class HttpKnowledgeClient implements KnowledgeClientPort {
  constructor(private readonly cfg: KnowledgeClientConfig) {}

  private async post<T>(path: string, body: unknown): Promise<T> {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), this.cfg.timeoutMs ?? 15_000);
    try {
      const headers: Record<string, string> = { 'Content-Type': 'application/json' };
      if (this.cfg.authToken) headers.Authorization = `Bearer ${this.cfg.authToken}`;
      if (this.cfg.serviceId) headers['x-tdai-service-id'] = this.cfg.serviceId;
      const resp = await fetch(`${this.cfg.baseUrl}${path}`, {
        method: 'POST',
        headers,
        body: JSON.stringify(body),
        signal: ctrl.signal,
      });
      const json = (await resp.json()) as CoreEnvelope<T>;
      if (json.code !== undefined && json.code !== 0) {
        throw new CoreUpstreamError(
          'CORE_UPSTREAM_ERROR',
          resp.status >= 400 ? resp.status : 502,
          json.message || `core error code ${json.code}`,
          json.code,
        );
      }
      if (!resp.ok) {
        throw new CoreUpstreamError('CORE_UPSTREAM_ERROR', resp.status, json.message || `HTTP ${resp.status}`, 0);
      }
      return json.data as T;
    } finally {
      clearTimeout(timer);
    }
  }

  // ═══════════════ Wiki · 资产层 ═══════════════

  async wikiCreate(teamId: string, name: string, userId?: string): Promise<WikiDetail> {
    return this.post('/v3/wiki/create', { team_id: teamId, name, user_id: userId });
  }

  async wikiGet(wikiId: string): Promise<WikiDetail> {
    return this.post('/v3/wiki/get', { wiki_id: wikiId });
  }

  async wikiIngest(wikiId: string): Promise<WikiIngestResult> {
    return this.post('/v3/wiki/ingest', { wiki_id: wikiId });
  }

  async wikiDelete(wikiIds: string[]): Promise<BatchDeleteResult> {
    return this.post('/v3/wiki/delete', { wiki_ids: wikiIds });
  }

  async wikiList(teamId: string, opts?: { status?: string; limit?: number; offset?: number }): Promise<WikiListResult> {
    return this.post('/v3/wiki/list', { team_id: teamId, ...opts });
  }

  // ═══════════════ Wiki · raw 文件层 ═══════════════

  async wikiRawLs(wikiId: string): Promise<{ items: RawFileEntry[] }> {
    return this.post('/v3/wiki/raw/ls', { wiki_id: wikiId });
  }

  async wikiRawRead(wikiId: string, filenames: string[]): Promise<{ items: WikiRawReadItem[] }> {
    return this.post('/v3/wiki/raw/read', { wiki_id: wikiId, filenames });
  }

  async wikiRawWrite(teamId: string, wikiId: string, files: WikiRawWriteFile[], userId?: string): Promise<{ items: WikiRawWriteItem[] }> {
    return this.post('/v3/wiki/raw/write', { team_id: teamId, user_id: userId, wiki_id: wikiId, files });
  }

  async wikiRawRm(teamId: string, wikiId: string, filenames: string[], userId?: string): Promise<WikiRawRmResult> {
    return this.post('/v3/wiki/raw/rm', { team_id: teamId, user_id: userId, wiki_id: wikiId, filenames });
  }

  // ═══════════════ Wiki · page 文件层 ═══════════════

  async wikiPageLs(wikiId: string): Promise<{ items: PageEntry[] }> {
    return this.post('/v3/wiki/page/ls', { wiki_id: wikiId });
  }

  async wikiPageRead(wikiId: string, refs: string[]): Promise<{ items: WikiPageReadItem[] }> {
    return this.post('/v3/wiki/page/read', { wiki_id: wikiId, refs });
  }

  async wikiPageWrite(teamId: string, wikiId: string, pages: WikiPageWriteItem[], userId?: string): Promise<{ items: WikiPageWriteResultItem[] }> {
    return this.post('/v3/wiki/page/write', { team_id: teamId, user_id: userId, wiki_id: wikiId, pages });
  }

  async wikiPageRm(teamId: string, wikiId: string, refs: string[], userId?: string): Promise<WikiPageRmResult> {
    return this.post('/v3/wiki/page/rm', { team_id: teamId, user_id: userId, wiki_id: wikiId, refs });
  }

  // ═══════════════ Wiki · 派生视图 ═══════════════

  async wikiGraph(wikiId: string): Promise<WikiGraphData> {
    return this.post('/v3/wiki/graph', { wiki_id: wikiId });
  }

  async wikiSearch(wikiId: string, query: string, limit?: number, graph?: { hop?: number; decay?: number; minScore?: number }): Promise<WikiSearchResult> {
    return this.post('/v3/wiki/search', { wiki_id: wikiId, query, limit: limit ?? 20, ...(graph && Object.keys(graph).length > 0 ? { graph } : {}) });
  }

  async wikiUpdateMeta(wikiId: string, patch: { name?: string; summary?: string | null }): Promise<WikiDetail> {
    return this.post('/v3/wiki/update-meta', { wiki_id: wikiId, ...patch });
  }

  // ═══════════════ Code-Graph ═══════════════

  async codeGraphCreate(teamId: string, repoUrl: string, branch?: string, userId?: string, repoName?: string): Promise<CodeGraphDetail> {
    return this.post('/v3/code-graph/create', {
      team_id: teamId,
      user_id: userId,
      repo_url: repoUrl,
      branch: branch ?? 'main',
      repo_name: repoName,
    });
  }

  async codeGraphList(teamId: string, opts?: { status?: string; limit?: number; offset?: number }): Promise<CodeGraphListResult> {
    return this.post('/v3/code-graph/list', { team_id: teamId, ...opts });
  }

  async codeGraphGet(codeGraphId: string): Promise<CodeGraphDetail> {
    return this.post('/v3/code-graph/get', { code_graph_id: codeGraphId });
  }

  async codeGraphSync(codeGraphId: string): Promise<CodeGraphSyncResult> {
    return this.post('/v3/code-graph/sync', { code_graph_id: codeGraphId });
  }

  async codeGraphDelete(codeGraphIds: string[]): Promise<BatchDeleteResult> {
    return this.post('/v3/code-graph/delete', { code_graph_ids: codeGraphIds });
  }

  async codeGraphUpdateMeta(codeGraphId: string, patch: { repo_name?: string; summary?: string | null }): Promise<CodeGraphDetail> {
    return this.post('/v3/code-graph/update-meta', { code_graph_id: codeGraphId, ...patch });
  }

  async codeGraphQuery(codeGraphId: string, tool: string, params: Record<string, unknown>): Promise<CodeGraphToolResult> {
    return this.post(`/v3/code-graph/${tool}`, { code_graph_id: codeGraphId, ...params });
  }
}

/** 内核 HTTP 响应信封（与 /v3/meta/* 一致）。 */

export interface MetaEnvelope<T = unknown> {
  code: number;
  message: string;
  request_id: string;
  data: T;
}

/** envelope.code → HTTP status（§4.8.2）：0→200；400–599→code；其余→502。 */
export function mapHttpStatusFromEnvelopeCode(code: number): number {
  if (code >= 400 && code < 600) return code;
  if (code === 0) return 200;
  return 502;
}

/**
 * 记忆内核 v3 `/v3/meta/*` 全局 HTTP 头（与 tdai-memory-plugin 对齐）。
 * Control 面板入站校验与出站转发均使用同一套名称。
 */
export const META_HEADER_SERVICE_ID = 'x-tdai-service-id';
export const META_HEADER_USER_KEY = 'x-tdai-user-key';
export const META_HEADER_REQUEST_ID = 'x-request-id';

/**
 * Knowledge RPC 端口 — Wiki（15 端点）+ Code-Graph（13 端点）。
 *
 * 对齐 docs/knowledge/knowledge-api.yaml（07/08/11 定稿）。管控对
 * wiki/code-graph 不持久化；UI 触发的操作通过该端口直连 core。
 *
 * 寻址规则（与 yaml 严格一致）：
 *  - create / list / *write / *rm 携带 IdFields（team_id 必传，user_id 可选）；
 *  - get / ingest / delete / *ls / *read / graph / search 及全部 code-graph
 *    查询端点仅以资产 id（wiki_id / code_graph_id）寻址，不再传
 *    team/agent/user/task ID（归属由内核侧通过复合键解析）。
 */

// ── Wiki ──

export interface WikiDetail {
  wiki_id: string;
  team_id: string;
  name: string;
  service_url: string | null;
  summary: string | null;
  status: 'draft' | 'pending' | 'processing' | 'ready' | 'failed';
  internal_status?: string | null;
  sync_error: string | null;
  version: string;
  owner_user_id: string | null;
  page_count: number | null;
  last_sync_at: string | null;
  created_at: string;
  updated_at: string;
}

export interface WikiListResult {
  items: WikiDetail[];
  total: number;
}

export interface WikiIngestResult {
  wiki_id: string;
  status: string;
}

/** raw 素材文件项（来自 `raw/sources/` 文件系统 stat）。 */
export interface RawFileEntry {
  filename: string;
  size: number;
  uploaded_at: string;
}

/** processed page 项（来自 `wiki/` 下 ingest 生成的页面）。 */
export interface PageEntry {
  id: string;
  title: string;
  type: string;
  path: string;
  locked?: boolean;
}

export interface WikiRawReadItem {
  filename: string;
  content?: string;
  not_found?: boolean;
}

export interface WikiRawWriteFile {
  filename: string;
  content: string;
}

export interface WikiRawWriteItem {
  filename: string;
  size: number;
}

export interface WikiRawRmResult {
  deleted_files: string[];
  deleted_pages: string[];
  rewritten_pages: number;
}

export interface WikiPageReadItem {
  ref: string;
  content?: string;
  not_found?: boolean;
}

export interface WikiPageWriteItem {
  ref: string;
  content: string;
}

export interface WikiPageWriteResultItem {
  ref: string;
  locked_injected?: boolean;
}

export interface WikiPageRmResult {
  deleted_pages: string[];
  rewritten_files: number;
}

export interface WikiGraphData {
  nodes: any[];
  edges: any[];
  communities?: any[];
}

export interface WikiSearchResult {
  results: Array<{ path: string; title: string; snippet: string; score: number; type: string }>;
  count: number;
}

export interface BatchDeleteResult {
  deleted_ids: string[];
  failed: Array<{ id: string; reason: string }>;
}

// ── Code-Graph ──

export interface CodeGraphDetail {
  code_graph_id: string;
  team_id: string;
  repo_name: string;
  repo_url: string;
  branch: string;
  commit_hash: string | null;
  service_url: string | null;
  summary: string | null;
  status: 'pending' | 'processing' | 'ready' | 'failed';
  sync_error: string | null;
  version: string;
  owner_user_id: string | null;
  stats: { files: number; nodes: number; edges: number } | null;
  last_sync_at: string | null;
  created_at: string;
  updated_at: string;
}

export interface CodeGraphListResult {
  items: CodeGraphDetail[];
  total: number;
}

export interface CodeGraphSyncResult {
  code_graph_id: string;
  status: string;
}

export interface CodeGraphToolResult {
  text: string;
  isError: boolean;
}

// ── Port ──

export interface KnowledgeClientPort {
  // Wiki — 资产层（create/list 带 IdFields；get/ingest/delete 仅资产 id 寻址）
  wikiCreate(teamId: string, name: string, userId?: string): Promise<WikiDetail>;
  wikiGet(wikiId: string): Promise<WikiDetail>;
  wikiIngest(wikiId: string): Promise<WikiIngestResult>;
  wikiDelete(wikiIds: string[]): Promise<BatchDeleteResult>;
  wikiList(teamId: string, opts?: { status?: string; limit?: number; offset?: number }): Promise<WikiListResult>;
  wikiUpdateMeta(wikiId: string, patch: { name?: string; summary?: string | null }): Promise<WikiDetail>;

  // Wiki — raw 文件层（ls/read 仅资产 id；write/rm 带 IdFields）
  wikiRawLs(wikiId: string): Promise<{ items: RawFileEntry[] }>;
  wikiRawRead(wikiId: string, filenames: string[]): Promise<{ items: WikiRawReadItem[] }>;
  wikiRawWrite(teamId: string, wikiId: string, files: WikiRawWriteFile[], userId?: string): Promise<{ items: WikiRawWriteItem[] }>;
  wikiRawRm(teamId: string, wikiId: string, filenames: string[], userId?: string): Promise<WikiRawRmResult>;

  // Wiki — page 文件层（ls/read 仅资产 id；write/rm 带 IdFields）
  wikiPageLs(wikiId: string): Promise<{ items: PageEntry[] }>;
  wikiPageRead(wikiId: string, refs: string[]): Promise<{ items: WikiPageReadItem[] }>;
  wikiPageWrite(teamId: string, wikiId: string, pages: WikiPageWriteItem[], userId?: string): Promise<{ items: WikiPageWriteResultItem[] }>;
  wikiPageRm(teamId: string, wikiId: string, refs: string[], userId?: string): Promise<WikiPageRmResult>;

  // Wiki — 派生视图（仅资产 id 寻址）
  wikiGraph(wikiId: string): Promise<WikiGraphData>;
  wikiSearch(wikiId: string, query: string, limit?: number, graph?: { hop?: number; decay?: number; minScore?: number }): Promise<WikiSearchResult>;

  // Code-Graph（create/list 带 IdFields；get/sync/delete/查询 仅资产 id 寻址）
  codeGraphCreate(teamId: string, repoUrl: string, branch?: string, userId?: string, repoName?: string): Promise<CodeGraphDetail>;
  codeGraphList(teamId: string, opts?: { status?: string; limit?: number; offset?: number }): Promise<CodeGraphListResult>;
  codeGraphGet(codeGraphId: string): Promise<CodeGraphDetail>;
  codeGraphSync(codeGraphId: string): Promise<CodeGraphSyncResult>;
  codeGraphDelete(codeGraphIds: string[]): Promise<BatchDeleteResult>;
  codeGraphUpdateMeta(codeGraphId: string, patch: { repo_name?: string; summary?: string | null }): Promise<CodeGraphDetail>;
  codeGraphQuery(codeGraphId: string, tool: string, params: Record<string, unknown>): Promise<CodeGraphToolResult>;
}

import type { MetaEnvelope } from '../envelope.js';
import type { MetaCallContext } from '../types.js';

/**
 * 内核 /v3/skill/* 数据面透明代理端口。
 * 与 MetaKernelPort 同形，但转发到 /v3/skill/{action} 而非 /v3/meta/{action}。
 */
export interface SkillKernelPort {
  invoke(action: string, body: Record<string, unknown>, ctx: MetaCallContext): Promise<MetaEnvelope>;
}

/**
 * 记忆内核 v3 元数据 HTTP fetch（Panel 专用）。
 */
import { randomUUID } from 'node:crypto';
import type { Logger } from '../infra/logger.js';
import type { MetaEnvelope } from './envelope.js';
import { mapHttpStatusFromEnvelopeCode } from './envelope.js';
import {
  META_HEADER_REQUEST_ID,
  META_HEADER_SERVICE_ID,
  META_HEADER_USER_KEY,
} from './headers.js';

export { mapHttpStatusFromEnvelopeCode };

const SENSITIVE_KEYS = new Set([
  'password',
  'initial_password',
  'default_user_key',
  'user_key',
  'key_value',
  'granted_by_key',
  'owner_user_key',
  'creator_user_key',
  'authorization',
  'api_key',
  'token',
  'secret',
  'bearer',
]);
const MAX_LOG_FIELD_CHARS = 300;
const MAX_LOG_JSON_CHARS = 1200;

function maskSecret(value: string): string {
  if (!value) return '';
  if (value.length <= 8) return `${value}…`;
  return `${value.slice(0, 8)}…`;
}

function truncateString(value: string): string {
  if (value.length <= MAX_LOG_FIELD_CHARS) return value;
  return `${value.slice(0, MAX_LOG_FIELD_CHARS)}…[truncated ${value.length - MAX_LOG_FIELD_CHARS} chars]`;
}

function sanitizeMetaBody(value: unknown, depth = 0): unknown {
  if (depth > 8) return '[max_depth]';
  if (value === null || value === undefined) return value;
  if (typeof value === 'string') return truncateString(value);
  if (typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.map((item) => sanitizeMetaBody(item, depth + 1));
  const out: Record<string, unknown> = {};
  for (const [key, raw] of Object.entries(value as Record<string, unknown>)) {
    if (SENSITIVE_KEYS.has(key.toLowerCase())) {
      out[key] = typeof raw === 'string' && raw.length > 0 ? maskSecret(raw) : '[redacted]';
      continue;
    }
    out[key] = sanitizeMetaBody(raw, depth + 1);
  }
  return out;
}

function serializeForLog(value: unknown): string {
  try {
    const json = JSON.stringify(sanitizeMetaBody(value));
    if (json.length <= MAX_LOG_JSON_CHARS) return json;
    return `${json.slice(0, MAX_LOG_JSON_CHARS)}…[truncated ${json.length - MAX_LOG_JSON_CHARS} chars]`;
  } catch {
    return '[unserializable]';
  }
}

/** 内核 HTTP 调用失败（网络/超时/无效信封）。 */
export class KernelFetchError extends Error {
  constructor(
    readonly code: number,
    message: string,
  ) {
    super(message);
    this.name = 'KernelFetchError';
  }

  get httpStatus(): number {
    return mapHttpStatusFromEnvelopeCode(this.code);
  }
}

export interface MetaFetchConfig {
  endpoint: string;
  apiKey: string;
  serviceId: string;
  userKey?: string;
  timeoutMs?: number;
  logger?: Logger;
  /** 透传为 x-request-id；缺省则生成 UUID。 */
  requestId?: string;
}

interface RawEnvelope<T> {
  code: number;
  message?: string;
  request_id?: string;
  data?: T;
}

function logRemoteMeta(
  logger: Logger | undefined,
  phase: 'request' | 'response' | 'error',
  requestId: string,
  fields: Record<string, unknown>,
): void {
  if (!logger) return;
  const msg = `[${requestId}] api.remote.${phase}`;
  if (phase === 'error') {
    logger.warn(msg, fields);
    return;
  }
  logger.info(msg, fields);
}

/**
 * POST 记忆内核元数据路径，返回完整信封。
 * - mode=envelope：业务 code≠0 不抛错（透明代理用）
 * - mode=data：code≠0 抛 KernelFetchError
 */
export async function executeMetaFetch<T>(
  cfg: MetaFetchConfig,
  path: string,
  body: unknown,
  mode: 'data' | 'envelope',
): Promise<T> {
  const base = cfg.endpoint.replace(/\/+$/, '');
  const timeoutMs = cfg.timeoutMs ?? 15_000;
  const log = cfg.logger;
  const startedAt = Date.now();
  const reqId = cfg.requestId ?? randomUUID();
  logRemoteMeta(log, 'request', reqId, {
    path,
    serviceId: cfg.serviceId,
    request_id: reqId,
    requestBody: serializeForLog(body ?? {}),
  });
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      [META_HEADER_SERVICE_ID]: cfg.serviceId,
      [META_HEADER_REQUEST_ID]: reqId,
    };
    if (cfg.apiKey) headers.Authorization = `Bearer ${cfg.apiKey}`;
    if (cfg.userKey) headers[META_HEADER_USER_KEY] = cfg.userKey;
    const resp = await fetch(`${base}${path}`, {
      method: 'POST',
      headers,
      body: JSON.stringify(body ?? {}),
      signal: ctrl.signal,
    });
    const env = (await resp.json().catch(() => null)) as RawEnvelope<unknown> | null;
    if (!env || typeof env.code !== 'number') {
      const err = new KernelFetchError(502, `invalid envelope from ${path} (http ${resp.status})`);
      logRemoteMeta(log, 'error', reqId, {
        path,
        request_id: reqId,
        durationMs: Date.now() - startedAt,
        httpStatus: resp.status,
        error: err.message,
      });
      throw err;
    }
    const envelope: MetaEnvelope<unknown> = {
      code: env.code,
      message: env.message ?? (env.code === 0 ? 'ok' : `error ${env.code}`),
      request_id: env.request_id ?? reqId,
      data: (env.data ?? {}) as unknown,
    };
    if (mode === 'envelope') {
      if (env.code !== 0) {
        logRemoteMeta(log, 'error', envelope.request_id, {
          path,
          request_id: envelope.request_id,
          durationMs: Date.now() - startedAt,
          envelopeCode: env.code,
          envelopeMessage: envelope.message,
        });
      } else {
        logRemoteMeta(log, 'response', envelope.request_id, {
          path,
          durationMs: Date.now() - startedAt,
          request_id: envelope.request_id,
          responseBody: serializeForLog(env.data ?? {}),
        });
      }
      return envelope as T;
    }
    if (env.code !== 0) {
      const err = new KernelFetchError(env.code, envelope.message);
      logRemoteMeta(log, 'error', envelope.request_id, {
        path,
        request_id: envelope.request_id,
        durationMs: Date.now() - startedAt,
        envelopeCode: env.code,
        envelopeMessage: envelope.message,
        error: err.message,
      });
      throw err;
    }
    logRemoteMeta(log, 'response', envelope.request_id, {
      path,
      durationMs: Date.now() - startedAt,
      request_id: envelope.request_id,
      responseBody: serializeForLog(env.data ?? {}),
    });
    return (env.data ?? {}) as T;
  } catch (err) {
    if (err instanceof KernelFetchError) throw err;
    const isTimeout = (err as { name?: string }).name === 'AbortError';
    const message = isTimeout
      ? `remote metadata timeout at ${path}`
      : `remote metadata call failed at ${path}: ${(err as Error).message}`;
    const code = isTimeout ? 504 : 502;
    logRemoteMeta(log, 'error', reqId, {
      path,
      durationMs: Date.now() - startedAt,
      request_id: reqId,
      envelopeCode: code,
      error: message,
    });
    throw new KernelFetchError(code, message);
  } finally {
    clearTimeout(timer);
  }
}

