/**
 * ParticleWaveBackground — 明亮风格的点阵波纹动效背景（纯 Canvas，零外部依赖）。
 *
 * 视觉参考 React Bits 的 Particles / DotGrid：网格点阵 + 多层正弦波驱动的起伏，
 * 点的半径与透明度随波峰变化，形成"呼吸感"的柔和波纹。
 *
 * 为什么不直接装 React Bits 的包：
 *   其 Particles / DotGrid / Aurora 分别依赖 ogl / gsap / three，本项目均未安装。
 *   按 React Bits 官方推荐的 manual 方式（复制源码进项目）实现，避免新增运行时依赖
 *   与构建风险，同时保留完全可控的视觉调参能力。
 *
 * 实现要点：
 *   - devicePixelRatio 适配，避免高清屏发虚；
 *   - ResizeObserver 跟随容器尺寸，不监听 window 以免多实例互相干扰；
 *   - 尊重 prefers-reduced-motion：偏好减少动效时渲染静态一帧，不启动 rAF；
 *   - 组件卸载时取消 rAF 与 observer，无内存泄漏。
 */
import { useEffect, useRef } from 'react';

export interface ParticleWaveBackgroundProps {
  /** 点阵间距（px），越小越密。默认 26 */
  gap?: number;
  /** 点的基础半径（px）。默认 1.5 */
  dotRadius?: number;
  /** 点颜色，需为 `r, g, b` 形式（透明度由内部按波峰计算）。默认深灰蓝 */
  color?: string;
  /** 动画速度系数，默认 1 */
  speed?: number;
  /** 附加类名 */
  className?: string;
}

export default function ParticleWaveBackground({
  gap = 26,
  dotRadius = 1.5,
  color = '100, 116, 139',
  speed = 1,
  className,
}: ParticleWaveBackgroundProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let rafId = 0;
    let width = 0;
    let height = 0;
    let disposed = false;

    const reduceMotion =
      typeof window !== 'undefined' &&
      typeof window.matchMedia === 'function' &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    function resize() {
      const parent = canvas!.parentElement;
      if (!parent) return;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      width = parent.clientWidth;
      height = parent.clientHeight;
      canvas!.width = Math.max(1, Math.floor(width * dpr));
      canvas!.height = Math.max(1, Math.floor(height * dpr));
      canvas!.style.width = `${width}px`;
      canvas!.style.height = `${height}px`;
      // 用 setTransform 而非 scale，避免多次 resize 后缩放系数累积
      ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
    }

    /**
     * 渲染一帧。三层不同频率/相位的正弦波叠加，得到 [-1, 1] 的强度场；
     * 强度映射到点的半径与透明度，形成明暗起伏的点阵波纹。
     *
     * 参数取值说明：时间系数决定"看起来动得多快"。太小（<0.5）时单个波周期会长达
     * 十几秒，肉眼几乎判断不出在动、像一张静态图；这里取 0.65~1.15 让主波约 5 秒
     * 一个周期，既能明确看出流动感又不至于晃眼。
     */
    function draw(elapsedMs: number) {
      if (width <= 0 || height <= 0) return;
      const t = (elapsedMs / 1000) * speed;
      ctx!.clearRect(0, 0, width, height);

      const cols = Math.ceil(width / gap) + 1;
      const rows = Math.ceil(height / gap) + 1;

      for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
          const x = col * gap;
          const y = row * gap;
          // 归一化坐标让波形不随画布尺寸变形
          const nx = x / Math.max(width, 1);
          const ny = y / Math.max(height, 1);

          // 主波自右向左流动，另两层不同角度叠加，避免出现规则条纹
          const wave =
            Math.sin(nx * 7.5 - t * 1.15) * 0.45 +
            Math.sin(ny * 5.5 + t * 0.75) * 0.28 +
            Math.sin((nx * 3.2 + ny * 4.1) + t * 0.95) * 0.27;

          // wave ∈ 约 [-1, 1] → intensity ∈ [0, 1]
          const intensity = (wave + 1) / 2;
          // 幂次收缩暗部，让波峰更突出、波谷更干净，明暗对比更清晰
          const shaped = Math.pow(intensity, 1.4);
          // 顶部略淡、底部略实，增强"光从上方来"的明亮感
          const depth = 0.6 + ny * 0.4;
          const alpha = (0.08 + shaped * 0.5) * depth;
          const radius = dotRadius * (0.45 + shaped * 1.15);
          if (alpha <= 0.01 || radius <= 0.05) continue;

          ctx!.beginPath();
          ctx!.fillStyle = `rgba(${color}, ${alpha.toFixed(3)})`;
          ctx!.arc(x, y, radius, 0, Math.PI * 2);
          ctx!.fill();
        }
      }
    }

    function loop(now: number) {
      if (disposed) return;
      draw(now);
      rafId = window.requestAnimationFrame(loop);
    }

    resize();

    const observer = new ResizeObserver(() => {
      resize();
      // 偏好减少动效时不跑 rAF，resize 后需手动补画一帧
      if (reduceMotion) draw(0);
    });
    const parent = canvas.parentElement;
    if (parent) observer.observe(parent);

    if (reduceMotion) {
      draw(0);
    } else {
      rafId = window.requestAnimationFrame(loop);
    }

    return () => {
      disposed = true;
      if (rafId) window.cancelAnimationFrame(rafId);
      observer.disconnect();
    };
  }, [gap, dotRadius, color, speed]);

  return <canvas ref={canvasRef} className={className} aria-hidden="true" />;
}

/**
 * RouteGuards — 路由级权限守卫
 *
 * - ResourceGuard：admin 角色访问资源页 → 重定向到工作台
 * - MemberManageGuard：member 角色访问成员管理页 → 重定向到工作台
 */
import { type ReactNode, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCurrentRole, type TeamRole } from '@/services/useCurrentRole';

/** 资源管理页面守卫：admin 不可见 */
export function ResourceGuard({ children }: { children: ReactNode }) {
  const role = useCurrentRole();
  const navigate = useNavigate();
  const blocked = role === 'admin';

  useEffect(() => {
    if (blocked) navigate('/', { replace: true });
  }, [blocked, navigate]);

  return blocked ? null : <>{children}</>;
}

/** 成员管理守卫：reviewer 不可见（admin / member 可见）。
 *  member 可查看成员列表、添加已有成员，但新建成员/删除成员/新建删除 Team
 *  的按钮在 TeamManagementPanel 内部按角色收敛。 */
export function MemberManageGuard({ children, allowedRoles }: {
  children: ReactNode;
  allowedRoles?: TeamRole[];
}) {
  const role = useCurrentRole();
  const navigate = useNavigate();
  const allowed = allowedRoles ?? ['admin', 'member'];
  const blocked = role !== null && !allowed.includes(role);

  useEffect(() => {
    if (blocked) navigate('/', { replace: true });
  }, [blocked, navigate]);

  return blocked ? null : <>{children}</>;
}

/**
 * SettingsDialog — 全局设置弹窗（从顶栏⚙图标触发）。
 *
 * 当前只有一个 Tab：「权限管理」— 控制资源管理模块的开关
 * （Wiki / Code / Skill / Chat_Memory），防止未稳定使用的模块
 * 被注入内核运行。
 *
 * 后续可在 TABS 数组里追加其他 Tab（如通知、偏好设置等）。
 *
 */
import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Alert,
  Switch,
  Text,
  Tag,
  Modal,
} from 'tea-component';
import {
  BooksIcon,
  CodeIcon,
  ToolsIcon,
  ChatIcon,
} from 'tea-icons-react';
import { userConfigApi, type AssetCapabilityKey } from '@/lib/teamApi';
import { tea } from '@/lib/tea-bridge';

// ===== 资源模块 =====

interface ResourceModule {
  id: string;
  paramKey: AssetCapabilityKey;
  labelKey: string;
  descKey: string;
  icon: JSX.Element;
}

const RESOURCE_MODULES: ResourceModule[] = [
  {
    id: 'wiki',
    paramKey: 'llm_wiki.enabled',
    labelKey: 'settings.module.wiki',
    descKey: 'settings.module.wiki.desc',
    icon: <BooksIcon size={16} />,
  },
  {
    id: 'code',
    paramKey: 'code_graph.enabled',
    labelKey: 'settings.module.code',
    descKey: 'settings.module.code.desc',
    icon: <CodeIcon size={16} />,
  },
  {
    id: 'skill',
    paramKey: 'skill.enabled',
    labelKey: 'settings.module.skill',
    descKey: 'settings.module.skill.desc',
    icon: <ToolsIcon size={16} />,
  },
  {
    id: 'chat_memory',
    paramKey: 'chat_memory.enabled',
    labelKey: 'settings.module.chatMemory',
    descKey: 'settings.module.chatMemory.desc',
    icon: <ChatIcon size={16} />,
  },
];

type SettingsTab = 'permissions';

export function SettingsDialog({ onClose }: { onClose: () => void }) {
  const { t } = useTranslation();
  const activeTab: SettingsTab = 'permissions';

  const [enabled, setEnabled] = useState<Record<string, boolean>>(() => ({
    wiki: true,
    code: true,
    skill: true,
    chat_memory: true,
  }));
  const [loading, setLoading] = useState(true);
  const [savingKey, setSavingKey] = useState<AssetCapabilityKey | null>(null);
  const [error, setError] = useState('');

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError('');
    userConfigApi.getAssetCapabilities()
      .then((cfg) => {
        if (cancelled) return;
        setEnabled({
          wiki: cfg['llm_wiki.enabled'],
          code: cfg['code_graph.enabled'],
          skill: cfg['skill.enabled'],
          chat_memory: cfg['chat_memory.enabled'],
        });
      })
      .catch((e) => {
        if (!cancelled) setError(e instanceof Error ? e.message : String(e));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => { cancelled = true; };
  }, []);

  async function handleToggle(mod: ResourceModule, next: boolean) {
    const previous = enabled[mod.id];
    setEnabled((prev) => ({ ...prev, [mod.id]: next }));
    setSavingKey(mod.paramKey);
    setError('');
    try {
      await userConfigApi.setAssetCapability(mod.paramKey, next);
      tea.notify.success(t(next ? 'settings.notify.enabled' : 'settings.notify.disabled', { label: t(mod.labelKey) }));
    } catch (e) {
      setEnabled((prev) => ({ ...prev, [mod.id]: previous }));
      const msg = e instanceof Error ? e.message : String(e);
      setError(msg);
      tea.notify.error(t('settings.notify.saveFailed', { msg }));
    } finally {
      setSavingKey(null);
    }
  }

  return (
    <Modal visible caption={t('settings.caption')} size="m" onClose={onClose}>
      <Modal.Body>
      {activeTab === 'permissions' && (
        <div>
          <div style={{ paddingTop: 4 }}>
            <Text theme="label" style={{ display: 'block', marginBottom: 8 }}>
              {t('settings.title')}
            </Text>
            <Text theme="weak" style={{ display: 'block', marginBottom: 16, fontSize: 12 }}>
              {t('settings.desc')}
            </Text>
            {error && <Alert type="error" style={{ marginBottom: 12 }}>{error}</Alert>}
            {loading && <Alert type="info" style={{ marginBottom: 12 }}>{t('settings.loadingConfig')}</Alert>}

            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
              {RESOURCE_MODULES.map((mod) => (
                <div
                  key={mod.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    padding: '10px 12px',
                    border: '1px solid var(--tea-color-border-primary-default)',
                    borderRadius: 6,
                    background: enabled[mod.id]
                      ? 'var(--tea-color-bg-brand-lighten-default)'
                      : 'var(--tea-color-bg-primary-default)',
                    transition: 'background-color 0.15s',
                  }}
                >
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10, minWidth: 0 }}>
                    <span style={{ color: 'var(--tea-color-text-secondary)', flexShrink: 0 }}>
                      {mod.icon}
                    </span>
                    <div style={{ minWidth: 0 }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                        <Text style={{ fontSize: 13, fontWeight: 500 }}>
                          {t(mod.labelKey)}
                        </Text>
                        {savingKey === mod.paramKey ? (
                          <Tag theme="warning" variant="soft" size="sm">{t('settings.tag.saving')}</Tag>
                        ) : enabled[mod.id] ? (
                          <Tag theme="success" variant="soft" size="sm">{t('settings.tag.enabled')}</Tag>
                        ) : (
                          <Tag theme="default" variant="soft" size="sm">{t('settings.tag.disabled')}</Tag>
                        )}
                      </div>
                      <Text theme="weak" style={{ fontSize: 12, marginTop: 2, display: 'block' }}>
                        {t(mod.descKey)}
                      </Text>
                    </div>
                  </div>
                  <Switch
                    value={enabled[mod.id]}
                    disabled={loading || savingKey === mod.paramKey}
                    onChange={(v) => void handleToggle(mod, v)}
                  />
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
      </Modal.Body>
    </Modal>
  );
}

/**
 * StatusTag —— 通用「状态标签」组件。
 *
 * 此前 Wiki（WikiStatusBadge）与 Code（statusLabel）各自实现 status → Tea Tag
 * 的渲染（theme + variant="soft" + 可选 hint），结构完全一致。这里统一收口，
 * 各资产页只负责提供「status → label/theme」的业务映射。
 */
import { Tag } from 'tea-component';

export type StatusTheme = 'default' | 'success' | 'warning' | 'error';

export function StatusTag({
  label,
  theme = 'default',
  hint,
  className,
}: {
  /** 已翻译的状态文案（或原始 status 兜底） */
  label: string;
  /** Tea Tag 语义主题（soft 变体） */
  theme?: StatusTheme;
  /** 可选的状态补充说明（如 processing 时的“处理中，可能需要几分钟”） */
  hint?: string;
  /** 外层容器 class（默认 _asset-status） */
  className?: string;
}) {
  return (
    <span className={className ?? '_asset-status'}>
      <Tag theme={theme} variant="soft" size="sm">
        {label}
      </Tag>
      {hint && <span className="_asset-status-hint">{hint}</span>}
    </span>
  );
}

/**
 * AllocateAssetDialog — 通用「资产分配到 Agent」弹窗。
 *
 * 与 AllocateSkillDialog 视觉对齐，但不限于 skill：用 assetType + assetLabel
 * 参数化标题，支持 wiki / code_graph / chat_memory 等任何挂载到 agent 固定
 * 资产的场景。
 */

import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Alert, Button, Form, Modal, Select, Tag } from 'tea-component';
import { tea } from '@/lib/tea-bridge';
import './allocate-dialog.css';

export type AllocateAssetType = 'skill' | 'llm_wiki' | 'code_graph' | 'chat_memory';

export default function AllocateAssetDialog(props: {
  assetType: AllocateAssetType;
  assetLabel: string;
  agents: Array<{ id: string; name: string }>;
  team?: { team_id: string; name: string } | null;
  onClose: () => void;
  onAllocate: (agentId: string) => Promise<void> | void;
}) {
  const { t } = useTranslation();
  const [agentId, setAgentId] = useState(props.agents[0]?.id ?? '');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const typeLabelMap: Record<AllocateAssetType, string> = {
    skill: t('allocAsset.skill'),
    llm_wiki: t('allocAsset.wiki'),
    code_graph: t('allocAsset.codeGraph'),
    chat_memory: t('allocAsset.memory'),
  };
  const typeLabel = typeLabelMap[props.assetType];

  async function submit(): Promise<void> {
    if (!agentId) {
      setError(t('allocAsset.error.noAgent'));
      return;
    }
    setError(null);
    setSubmitting(true);
    try {
      await props.onAllocate(agentId);
      tea.notify.success(t('allocAsset.notify.success', { label: props.assetLabel, agent: agentId }));
      props.onClose();
    } catch (err) {
      tea.notify.error(err);
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <Modal visible caption={t('allocAsset.caption', { type: typeLabel })} size="s" onClose={props.onClose} disableEscape={submitting}>
      <Modal.Body>
        <Form>
          {props.team && (
            <Form.Item label={t('allocAsset.team')}>
              <Form.Text>{props.team.name} <Tag size="sm">{props.team.team_id}</Tag></Form.Text>
            </Form.Item>
          )}
          <Form.Item label={t('allocAsset.asset')} extra={t('allocAsset.asset.extra')}>
            <Form.Text>{props.assetLabel}</Form.Text>
          </Form.Item>
          <Form.Item label={t('allocAsset.agent')} required>
            <Select
              size="full"
              value={agentId}
              onChange={setAgentId}
              placeholder={props.agents.length === 0 ? t('allocAsset.agent.placeholder.empty') : t('allocAsset.agent.placeholder.select')}
              options={props.agents.map((a) => ({ value: a.id, text: `${a.id} · ${a.name}` }))}
              disabled={props.agents.length === 0}
            />
          </Form.Item>
          {error && <Form.Item><Alert type="error">{error}</Alert></Form.Item>}
        </Form>
      </Modal.Body>
      <Modal.Footer>
        <Button type="primary" onClick={() => void submit()} disabled={submitting || !agentId} loading={submitting}>{t('allocAsset.submit')}</Button>
        <Button onClick={props.onClose} disabled={submitting}>{t('allocAsset.cancel')}</Button>
      </Modal.Footer>
    </Modal>
  );
}

/**
 * AssetListPanel — 资产管理页通用左侧列表面板。
 *
 * 统一 Skills / Memory 等资产页的左侧导航列表容器，提供：
 *   - 面板标题 + 条数统计
 *   - 加载骨架屏
 *   - 空态提示
 *   - 选中态管理（浅品牌底色，无边框）
 *   - 统一的列表项 4 行结构（标题 / 描述 / 徽章 / 元信息）
 *
 * 列表项内容通过 render prop 由各资产页自行填充，
 * 保持容器与业务解耦。
 */

import type { ReactNode } from 'react';
import './asset-list-panel.css';

/* ── 面板 ── */

interface AssetListPanelProps<T> {
  /** 面板标题 */
  title: ReactNode;
  /** 条数统计文本 */
  count?: ReactNode;
  /** 是否加载中 */
  loading?: boolean;
  /** 数据项 */
  items: T[];
  /** 当前选中项 id */
  selectedId?: string | null;
  /** 从数据项提取唯一 id */
  getItemId: (item: T) => string;
  /** 选中回调 */
  onSelect: (item: T) => void;
  /** 渲染单个列表项内容（不含外层选中态容器） */
  renderItem: (item: T, isSelected: boolean) => ReactNode;
  /** 判断某项是否禁用（不可点击） */
  isItemDisabled?: (item: T) => boolean;
  /** 空态文本 */
  emptyText?: ReactNode;
}

export function AssetListPanel<T>({
  title,
  count,
  loading,
  items,
  selectedId,
  getItemId,
  onSelect,
  renderItem,
  isItemDisabled,
  emptyText,
}: AssetListPanelProps<T>) {
  return (
    <div className="_alp">
      <div className="_alp-header">
        <span className="_alp-title">{title}</span>
        {!loading && count != null && <span className="_alp-count">{count}</span>}
      </div>

      {loading ? (
        <div className="_alp-items">
          {[0, 1, 2, 3].map((i) => (
            <div key={i} className="_alp-item _alp-skeleton">
              <div className="_alp-skeleton-line _alp-skeleton-primary" />
              <div className="_alp-skeleton-line _alp-skeleton-secondary" />
            </div>
          ))}
        </div>
      ) : items.length === 0 ? (
        <div className="_alp-empty">{emptyText}</div>
      ) : (
        <ul className="_alp-items">
          {items.map((item) => {
            const id = getItemId(item);
            const isSelected = selectedId === id;
            const disabled = isItemDisabled?.(item) ?? false;
            return (
              <li
                key={id}
                className={[
                  '_alp-item',
                  isSelected ? '_alp-item--selected' : '',
                  disabled ? '_alp-item--disabled' : '',
                ]
                  .filter(Boolean)
                  .join(' ')}
              >
                <button
                  type="button"
                  className="_alp-item-btn"
                  onClick={() => !disabled && onSelect(item)}
                  disabled={disabled}
                >
                  {renderItem(item, isSelected)}
                </button>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

