/**
 * AssetSplitLayout — 资产管理页通用分栏布局。
 *
 * 统一 Skills / Memory 等资产页的「左侧列表 + 右侧详情」分栏结构：
 * - 左右宽度可拖拽调节，比例记忆到 localStorage（同一浏览器下次保留）
 * - 右侧详情设最大高度，内容超出时在详情区内部滚动，不撑开外层页面高度
 *   （外层容器不出现滚动条）
 */

import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import './asset-split-layout.css';

interface AssetSplitLayoutProps {
  sidebar: ReactNode;
  detail: ReactNode;
  /** 拖拽宽度的持久化 key（不同页面互不干扰）；不传则不持久化 */
  storageKey?: string;
}

const MIN_SIDEBAR = 220;
const MAX_SIDEBAR = 480;
const DEFAULT_SIDEBAR = 280;

function clampWidth(w: number): number {
  return Math.min(MAX_SIDEBAR, Math.max(MIN_SIDEBAR, w));
}

function readStoredWidth(storageKey?: string): number {
  if (!storageKey) return DEFAULT_SIDEBAR;
  try {
    const raw = window.localStorage.getItem(storageKey);
    const parsed = raw ? Number(raw) : NaN;
    return Number.isFinite(parsed) ? clampWidth(parsed) : DEFAULT_SIDEBAR;
  } catch {
    return DEFAULT_SIDEBAR;
  }
}

export function AssetSplitLayout({ sidebar, detail, storageKey }: AssetSplitLayoutProps) {
  const { t } = useTranslation();
  const [sidebarWidth, setSidebarWidth] = useState<number>(() => readStoredWidth(storageKey));
  const [dragging, setDragging] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  // 拖拽过程：以容器左边界为基准计算左栏宽度，限制在 [MIN, MAX] 内
  useEffect(() => {
    if (!dragging) return;
    const onMove = (e: MouseEvent) => {
      const container = containerRef.current;
      if (!container) return;
      const rect = container.getBoundingClientRect();
      setSidebarWidth(clampWidth(e.clientX - rect.left));
    };
    const onUp = () => setDragging(false);
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
    // 拖拽时禁用文本选中，避免选到列表内容
    const prevUserSelect = document.body.style.userSelect;
    document.body.style.userSelect = 'none';
    return () => {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
      document.body.style.userSelect = prevUserSelect;
    };
  }, [dragging]);

  // 拖拽结束后持久化最终宽度
  useEffect(() => {
    if (dragging || !storageKey) return;
    try {
      window.localStorage.setItem(storageKey, String(sidebarWidth));
    } catch {
      /* localStorage 不可用时静默忽略，仅影响记忆能力 */
    }
  }, [dragging, sidebarWidth, storageKey]);

  const onHandleMouseDown = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setDragging(true);
  }, []);

  return (
    <div
      ref={containerRef}
      className={`_asset-split${dragging ? ' _asset-split--dragging' : ''}`}
      style={{ gridTemplateColumns: `${sidebarWidth}px 6px minmax(0, 1fr)` }}
    >
      <section className="_asset-split-sidebar">{sidebar}</section>
      <button
        type="button"
        className="_asset-split-resizer"
        aria-label={t('assetSplit.resizer.label')}
        onMouseDown={onHandleMouseDown}
        onKeyDown={(e) => {
          // 键盘可达：左右箭头以 16px 步进调整左栏宽度
          if (e.key === 'ArrowLeft') {
            e.preventDefault();
            setSidebarWidth((w) => clampWidth(w - 16));
          } else if (e.key === 'ArrowRight') {
            e.preventDefault();
            setSidebarWidth((w) => clampWidth(w + 16));
          }
        }}
      >
        <span className="_asset-split-resizer-bar" />
      </button>
      <section className="_asset-split-detail">{detail}</section>
    </div>
  );
}

/**
 * UserBadge —— 通用「用户徽章」组件。
 *
 * 此前 Skills（SkillOwnerTag）与 Memory（UploaderBadge）各自实现了相同的
 * 「AssetBadge + UserIcon + displayName 展示 + 当前用户追加“你”标记」结构。
 * 这里统一收口；displayName 通过 useUserDisplayName 全局缓存获取，title /
 * youText / getTitle 由调用方注入以兼容各页 i18n。
 */
import { UserIcon } from 'tea-icons-react';
import { useUserDisplayName } from '@/services/user-profile-store';
import { AssetBadge, AssetBadgeYou } from './AssetListPanel';

export function UserBadge({
  userId,
  isCurrentUser,
  title,
  youText,
  getTitle,
}: {
  userId: string;
  /** 是否为当前用户（决定是否追加“你”标记） */
  isCurrentUser: boolean;
  /** hover 提示文本；默认 userId。若需基于 displayName 拼装（如 skills），用 getTitle */
  title?: string;
  /** “你”标记文案 */
  youText: string;
  /** 基于 displayName 生成 hover 提示的回调（优先于 title） */
  getTitle?: (displayName: string) => string;
}) {
  const displayName = useUserDisplayName(userId);
  const resolvedTitle = getTitle
    ? getTitle(displayName || userId)
    : (title ?? userId);
  return (
    <AssetBadge icon={<UserIcon size={10} />} title={resolvedTitle}>
      {displayName || userId}
      {isCurrentUser && <AssetBadgeYou>{youText}</AssetBadgeYou>}
    </AssetBadge>
  );
}

/**
 * AgentEditDialog —— 编辑/查看 Agent 弹窗。
 *
 * 编辑范围约定：
 *   - 名称、一句话描述、角色 prompt / 规则 prompt 可编辑保存。
 *   - 资源能力可直接在本弹窗勾选/解绑并保存：
 *     · Wiki 知识库 / CodeGraph → allocate / unbind（引用绑定，增量 diff）
 *     · Chat Memory → setAgentFixed（全量覆盖，天然处理增删；不含 agent 自身 memory）
 *     · Skill → 仍只读展示。skill 的「挂载」语义是 fork 出 owner=该 agent 的独立副本
 *       （见 skillApi.forkToAgent），在编辑弹窗里做增删副本涉及乐观锁与归档，
 *       风险高，本期不放开，保留在「创建 Agent」/技能管理页维护。
 *
 * 资源已绑定态读真实绑定源（skill 表 owner_agent_id + agent-fixed-asset 表），与运行时一致。
 */

import { useState, useMemo, useEffect } from 'react';
import { Button, Input, Modal } from 'tea-component';
import { useTranslation } from 'react-i18next';
import { ToolsIcon, CodeIcon, BooksIcon, ChatIcon } from 'tea-icons-react';
import { type Agent as StoreAgent, invalidateBackendCache, writeAgentUiMeta } from '@/services';
import { agentsApi, skillApi, chatMemoryApi } from '@/lib/teamApi';
import { knowledgeApi } from '@/lib/api/knowledge-api';
import { tea } from '@/lib/tea-bridge';
import { useTeamAssets, syncChatMemoryBindings } from './useAgentAssets';
import { LightField, CollapseGroup, AssetCheckList } from './shared';

export default function AgentEditDialog({
  agent,
  onClose,
}: {
  agent: StoreAgent;
  onClose: () => void;
}) {
  const selfChatMemoryId = `chat_memory-${agent.team_id}-${agent.agent_id}`;
  const [name, setName] = useState(agent.name);
  const [description, setDescription] = useState(agent.description);
  const [rolePrompt, setRolePrompt] = useState(agent.role_prompt);
  const [rulesPrompt, setRulesPrompt] = useState(agent.rules_prompt);
  const [savingPrompt, setSavingPrompt] = useState(false);

  const [codeGraphOpen, setCodeGraphOpen] = useState(false);
  const [wikiOpen, setWikiOpen] = useState(false);
  const [skillsOpen, setSkillsOpen] = useState(false);
  const [memoryOpen, setMemoryOpen] = useState(false);

  // 资源可编辑：用真实绑定源填充初始勾选态。
  const [skills, setSkills] = useState<string[]>([]);
  const [codeGraphs, setCodeGraphs] = useState<string[]>([]);
  const [llmWikis, setLlmWikis] = useState<string[]>([]);
  const [chatMemories, setChatMemories] = useState<string[]>([selfChatMemoryId]);
  // 初始绑定快照：保存时与当前勾选对比算增删 diff（skill 只读不参与 diff）。
  const [initialCodeGraphs, setInitialCodeGraphs] = useState<string[]>([]);
  const [initialWikis, setInitialWikis] = useState<string[]>([]);
  const [initialChatMemories, setInitialChatMemories] = useState<string[]>([selfChatMemoryId]);
  const [savingAssets, setSavingAssets] = useState(false);
  // agent 真实拥有但可能不在 team 资产池的绑定项（如 skill fork 副本、借入的 memory），
  // 注入资产池以保证「已绑定」项都能显示、数量与 list 卡片一致。
  const [realSkillItems, setRealSkillItems] = useState<Array<{ key: string; title: string }>>([]);
  const [realCodeGraphIds, setRealCodeGraphIds] = useState<string[]>([]);
  const [realWikiIds, setRealWikiIds] = useState<string[]>([]);
  const [realChatMemoryIds, setRealChatMemoryIds] = useState<string[]>([]);
  const [realBindingsLoaded, setRealBindingsLoaded] = useState(false);

  const assets = useTeamAssets(agent.team_id);
  const { t } = useTranslation();

  // 加载态编排：
  //   assets.loading —— 团队资产池在加载（4 个折叠组都用资产池数据）
  //   realBindingsLoaded —— 真实绑定源已就绪（决定折叠组 count 是否可信）
  // 任一未就绪 → 折叠组走骨架占位，避免「已选 0/共 0 → 真实数字」跳变。
  const bindingsLoading = assets.loading || !realBindingsLoaded;

  function injectBound<T extends { key: string; title: string; group: string; slug: string }>(
    pool: T[],
    boundIds: string[],
    group: string,
  ): T[] {
    const map = new Map(pool.map((item) => [item.key, item]));
    for (const id of boundIds) {
      if (!map.has(id)) {
        map.set(id, { key: id, title: id, group, slug: id } as T);
      }
    }
    return Array.from(map.values());
  }

  const skillsAssets = useMemo(() => {
    const map = new Map(assets.skills.map((item) => [item.key, item]));
    for (const it of realSkillItems) {
      if (!map.has(it.key)) {
        map.set(it.key, { key: it.key, title: it.title, group: 'SKILL', slug: it.key });
      }
    }
    return Array.from(map.values());
  }, [assets.skills, realSkillItems]);
  const codeGraphAssets = useMemo(
    () => injectBound(assets.codeGraphs, realCodeGraphIds, 'CODE'),
    [assets.codeGraphs, realCodeGraphIds],
  );
  const wikiAssets = useMemo(
    () => injectBound(assets.wikis, realWikiIds, 'WIKI'),
    [assets.wikis, realWikiIds],
  );
  const memoryAssets = useMemo(() => {
    const map = new Map(assets.chatMemories.map((item) => [item.key, item]));
    if (!map.has(selfChatMemoryId)) {
      map.set(selfChatMemoryId, {
        key: selfChatMemoryId,
        title: agent.name,
        group: 'MEMORY',
        slug: selfChatMemoryId,
      });
    }
    for (const id of realChatMemoryIds) {
      if (!map.has(id)) {
        map.set(id, { key: id, title: id, group: 'MEMORY', slug: id });
      }
    }
    return Array.from(map.values());
  }, [agent.name, realChatMemoryIds, assets.chatMemories, selfChatMemoryId]);

  // 可编辑：展示团队资产池全集（含已绑定与未绑定），供用户勾选/取消。
  // skill 仍只读，只展示已绑定项（fork 语义，见文件头说明）。
  const boundSkills = useMemo(
    () => skillsAssets.filter((a) => skills.includes(a.key)),
    [skillsAssets, skills],
  );

  function toggle(list: string[], setList: (v: string[]) => void, key: string) {
    setList(list.includes(key) ? list.filter((k) => k !== key) : [...list, key]);
  }

  // 资产是否相对初始绑定发生变化（用于启用保存按钮）
  const sameSet = (a: string[], b: string[]) =>
    a.length === b.length && a.every((x) => b.includes(x));
  const assetsChanged =
    !sameSet(codeGraphs, initialCodeGraphs) ||
    !sameSet(llmWikis, initialWikis) ||
    !sameSet(chatMemories, initialChatMemories);

  const promptChanged =
    name !== agent.name ||
    description !== agent.description ||
    rolePrompt !== agent.role_prompt ||
    rulesPrompt !== agent.rules_prompt;
  const agentChanged = promptChanged || assetsChanged;
  const saving = savingPrompt || savingAssets;

  /** 保存资产绑定 diff：wiki / code_graph 走 allocate/unbind，chat_memory 走全量 setAgentFixed。 */
  async function saveAssetBindings() {
    // Wiki
    for (const id of llmWikis.filter((x) => !initialWikis.includes(x))) {
      await knowledgeApi.wiki.allocate(agent.team_id, id, agent.agent_id);
    }
    for (const id of initialWikis.filter((x) => !llmWikis.includes(x))) {
      await knowledgeApi.wiki.unbind(id, agent.agent_id);
    }
    // CodeGraph
    for (const id of codeGraphs.filter((x) => !initialCodeGraphs.includes(x))) {
      await knowledgeApi.code.allocate(agent.team_id, id, agent.agent_id);
    }
    for (const id of initialCodeGraphs.filter((x) => !codeGraphs.includes(x))) {
      await knowledgeApi.code.unbind(id, agent.agent_id);
    }
    // Chat Memory：全量覆盖（内部会过滤自身 memory、校验借入上限）
    if (!sameSet(chatMemories, initialChatMemories)) {
      await syncChatMemoryBindings(agent.team_id, agent.agent_id, chatMemories);
    }
  }

  async function saveAgent() {
    if (!agentChanged || saving) return;
    const nextName = name.trim();
    const nextDescription = description.trim();
    const nextRolePrompt = rolePrompt.trim();
    const nextRulesPrompt = rulesPrompt.trim();
    if (!nextName) {
      tea.notify.error(t('agentEdit.notify.nameRequired'));
      return;
    }
    setSavingPrompt(true);
    setSavingAssets(true);
    try {
      // 运行时使用 prompt 完整文本；metadata_json 保留两个字段的拆分，供前端再次编辑时恢复。
      if (promptChanged) {
        await agentsApi.update(agent.agent_id, {
          name: nextName,
          description: nextDescription,
          prompt: [nextRolePrompt, nextRulesPrompt].filter(Boolean).join('\n\n'),
          metadata_json: writeAgentUiMeta(agent.metadata_json, {
            role_prompt: nextRolePrompt,
            rules_prompt: nextRulesPrompt,
          }),
        });
      }
      if (assetsChanged) {
        await saveAssetBindings();
      }
      invalidateBackendCache();
      tea.notify.success(t('agentEdit.notify.saved'));
      onClose();
    } catch (error) {
      tea.notify.error(
        t('agentEdit.notify.saveFailed', {
          msg: error instanceof Error ? error.message : String(error),
        }),
      );
    } finally {
      setSavingPrompt(false);
      setSavingAssets(false);
    }
  }

  useEffect(() => {
    let cancelled = false;
    if (assets.loading || realBindingsLoaded)
      return () => {
        cancelled = true;
      };

    // 读真实绑定源（权威、与运行时一致），仅用于只读展示。
    Promise.allSettled([
      skillApi.listByAgent(agent.team_id, agent.agent_id),
      knowledgeApi.agentFixed(agent.agent_id),
      chatMemoryApi.agentFixed(agent.agent_id),
    ])
      .then(([skillResult, knowledgeResult, chatResult]) => {
        if (cancelled) return;

        const skillItems = skillResult.status === 'fulfilled' ? skillResult.value : [];
        const nextSkillItems = skillItems.map((s) => ({
          key: s.skill_id,
          title: s.name || s.skill_id,
        }));
        setRealSkillItems(nextSkillItems);
        setSkills(nextSkillItems.map((s) => s.key));

        const knowledgeItems = knowledgeResult.status === 'fulfilled' ? knowledgeResult.value : [];
        const nextCodeGraphs = Array.from(
          new Set(
            knowledgeItems
              .filter((it) => it.asset_type === 'code_graph')
              .map((it) => it.knowledge_id),
          ),
        );
        const nextLlmWikis = Array.from(
          new Set(
            knowledgeItems
              .filter((it) => it.asset_type === 'llm_wiki')
              .map((it) => it.knowledge_id),
          ),
        );
        setRealCodeGraphIds(nextCodeGraphs);
        setRealWikiIds(nextLlmWikis);
        setCodeGraphs(nextCodeGraphs);
        setLlmWikis(nextLlmWikis);
        setInitialCodeGraphs(nextCodeGraphs);
        setInitialWikis(nextLlmWikis);

        const chatItems = chatResult.status === 'fulfilled' ? (chatResult.value.items ?? []) : [];
        const nextChatMemories = Array.from(
          new Set([selfChatMemoryId, ...chatItems.map((it) => it.id)]),
        );
        setRealChatMemoryIds(nextChatMemories);
        setChatMemories(nextChatMemories);
        setInitialChatMemories(nextChatMemories);

        setRealBindingsLoaded(true);
      })
      .catch((err) => {
        if (cancelled) return;
        setRealBindingsLoaded(true);
        const msg = err instanceof Error ? err.message : String(err);
        // 只读模式下后端可能拒绝访问非自己的 agent 资产（NOT_YOUR_AGENT），这是预期行为。
        if (!/NOT_YOUR_AGENT/.test(msg)) {
          tea.notify.error(t('agentEdit.notify.loadAssetsFailed', { msg }));
        }
      });

    return () => {
      cancelled = true;
    };
  }, [agent, assets.loading, realBindingsLoaded, selfChatMemoryId]);

  return (
    <Modal visible caption={t('agentEdit.caption')} size="l" onClose={onClose}>
      <Modal.Body>
        <div className="_memory-form-stack">
          <div className="_memory-modal-description">{agent.agent_id}</div>
          <LightField label={t('agentEdit.name')}>
            <Input size="full" value={name} onChange={setName} disabled={saving} />
          </LightField>

          <LightField label={t('agentEdit.descLabel')}>
            <Input.TextArea
              size="full"
              value={description}
              onChange={setDescription}
              rows={2}
              disabled={saving}
            />
          </LightField>

          <LightField label={t('agentEdit.roleLabel')}>
            <Input.TextArea
              size="full"
              value={rolePrompt}
              onChange={setRolePrompt}
              rows={3}
              disabled={saving}
              placeholder={t('agentEdit.rolePlaceholder')}
            />
          </LightField>

          <LightField label={t('agentEdit.rulesLabel')}>
            <Input.TextArea
              size="full"
              value={rulesPrompt}
              onChange={setRulesPrompt}
              rows={4}
              disabled={saving}
              className="_memory-mono-textarea"
              placeholder={t('agentEdit.rulesPlaceholder')}
            />
          </LightField>

          <div className="_memory-asset-section">
            {bindingsLoading ? (
              // 整个资产区域加载中：骨架占位 4 个折叠组的轮廓
              <div className="_memory-asset-section-loading" aria-label="loading assets">
                <div className="_memory-asset-loading">{t('agentEdit.assets.loading')}</div>
                <div className="_memory-collapse-group-stack">
                  {[0, 1, 2, 3].map((i) => (
                    <div
                      key={i}
                      className="_memory-collapse-group _memory-collapse-group--loading"
                      style={{ animationDelay: `${i * 60}ms` }}
                    >
                      <div className="_memory-collapse-group-header">
                        <span className="_memory-collapse-group-chevron" />
                        <span className="_memory-collapse-group-title">
                          <span className="_memory-collapse-group-title-skeleton" />
                        </span>
                        <span className="_memory-collapse-group-count _memory-collapse-group-count--loading" />
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ) : (
              <>
                <div className="_memory-asset-toolbar">
                  <span className="_memory-asset-toolbar-label">{t('agentEdit.assets.label')}</span>
                  <span className="_memory-asset-toolbar-hint">
                    {t('agentEdit.assets.editHint')}
                  </span>
                </div>
                <div className="_memory-collapse-group-stack">
                  <CollapseGroup
                    icon={<BooksIcon size={16} />}
                    title={t('settings.module.wiki')}
                    selectedCount={llmWikis.length}
                    totalCount={wikiAssets.length}
                    open={wikiOpen}
                    onToggle={() => setWikiOpen(!wikiOpen)}
                  >
                    <AssetCheckList
                      assets={wikiAssets}
                      checkedKeys={llmWikis}
                      onToggle={(k) => toggle(llmWikis, setLlmWikis, k)}
                    />
                  </CollapseGroup>
                  <CollapseGroup
                    icon={<CodeIcon size={16} />}
                    title={t('settings.module.code')}
                    selectedCount={codeGraphs.length}
                    totalCount={codeGraphAssets.length}
                    open={codeGraphOpen}
                    onToggle={() => setCodeGraphOpen(!codeGraphOpen)}
                  >
                    <AssetCheckList
                      assets={codeGraphAssets}
                      checkedKeys={codeGraphs}
                      onToggle={(k) => toggle(codeGraphs, setCodeGraphs, k)}
                    />
                  </CollapseGroup>
                  <CollapseGroup
                    icon={<ChatIcon size={16} />}
                    title={t('settings.module.chatMemory')}
                    selectedCount={chatMemories.length}
                    totalCount={memoryAssets.length}
                    open={memoryOpen}
                    onToggle={() => setMemoryOpen(!memoryOpen)}
                  >
                    <AssetCheckList
                      assets={memoryAssets}
                      checkedKeys={chatMemories}
                      onToggle={(k) => toggle(chatMemories, setChatMemories, k)}
                      disabledKeys={new Set([selfChatMemoryId])}
                    />
                  </CollapseGroup>
                  {/* Skill 仍只读：其绑定是 fork 独立副本，编辑弹窗不做增删（见文件头说明） */}
                  <CollapseGroup
                    icon={<ToolsIcon size={16} />}
                    title={t('settings.module.skill')}
                    selectedCount={skills.length}
                    totalCount={boundSkills.length}
                    open={skillsOpen}
                    onToggle={() => setSkillsOpen(!skillsOpen)}
                    hideTotal
                  >
                    <div className="_memory-asset-readonly-hint">
                      {t('agentEdit.assets.skillReadonly')}
                    </div>
                    <AssetCheckList
                      assets={boundSkills}
                      checkedKeys={skills}
                      onToggle={() => {}}
                      readOnly
                    />
                  </CollapseGroup>
                </div>
              </>
            )}
          </div>
        </div>
      </Modal.Body>
      <Modal.Footer>
        <Button onClick={onClose} disabled={saving}>
          {t('agentEdit.cancel')}
        </Button>
        <Button
          type="primary"
          onClick={() => void saveAgent()}
          disabled={!agentChanged || saving}
          loading={saving}
        >
          {t('agentEdit.save')}
        </Button>
      </Modal.Footer>
    </Modal>
  );
}

/**
 * AgentGrid —— team 内 Agent 管理：卡片/列表视图、搜索与 Owner 筛选。
 * 权限与数据走真实后端链路。
 */

import { useCallback, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Button, Justify, SearchBox, Segment, Select, Table } from 'tea-component';
import {
  AddIcon,
  ChevronRightIcon,
  DeleteIcon,
  ViewListIcon,
  ViewModuleIcon,
} from 'tea-icons-react';
import { canManageAsset, type Team, type Agent as StoreAgent } from '@/services';
import { useDisplayNameResolver, useUserDisplayName } from '@/services/user-profile-store';
import { emptyMountedCounts, type AgentMountedCounts } from './types';
import { Mounted } from './shared';

const { scrollable } = Table.addons;

/**
 * Agent owner 标签：可见文本显示 display_name（缓存未命中先回退 id），
 * title 保留 user_id 供排查。抽子组件是 Rules of Hooks 要求（不能在 .map 里循环调 hook）。
 */
function AgentOwnerTag({ ownerId, isMe }: { ownerId: string; isMe: boolean }) {
  const { t } = useTranslation();
  const name = useUserDisplayName(ownerId);
  if (!ownerId) {
    return <span className="_memory-agents-owner-tag">{t('agentGrid.card.ownerUnset')}</span>;
  }
  return (
    <span
      className={`_memory-agents-owner-tag${isMe ? ' _memory-agents-owner-tag--me' : ''}`}
      title={ownerId}
    >
      {name || ownerId}
      {isMe && t('agentGrid.owner.you')}
    </span>
  );
}

type ViewMode = 'card' | 'list';

export default function AgentGrid({
  activeTeam,
  agents,
  agentsLoading,
  countsLoading,
  mountedCounts,
  currentUser,
  isAdmin: _isAdmin,
  canSeeAllAgents,
  onCreateAgent,
  onEditAgent,
  onDeleteAgent,
}: {
  activeTeam: Team;
  agents: StoreAgent[];
  agentsLoading: boolean;
  /** agent-overview/bootstrap 计数是否仍在加载：未返回时保持骨架屏，不提前跳出加载态 */
  countsLoading: boolean;
  mountedCounts: Record<string, AgentMountedCounts>;
  currentUser: string;
  /** 保留接口兼容；admin 不再有特殊权限。 */
  isAdmin: boolean;
  /** 是否有权限看到 team 内全部 agent（admin / team admin）。普通用户只能看到自己的，无需 Owner 筛选。 */
  canSeeAllAgents: boolean;
  onCreateAgent: () => void;
  onEditAgent: (agent: StoreAgent) => void;
  onDeleteAgent: (agent: StoreAgent) => void;
}) {
  const { t } = useTranslation();
  const [keyword, setKeyword] = useState('');
  const [ownerFilter, setOwnerFilter] = useState('');
  const [viewMode, setViewMode] = useState<ViewMode>(() => {
    const saved = typeof localStorage !== 'undefined' ? localStorage.getItem('agentGrid.viewMode') : null;
    return saved === 'list' ? 'list' : 'card';
  });
  const handleSetViewMode = useCallback((mode: ViewMode) => {
    setViewMode(mode);
    try {
      localStorage.setItem('agentGrid.viewMode', mode);
    } catch {
      /* localStorage 不可用则忽略 */
    }
  }, []);

  const ownerOptions = useMemo(() => {
    const memberIds = activeTeam.members.map((member) => member.user_id);
    const agentOwnerIds = agents.map((agent) => agent.owner_user_id).filter(Boolean);
    return Array.from(new Set([...memberIds, ...agentOwnerIds]));
  }, [activeTeam.members, agents]);

  // user_id → display_name 解析（筛选下拉 / tooltip 等批量场景；与 owner 标签同套缓存）
  const resolveUserName = useDisplayNameResolver();

  const filteredAgents = useMemo(() => {
    const normalizedKeyword = keyword.trim().toLowerCase();
    return agents.filter((agent) => {
      if (ownerFilter && agent.owner_user_id !== ownerFilter) return false;
      if (!normalizedKeyword) return true;
      return (
        agent.name.toLowerCase().includes(normalizedKeyword)
        || agent.description.toLowerCase().includes(normalizedKeyword)
        || agent.agent_id.toLowerCase().includes(normalizedKeyword)
      );
    });
  }, [agents, keyword, ownerFilter]);

  function canEdit(agent: StoreAgent): boolean {
    // admin 与 member 一致：只能操作自己 owner 的 agent（不再有全局 admin 特权）。
    return canManageAsset(
      { owner_user_id: agent.owner_user_id, team_id: agent.team_id },
      activeTeam,
      currentUser,
      false,
    );
  }

  function renderName(agent: StoreAgent, compact = false) {
    const editable = canEdit(agent);
    return (
      <button
        type="button"
        className={`_memory-agents-name-trigger${editable ? ' _memory-agents-name-trigger--editable' : ''}`}
        data-guide={editable ? 'agent-name-editable' : undefined}
        onClick={() => editable && onEditAgent(agent)}
        disabled={!editable}
        title={editable
          ? t('agentGrid.card.edit.tooltip.can')
          : t('agentGrid.card.edit.tooltip.cannot', { owner: agent.owner_user_id ? resolveUserName(agent.owner_user_id) : t('agentGrid.card.ownerUnset') })}
      >
        <span className="_memory-agents-name" title={agent.name}>{agent.name}</span>
        {editable && <ChevronRightIcon size={compact ? 12 : 14} className="_memory-agents-chevron" />}
      </button>
    );
  }

  function renderOwner(agent: StoreAgent) {
    return <AgentOwnerTag ownerId={agent.owner_user_id} isMe={agent.owner_user_id === currentUser} />;
  }

  function renderAssets(agent: StoreAgent, countsLoading = false) {
    const counts = mountedCounts[agent.agent_id] ?? emptyMountedCounts();
    return (
      <div className="_memory-agents-stats">
        <Mounted label="skills" count={counts.skills} loading={countsLoading} />
        <Mounted label="code_graph" count={counts.code_graph} loading={countsLoading} />
        <Mounted label="llm_wiki" count={counts.llm_wiki} loading={countsLoading} />
        <Mounted label="chat_memory" count={counts.chat_memory} loading={countsLoading} />
      </div>
    );
  }

  return (
    <div className="_memory-agents-panel">
      <div className="_memory-agents-section-head">
        <div>
          <h2 className="_memory-agents-section-title">{t('agentGrid.title')}</h2>
          <div className="_memory-agents-section-subtitle">
            {t('agentGrid.subtitle', {
              name: activeTeam.name,
              id: activeTeam.team_id,
              loading: agentsLoading ? t('agentGrid.loading') : t('agentGrid.subtitle.count', { count: agents.length }),
            })}
          </div>
        </div>
      </div>

      <Table.ActionPanel>
        <Justify
          left={
            <Button
              type="primary"
              onClick={onCreateAgent}
              title={t('agentGrid.create.tooltip')}
              data-guide="create-agent"
            >
              <AddIcon size={12} /> {t('agentGrid.create')}
            </Button>
          }
          right={
            <div className="_memory-agents-toolbar">
              <SearchBox
                value={keyword}
                onChange={setKeyword}
                placeholder={t('agentGrid.search')}
              />
              {canSeeAllAgents && (
                <Select
                  value={ownerFilter}
                  onChange={setOwnerFilter}
                  appearance="button"
                  options={[
                    { value: '', text: t('agentGrid.allOwners') },
                    ...ownerOptions.map((ownerId) => ({ value: ownerId, text: resolveUserName(ownerId) })),
                  ]}
                  matchButtonWidth
                />
              )}
              <Segment
                value={viewMode}
                onChange={(value) => handleSetViewMode(value as ViewMode)}
                options={[
                  { value: 'card', text: <ViewModuleIcon /> },
                  { value: 'list', text: <ViewListIcon /> },
                ]}
              />
            </div>
          }
        />
      </Table.ActionPanel>

      {/* 加载编排两段式：
          1) 首屏 agents 还没回来 → 4 个骨架卡占位（不知道实际数量，按视觉预设 4 张）
          2) agents 已就绪 → 立刻渲染真实卡片，counts 还在加载时只在「资产计数 chip」显示骨架占位
            —— 不再用整网格骨架覆盖，避免「4 骨架 → 1 真实卡」的过渡突兀 */}
      {agentsLoading && agents.length === 0 ? (
        viewMode === 'card' ? (
          // 卡片视图骨架屏：4 个占位卡 + shimmer 动画，风格与 AssetListPanel 一致；
          // 卡片逐张错峰入场（60ms 步进，编排式加载），骨架卡不闪切
          <div className="_memory-agents-skeleton-grid" aria-label="loading">
            {[0, 1, 2, 3].map((i) => (
              <div
                key={i}
                className="_memory-agents-skeleton-card"
                style={{ animationDelay: `${i * 60}ms` }}
              >
                {/* 1. head：名称 + chevron，对齐真实 _memory-agents-card-head */}
                <div className="_memory-agents-skeleton-head">
                  <div className="_memory-agents-skeleton-line _memory-agents-skeleton-line--name" />
                  <div className="_memory-agents-skeleton-line _memory-agents-skeleton-line--chevron" />
                </div>
                {/* 2. id：等宽小字，对齐 _memory-agents-card-id */}
                <div className="_memory-agents-skeleton-line _memory-agents-skeleton-line--id" />
                {/* 3. desc：两行，对齐 _memory-agents-card-desc（min-height 40px） */}
                <div className="_memory-agents-skeleton-desc">
                  <div className="_memory-agents-skeleton-line" />
                  <div className="_memory-agents-skeleton-line _memory-agents-skeleton-line--desc-short" />
                </div>
                {/* 4. owner 行：label + pill，对齐 _memory-agents-owner-row */}
                <div className="_memory-agents-skeleton-owner">
                  <div className="_memory-agents-skeleton-line _memory-agents-skeleton-line--owner-label" />
                  <div className="_memory-agents-skeleton-line _memory-agents-skeleton-line--owner-tag" />
                </div>
                {/* 5. stats：2 列 4 个 mounted chip，对齐 _memory-agents-stats */}
                <div className="_memory-agents-skeleton-stats">
                  {[0, 1, 2, 3].map((j) => (
                    <div key={j} className="_memory-agents-skeleton-chip">
                      <div className="_memory-agents-skeleton-line _memory-agents-skeleton-line--chip-label" />
                      <div className="_memory-agents-skeleton-line _memory-agents-skeleton-line--chip-count" />
                    </div>
                  ))}
                </div>
                {/* 6. actions：右对齐删除按钮，对齐 _memory-agents-card-actions */}
                <div className="_memory-agents-skeleton-actions">
                  <div className="_memory-agents-skeleton-line _memory-agents-skeleton-line--action" />
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="_memory-agents-empty">{t('agentGrid.loading')}</div>
        )
      ) : filteredAgents.length === 0 ? (
        <div className="_memory-agents-empty">
          {agents.length === 0
            ? t('agentGrid.empty.member')
            : canSeeAllAgents
              ? t('agentGrid.empty.filtered.all')
              : t('agentGrid.empty.filtered.partial')}
        </div>
      ) : viewMode === 'card' ? (
        <div className="_memory-agents-card-grid">
          {filteredAgents.map((agent) => {
            const editable = canEdit(agent);
            return (
              <div
                key={agent.agent_id}
                className={`_memory-agents-card${editable ? ' _memory-agents-card--editable' : ''}`}
                data-guide={editable ? 'agent-card-editable' : undefined}
              >
                <div className="_memory-agents-card-head">{renderName(agent)}</div>
                <div className="_memory-agents-card-id">{t('agentGrid.card.id', { id: agent.agent_id })}</div>
                <div className="_memory-agents-card-desc">{agent.description || t('common.noDescription')}</div>
                <div className="_memory-agents-owner-row">
                  <span>{t('agentGrid.card.owner')}</span>
                  {renderOwner(agent)}
                  {!editable && <span className="_memory-agents-readonly">{t('agentGrid.card.readonly')}</span>}
                </div>
                {/* 资产计数区：counts 还在加载时只把 4 个数字换成小骨架占位，主体立刻可见 */}
                {renderAssets(agent, countsLoading)}
                <div className="_memory-agents-card-actions">
                  <Button
                    type="text"
                    disabled={!editable}
                    onClick={() => onDeleteAgent(agent)}
                    title={editable ? t('agentGrid.card.delete.tooltip.can') : t('agentGrid.card.delete.tooltip.cannot')}
                  >
                    <DeleteIcon size={12} /> {t('agentGrid.card.delete')}
                  </Button>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <Table
          records={filteredAgents}
          recordKey="agent_id"
          addons={[scrollable({ minWidth: 960, maxHeight: 560 })]}
          columns={[
            {
              key: 'name',
              header: t('agentGrid.table.name'),
              width: 240,
              render: (agent: StoreAgent) => renderName(agent, true),
            },
            {
              key: 'owner',
              header: t('agentGrid.table.owner'),
              width: 160,
              render: (agent: StoreAgent) => renderOwner(agent),
            },
            {
              key: 'assets',
              header: t('agentGrid.table.assets'),
              render: (agent: StoreAgent) => {
                const counts = mountedCounts[agent.agent_id] ?? emptyMountedCounts();
                // 列表视图同样：counts 在加载时用「—」占位，而不是整行消失
                if (countsLoading) {
                  return <span className="_memory-agents-list-assets _memory-agents-list-assets--loading">—</span>;
                }
                return (
                  <span className="_memory-agents-list-assets">
                    skills×{counts.skills} · code_graph×{counts.code_graph} · llm_wiki×{counts.llm_wiki} · chat_memory×{counts.chat_memory}
                  </span>
                );
              },
            },
            {
              key: 'description',
              header: t('agentGrid.table.desc'),
              render: (agent: StoreAgent) => <span className="_memory-agents-list-description">{agent.description || t('common.noDescription')}</span>,
            },
            {
              key: 'actions',
              header: t('agentGrid.table.actions'),
              width: 90,
              fixed: 'right',
              render: (agent: StoreAgent) => {
                const editable = canEdit(agent);
                return (
                  <Button type="link" disabled={!editable} onClick={() => onDeleteAgent(agent)}>
                    {t('agentGrid.table.delete')}
                  </Button>
                );
              },
            },
          ]}
        />
      )}
    </div>
  );
}

/**
 * CreateAgentDialog —— 创建 Agent 弹窗。
 * 支持套用/保存模板、勾选 skills/code_graph/llm_wiki/chat_memory 原子能力。
 */

import { useState } from 'react';
import { Button, Input, Modal, Tag } from 'tea-component';
import { useTranslation } from 'react-i18next';
import {
  AddIcon,
  StarFilledIcon,
  CloseIcon,
  BooksIcon,
  CodeIcon,
  ToolsIcon,
  ChatIcon,
} from 'tea-icons-react';
import {
  readAgentTemplates,
  createAgentTemplate,
  deleteAgentTemplate,
  type AgentTemplate,
} from '@/services';

import type { AgentCard } from './types';
import { useTeamAssets } from './useAgentAssets';
import { LightField, CollapseGroup, AssetCheckList, selectableAssetKeys } from './shared';

export default function CreateAgentDialog({
  team,
  currentUser: _currentUser,
  onClose,
  onCreated,
  busy,
}: {
  /** Agent 严格归属一个 team，这里不让用户在 dialog 里改归属或转交 owner
   *  （owner 由后端在创建时固定为当前登录用户）。 */
  team: { team_id: string; name: string };
  currentUser: string;
  onClose: () => void;
  onCreated: (card: Omit<AgentCard, 'id' | 'icon' | 'accent'>) => void;
  busy: boolean;
}) {
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [rolePrompt, setRolePrompt] = useState('');
  const [rulesPrompt, setRulesPrompt] = useState('');
  const [skillsOpen, setSkillsOpen] = useState(false);
  const [codeGraphOpen, setCodeGraphOpen] = useState(false);
  const [wikiOpen, setWikiOpen] = useState(false);
  const [memoryOpen, setMemoryOpen] = useState(false);
  const [skills, setSkills] = useState<string[]>([]);
  const [codeGraphs, setCodeGraphs] = useState<string[]>([]);
  const [llmWikis, setLlmWikis] = useState<string[]>([]);
  const [chatMemories, setChatMemories] = useState<string[]>([]);

  const [templates, setTemplates] = useState<AgentTemplate[]>(() => readAgentTemplates());
  const [appliedTemplateId, setAppliedTemplateId] = useState<string>('');
  const [saveTplOpen, setSaveTplOpen] = useState(false);
  const [tplName, setTplName] = useState('');
  const [tplSummary, setTplSummary] = useState('');
  // 保存模板表单里可编辑的 agent 内容字段：默认取自当前主表单，
  // 展开保存表单时预填，用户可微调后再存入模板（不含 agent 名字）。
  const [tplDescription, setTplDescription] = useState('');
  const [tplRolePrompt, setTplRolePrompt] = useState('');
  const [tplRulesPrompt, setTplRulesPrompt] = useState('');

  // 从真实 API 拉取团队资产列表
  const assets = useTeamAssets(team.team_id);
  const { t } = useTranslation();

  const canSubmit = name.trim().length > 0 && !busy;
  const totalSelected = skills.length + codeGraphs.length + llmWikis.length + chatMemories.length;

  function toggle(list: string[], setList: (v: string[]) => void, key: string) {
    setList(list.includes(key) ? list.filter((k) => k !== key) : [...list, key]);
  }

  function applyTemplate(tpl: AgentTemplate) {
    // 模板只承载文本描述，套用时不改动用户已勾选的原子能力。
    setDescription(tpl.description);
    setRolePrompt(tpl.role_prompt);
    setRulesPrompt(tpl.rules_prompt);
    setAppliedTemplateId(tpl.template_id);
  }

  // 展开「保存为模板」表单时，用当前主表单值预填可编辑字段。
  function openSaveTemplateForm() {
    setSaveTplOpen((v) => {
      const next = !v;
      if (next) {
        setTplDescription(description);
        setTplRolePrompt(rolePrompt);
        setTplRulesPrompt(rulesPrompt);
      }
      return next;
    });
  }

  // 关闭并清空保存模板表单的全部字段。
  function resetSaveTemplateForm() {
    setSaveTplOpen(false);
    setTplName('');
    setTplSummary('');
    setTplDescription('');
    setTplRolePrompt('');
    setTplRulesPrompt('');
  }

  function handleSaveTemplate() {
    const nm = tplName.trim();
    if (!nm) return;
    // 模板只保存文本描述，不保存所选原子能力（skills / code_graph / llm_wiki / chat_memory）。
    createAgentTemplate({
      name: nm,
      summary: tplSummary.trim(),
      description: tplDescription.trim(),
      role_prompt: tplRolePrompt.trim(),
      rules_prompt: tplRulesPrompt.trim(),
    });
    setTemplates(readAgentTemplates());
    resetSaveTemplateForm();
  }

  function handleDeleteTemplate(tpl: AgentTemplate) {
    if (tpl.builtin) return;
    deleteAgentTemplate(tpl.template_id);
    setTemplates(readAgentTemplates());
    if (appliedTemplateId === tpl.template_id) setAppliedTemplateId('');
  }

  return (
    <Modal visible caption={t('createAgent.caption')} size="l" onClose={onClose} disableEscape={busy}>
      <Modal.Body>
        <div className="_memory-form-stack">
          <div className="_memory-modal-description">{t('createAgent.desc')}</div>
        <div className="_memory-target-team-row">
          <span className="_memory-target-team-avatar">{team.name.slice(0, 1).toUpperCase()}</span>
          <div className="_memory-target-team-meta">
            <div className="_memory-target-team-label">{t('createAgent.teamLabel')}</div>
            <div className="_memory-target-team-name-row">
              <span className="_memory-target-team-name">{team.name}</span>
              <Tag size="sm">{team.team_id}</Tag>
            </div>
          </div>
          <div className="_memory-target-team-hint">
            {t('createAgent.teamHint')}
          </div>
        </div>

        <div className="_memory-template-box">
          <div className="_memory-template-box-title-row">
            <span className="_memory-template-box-title">{t('createAgent.template.title')}</span>
            <span className="_memory-template-box-hint">
              {t('createAgent.template.hint')}
            </span>
          </div>
          <div className="_memory-template-chip-row">
            {templates.map((tpl) => {
              const active = appliedTemplateId === tpl.template_id;
              return (
                <span
                  key={tpl.template_id}
                  className={`_memory-template-chip${active ? ' _memory-template-chip--active' : ''}`}
                >
                  <button
                    type="button"
                    onClick={() => applyTemplate(tpl)}
                    title={tpl.summary || tpl.name}
                    className="_memory-template-chip-btn"
                  >
                    {tpl.builtin && <StarFilledIcon size={11} />} {tpl.name}
                  </button>
                  {!tpl.builtin && (
                    <button
                      type="button"
                      onClick={() => handleDeleteTemplate(tpl)}
                      title={t('createAgent.template.delete')}
                      className="_memory-template-chip-close"
                      aria-label={t('createAgent.template.delete')}
                    >
                      <CloseIcon size={10} />
                    </button>
                  )}
                </span>
              );
            })}
            <button
              type="button"
              onClick={openSaveTemplateForm}
              className="_memory-template-save-btn"
            >
              <AddIcon size={11} /> {t('createAgent.template.save')}
            </button>
          </div>
          {saveTplOpen && (
            <div className="_memory-template-save-form">
              <div className="_memory-template-save-hint">
                {t('createAgent.template.saveHint')}
              </div>
              <Input
                size="full"
                value={tplName}
                onChange={setTplName}
                placeholder={t('createAgent.template.namePlaceholder')}
              />
              <Input
                size="full"
                value={tplSummary}
                onChange={setTplSummary}
                placeholder={t('createAgent.template.summaryPlaceholder')}
              />
              <div className="_memory-light-field-label">{t('createAgent.template.descLabel')}</div>
              <Input
                size="full"
                value={tplDescription}
                onChange={setTplDescription}
                placeholder={t('createAgent.template.descPlaceholder')}
              />
              <div className="_memory-light-field-label">{t('createAgent.template.roleLabel')}</div>
              <Input.TextArea
                size="full"
                rows={3}
                value={tplRolePrompt}
                onChange={setTplRolePrompt}
                placeholder={t('createAgent.template.rolePlaceholder')}
              />
              <div className="_memory-light-field-label">{t('createAgent.template.rulesLabel')}</div>
              <Input.TextArea
                size="full"
                rows={4}
                value={tplRulesPrompt}
                onChange={setTplRulesPrompt}
                placeholder={t('createAgent.template.rulesPlaceholder')}
                className="_memory-mono-textarea"
              />

              <div className="_memory-template-save-actions">
                <Button onClick={resetSaveTemplateForm}>{t('createAgent.template.cancel')}</Button>
                <Button type="primary"
                  disabled={!tplName.trim()}
                  onClick={handleSaveTemplate}
                >
                  {t('createAgent.template.saveBtn')}
                </Button>
              </div>
            </div>
          )}
        </div>

        <LightField label={t('createAgent.name')}>
          <Input
            autoFocus
            size="full"
            value={name}
            onChange={setName}
            placeholder={t('createAgent.name.placeholder')}
          />
          <div className="_memory-field-hint">
            {t('createAgent.name.hint')}
          </div>
        </LightField>

        <LightField label={t('createAgent.descLabel')} hint={t('createAgent.descHint')}>
          <Input
            size="full"
            value={description}
            onChange={setDescription}
            placeholder={t('createAgent.descPlaceholder')}
          />
        </LightField>

        <LightField
          label={t('createAgent.roleLabel')}
          hint={t('createAgent.roleHint')}
        >
          <Input.TextArea
            size="full"
            value={rolePrompt}
            onChange={setRolePrompt}
            rows={3}
            placeholder={t('createAgent.rolePlaceholder')}
          />
        </LightField>

        <LightField
          label={t('createAgent.rulesLabel')}
          hint={t('createAgent.rulesHint')}
        >
          <Input.TextArea
            size="full"
            value={rulesPrompt}
            onChange={setRulesPrompt}
            rows={4}
            placeholder={t('createAgent.rulesPlaceholder')}
            className="_memory-mono-textarea"
          />
        </LightField>

        {assets.loading ? (
          <div className="_memory-asset-loading">{t('createAgent.assets.loading')}</div>
        ) : (
          <>
            <div className="_memory-asset-toolbar">
              <span className="_memory-asset-toolbar-label">{t('createAgent.assets.label')}</span>
              <button
                type="button"
                onClick={() => {
                  setSkills(selectableAssetKeys(assets.skills));
                  setCodeGraphs(selectableAssetKeys(assets.codeGraphs));
                  setLlmWikis(selectableAssetKeys(assets.wikis));
                  setChatMemories(selectableAssetKeys(assets.chatMemories));
                }}
                className="_memory-asset-toolbar-btn"
              >
                {t('createAgent.assets.selectAll')}
              </button>
              {totalSelected > 0 && (
                <button
                  type="button"
                  onClick={() => {
                    setSkills([]);
                    setCodeGraphs([]);
                    setLlmWikis([]);
                    setChatMemories([]);
                  }}
                  className="_memory-asset-toolbar-btn"
                >
                  {t('createAgent.assets.clearAll')}
                </button>
              )}
            </div>
            <CollapseGroup
              icon={<BooksIcon size={16} />}
              title={t('settings.module.wiki')}
              selectedCount={llmWikis.length}
              totalCount={assets.wikis.length}
              open={wikiOpen}
              onToggle={() => setWikiOpen(!wikiOpen)}
            >
              <AssetCheckList
                assets={assets.wikis}
                checkedKeys={llmWikis}
                onToggle={(k) => toggle(llmWikis, setLlmWikis, k)}
              />
            </CollapseGroup>
            <CollapseGroup
              icon={<CodeIcon size={16} />}
              title={t('settings.module.code')}
              selectedCount={codeGraphs.length}
              totalCount={assets.codeGraphs.length}
              open={codeGraphOpen}
              onToggle={() => setCodeGraphOpen(!codeGraphOpen)}
            >
              <AssetCheckList
                assets={assets.codeGraphs}
                checkedKeys={codeGraphs}
                onToggle={(k) => toggle(codeGraphs, setCodeGraphs, k)}
              />
            </CollapseGroup>
            <CollapseGroup
              icon={<ToolsIcon size={16} />}
              title={t('settings.module.skill')}
              selectedCount={skills.length}
              totalCount={assets.skills.length}
              open={skillsOpen}
              onToggle={() => setSkillsOpen(!skillsOpen)}
            >
              <AssetCheckList
                assets={assets.skills}
                checkedKeys={skills}
                onToggle={(k) => toggle(skills, setSkills, k)}
              />
            </CollapseGroup>
            <CollapseGroup
              icon={<ChatIcon size={16} />}
              title={t('settings.module.chatMemory')}
              selectedCount={chatMemories.length}
              totalCount={assets.chatMemories.length}
              open={memoryOpen}
              onToggle={() => setMemoryOpen(!memoryOpen)}
            >
              <AssetCheckList
                assets={assets.chatMemories}
                checkedKeys={chatMemories}
                onToggle={(k) => toggle(chatMemories, setChatMemories, k)}
              />
            </CollapseGroup>
          </>
        )}
        </div>
      </Modal.Body>
      <Modal.Footer>
        <Button
          type="primary"
          disabled={!canSubmit}
          loading={busy}
          onClick={() => onCreated({
            name: name.trim(),
            description: description.trim(),
            rolePrompt: rolePrompt.trim(),
            rulesPrompt: rulesPrompt.trim(),
            skills,
            codeGraphs,
            llmWikis,
            chatMemories,
          })}
        >
          {t('createAgent.submit')}
        </Button>
        <Button onClick={onClose} disabled={busy}>{t('createAgent.cancel')}</Button>
      </Modal.Footer>
    </Modal>
  );
}

/**
 * DefaultAgentTemplateDialog —— 默认 Agent 模板配置弹窗（仅全局 admin）。
 *
 * 表单字段与「创建 Agent」对齐，但只允许选择**团队公共资产**
 * （useTeamAssets 内部已按 visibility=team 过滤 skill / code_graph / wiki；
 * 模板的 asset_ids 不支持 chat_memory，故不提供记忆勾选）。
 *
 * 保存走 agent/set-default-template（覆盖式写入，一次回传完整 template）。
 * 已配置时打开弹窗会用 get-default-template 的返回值预填。
 */

import { useState } from 'react';
import { Button, Input, Modal, Tag } from 'tea-component';
import { useTranslation } from 'react-i18next';
import { BooksIcon, CodeIcon, ToolsIcon } from 'tea-icons-react';
import { agentsApi, type AgentTemplateConfig } from '@/lib/teamApi';
import { writeAgentUiMeta } from '@/services';
import { tea } from '@/lib/tea-bridge';
import { getErrorMessage } from '@/lib/error-message';
import { LightField, CollapseGroup, AssetCheckList, selectableAssetKeys } from './shared';
import { useTeamAssets } from './useAgentAssets';

/** 从模板 metadata_json（JSON 字符串）读取 ui.role_prompt / ui.rules_prompt。 */
function readTemplatePrompts(tpl: AgentTemplateConfig): { rolePrompt: string; rulesPrompt: string } {
  let rolePrompt = '';
  let rulesPrompt = '';
  if (tpl.metadata_json) {
    try {
      const meta = JSON.parse(tpl.metadata_json) as { ui?: { role_prompt?: string; rules_prompt?: string } };
      rolePrompt = meta?.ui?.role_prompt ?? '';
      rulesPrompt = meta?.ui?.rules_prompt ?? '';
    } catch {
      /* metadata_json 不合法按空处理 */
    }
  }
  // 没有 ui 拆分时回退到整体 prompt（与 Agent 详情展示口径一致）
  if (!rolePrompt && tpl.prompt) rolePrompt = tpl.prompt;
  return { rolePrompt, rulesPrompt };
}

export default function DefaultAgentTemplateDialog({
  team,
  initial,
  onClose,
  onSaved,
}: {
  team: { team_id: string; name: string };
  /** 已配置的模板（用于预填表单）；null = 首次新建 */
  initial: AgentTemplateConfig | null;
  onClose: () => void;
  onSaved: (tpl: AgentTemplateConfig) => void;
}) {
  const { t } = useTranslation();
  const [name, setName] = useState(initial?.name ?? '');
  const [description, setDescription] = useState(initial?.description ?? '');
  const [rolePrompt, setRolePrompt] = useState(() => readTemplatePrompts(initial ?? { name: '' }).rolePrompt);
  const [rulesPrompt, setRulesPrompt] = useState(() => readTemplatePrompts(initial ?? { name: '' }).rulesPrompt);
  const [skillsOpen, setSkillsOpen] = useState(false);
  const [codeGraphOpen, setCodeGraphOpen] = useState(false);
  const [wikiOpen, setWikiOpen] = useState(false);
  const [skills, setSkills] = useState<string[]>(initial?.asset_ids?.skills ?? []);
  const [codeGraphs, setCodeGraphs] = useState<string[]>(initial?.asset_ids?.code_graphs ?? []);
  const [llmWikis, setLlmWikis] = useState<string[]>(initial?.asset_ids?.wikis ?? []);
  const [busy, setBusy] = useState(false);

  // 团队公共资产（skill / code_graph / wiki，后端 bootstrap 已按 visibility=team 过滤）
  const assets = useTeamAssets(team.team_id);

  const canSubmit = name.trim().length > 0 && !busy;
  const totalSelected = skills.length + codeGraphs.length + llmWikis.length;

  function toggle(list: string[], setList: (v: string[]) => void, key: string) {
    setList(list.includes(key) ? list.filter((k) => k !== key) : [...list, key]);
  }

  async function handleSave() {
    if (!canSubmit) return;
    setBusy(true);
    try {
      const metadataJson = writeAgentUiMeta(undefined, {
        role_prompt: rolePrompt.trim(),
        rules_prompt: rulesPrompt.trim(),
      });
      const template: AgentTemplateConfig = {
        name: name.trim(),
        description: description.trim() || null,
        prompt: [rolePrompt.trim(), rulesPrompt.trim()].filter(Boolean).join('\n\n'),
        visibility: 'team',
        metadata_json: metadataJson,
        asset_ids: { skills, code_graphs: codeGraphs, wikis: llmWikis },
      };
      await agentsApi.setDefaultTemplate(team.team_id, template);
      onSaved(template);
    } catch (err) {
      tea.notify.error(getErrorMessage(err));
      setBusy(false);
    }
  }

  return (
    <Modal
      visible
      caption={initial ? t('defaultAgent.edit.caption') : t('defaultAgent.create.caption')}
      size="l"
      onClose={onClose}
      disableEscape={busy}
    >
      <Modal.Body>
        <div className="_memory-form-stack">
          <div className="_memory-modal-description">
            {initial ? t('defaultAgent.edit.desc') : t('defaultAgent.create.desc')}
          </div>
          <div className="_memory-target-team-row">
            <span className="_memory-target-team-avatar">{team.name.slice(0, 1).toUpperCase()}</span>
            <div className="_memory-target-team-meta">
              <div className="_memory-target-team-label">{t('createAgent.teamLabel')}</div>
              <div className="_memory-target-team-name-row">
                <span className="_memory-target-team-name">{team.name}</span>
                <Tag size="sm">{team.team_id}</Tag>
              </div>
            </div>
            <div className="_memory-target-team-hint">
              {t('createAgent.teamHint')}
            </div>
          </div>

          <LightField label={t('defaultAgent.name')}>
            <Input
              size="full"
              value={name}
              onChange={setName}
              placeholder={t('createAgent.name.placeholder')}
            />
            <div className="_memory-field-hint">
              {t('defaultAgent.name.hint')}
            </div>
          </LightField>

          <LightField label={t('createAgent.descLabel')} hint={t('createAgent.descHint')}>
            <Input
              size="full"
              value={description}
              onChange={setDescription}
              placeholder={t('createAgent.descPlaceholder')}
            />
          </LightField>

          <LightField
            label={t('createAgent.roleLabel')}
            hint={t('createAgent.roleHint')}
          >
            <Input.TextArea
              size="full"
              value={rolePrompt}
              onChange={setRolePrompt}
              rows={3}
              placeholder={t('createAgent.rolePlaceholder')}
            />
          </LightField>

          <LightField
            label={t('createAgent.rulesLabel')}
            hint={t('createAgent.rulesHint')}
          >
            <Input.TextArea
              size="full"
              value={rulesPrompt}
              onChange={setRulesPrompt}
              rows={4}
              placeholder={t('createAgent.rulesPlaceholder')}
              className="_memory-mono-textarea"
            />
          </LightField>

          {assets.loading ? (
            <div className="_memory-asset-loading">{t('createAgent.assets.loading')}</div>
          ) : (
            <>
              <div className="_memory-asset-toolbar">
                <span className="_memory-asset-toolbar-label">
                  {t('defaultAgent.assets.label')}
                </span>
                <span className="_memory-asset-toolbar-hint">
                  {t('defaultAgent.assets.hint')}
                </span>
                <button
                  type="button"
                  onClick={() => {
                    setSkills(selectableAssetKeys(assets.skills));
                    setCodeGraphs(selectableAssetKeys(assets.codeGraphs));
                    setLlmWikis(selectableAssetKeys(assets.wikis));
                  }}
                  className="_memory-asset-toolbar-btn"
                >
                  {t('createAgent.assets.selectAll')}
                </button>
                {totalSelected > 0 && (
                  <button
                    type="button"
                    onClick={() => {
                      setSkills([]);
                      setCodeGraphs([]);
                      setLlmWikis([]);
                    }}
                    className="_memory-asset-toolbar-btn"
                  >
                    {t('createAgent.assets.clearAll')}
                  </button>
                )}
              </div>
              <CollapseGroup
                icon={<BooksIcon size={16} />}
                title={t('settings.module.wiki')}
                selectedCount={llmWikis.length}
                totalCount={assets.wikis.length}
                open={wikiOpen}
                onToggle={() => setWikiOpen(!wikiOpen)}
              >
                <AssetCheckList
                  assets={assets.wikis}
                  checkedKeys={llmWikis}
                  onToggle={(k) => toggle(llmWikis, setLlmWikis, k)}
                />
              </CollapseGroup>
              <CollapseGroup
                icon={<CodeIcon size={16} />}
                title={t('settings.module.code')}
                selectedCount={codeGraphs.length}
                totalCount={assets.codeGraphs.length}
                open={codeGraphOpen}
                onToggle={() => setCodeGraphOpen(!codeGraphOpen)}
              >
                <AssetCheckList
                  assets={assets.codeGraphs}
                  checkedKeys={codeGraphs}
                  onToggle={(k) => toggle(codeGraphs, setCodeGraphs, k)}
                />
              </CollapseGroup>
              <CollapseGroup
                icon={<ToolsIcon size={16} />}
                title={t('settings.module.skill')}
                selectedCount={skills.length}
                totalCount={assets.skills.length}
                open={skillsOpen}
                onToggle={() => setSkillsOpen(!skillsOpen)}
              >
                <AssetCheckList
                  assets={assets.skills}
                  checkedKeys={skills}
                  onToggle={(k) => toggle(skills, setSkills, k)}
                />
              </CollapseGroup>
            </>
          )}
        </div>
      </Modal.Body>
      <Modal.Footer>
        <Button type="primary" disabled={!canSubmit} loading={busy} onClick={handleSave}>
          {initial ? t('defaultAgent.save') : t('defaultAgent.create.submit')}
        </Button>
        <Button onClick={onClose} disabled={busy}>{t('createAgent.cancel')}</Button>
      </Modal.Footer>
    </Modal>
  );
}

/**
 * DefaultAgentTemplateSection —— 「默认 Agent 模板」管理区（仅全局 admin 可见）。
 *
 * 放置于 Agents 页面的 AgentGrid 上方：
 *   - 未配置：展示「新建默认 Agent」入口；
 *   - 已配置：展示当前模板摘要 + 「修改配置」入口。
 *
 * 数据源：agent/get-default-template（无权限校验）；写操作 agent/set-default-template
 * 仅 system_admin 可调用，因此本组件只在 isAdmin=true 时渲染。
 */

import { useCallback, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Button } from 'tea-component';
import { AddIcon, EditIcon } from 'tea-icons-react';
import { agentsApi, type AgentTemplateConfig } from '@/lib/teamApi';
import { tea } from '@/lib/tea-bridge';
import { getErrorMessage } from '@/lib/error-message';
import DefaultAgentTemplateDialog from './DefaultAgentTemplateDialog';

export default function DefaultAgentTemplateSection({
  teamId,
  teamName,
}: {
  teamId: string;
  teamName: string;
}) {
  const { t } = useTranslation();
  const [template, setTemplate] = useState<AgentTemplateConfig | null>(null);
  const [loading, setLoading] = useState(true);
  const [showDialog, setShowDialog] = useState(false);

  const load = useCallback(async () => {
    if (!teamId) return;
    setLoading(true);
    try {
      const data = await agentsApi.getDefaultTemplate(teamId);
      // 未配置时后端返回 {}；以 name 是否存在判断是否已配置
      setTemplate(data && data.name ? data : null);
    } catch (err) {
      tea.notify.error(getErrorMessage(err));
      setTemplate(null);
    } finally {
      setLoading(false);
    }
  }, [teamId]);

  useEffect(() => {
    load();
  }, [load]);

  function handleSaved(saved: AgentTemplateConfig) {
    setTemplate(saved);
    setShowDialog(false);
    tea.notify.success(t('defaultAgent.notify.saved'));
  }

  const hasTemplate = !!template;
  const actionButton = hasTemplate ? (
    <Button onClick={() => setShowDialog(true)} title={t('defaultAgent.edit.tooltip')}>
      <EditIcon size={14} /> {t('defaultAgent.edit')}
    </Button>
  ) : (
    <Button
      type="primary"
      onClick={() => setShowDialog(true)}
      title={t('defaultAgent.create.tooltip')}
    >
      <AddIcon size={14} /> {t('defaultAgent.create')}
    </Button>
  );

  return (
    <div className="_memory-panel-card _memory-default-agent-section">
      <div className="_memory-default-agent-head">
        <div className="_memory-default-agent-info">
          <div className="_memory-default-agent-title">{t('defaultAgent.title')}</div>
          <div className="_memory-default-agent-desc">{t('defaultAgent.desc')}</div>
        </div>
        <div className="_memory-default-agent-actions">{actionButton}</div>
      </div>

      {loading ? (
        <div className="_memory-default-agent-body">
          <span className="_memory-default-agent-placeholder">{t('team.loading')}</span>
        </div>
      ) : hasTemplate ? (
        <div className="_memory-default-agent-body">
          <div className="_memory-default-agent-name" title={template!.name}>
            {template!.name}
          </div>
          <div className="_memory-default-agent-detail">
            {template!.description || t('common.noDescription')}
          </div>
        </div>
      ) : (
        <div className="_memory-default-agent-body">
          <span className="_memory-default-agent-placeholder">
            {t('defaultAgent.empty')}
          </span>
        </div>
      )}

      {showDialog && (
        <DefaultAgentTemplateDialog
          team={{ team_id: teamId, name: teamName }}
          initial={template}
          onClose={() => setShowDialog(false)}
          onSaved={handleSaved}
        />
      )}
    </div>
  );
}

import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Button, Form, Input, Modal } from 'tea-component';
import type { Team } from '@/services';

/**
 * EditTeamDialog — 编辑当前 team 的名称 / 描述。
 *
 * 与 CreateTeamDialog 同款表单样式，进入时以 team 当前值预填；
 * 提交调 teamsApi.update（team/update，仅 owner / admin 可改，
 * 后端会静默忽略 owner_user_id 等不可改字段）。
 */
export default function EditTeamDialog({
  team,
  onClose,
  onSave,
  busy,
}: {
  team: Team;
  onClose: () => void;
  onSave: (input: { name: string; description: string }) => void;
  busy: boolean;
}) {
  const { t } = useTranslation();
  const [name, setName] = useState(team.name);
  const [description, setDescription] = useState(team.description ?? '');
  const canSubmit = name.trim().length > 0 && !busy;
  return (
    <Modal
      visible
      caption={t('editTeam.caption', { name: team.name })}
      size="s"
      onClose={onClose}
      disableEscape={busy}
    >
      <Modal.Body>
        <Form>
          <Form.Item label={t('editTeam.name')} required>
            <Input
              size="full"
              value={name}
              onChange={setName}
              placeholder={t('editTeam.name.placeholder')}
            />
          </Form.Item>
          <Form.Item label={t('editTeam.desc')}>
            <Input.TextArea
              size="full"
              value={description}
              onChange={setDescription}
              rows={3}
              placeholder={t('editTeam.desc.placeholder')}
            />
          </Form.Item>
        </Form>
      </Modal.Body>
      <Modal.Footer>
        <Button
          type="primary"
          disabled={!canSubmit}
          loading={busy}
          onClick={() => onSave({ name: name.trim(), description: description.trim() })}
        >
          {t('editTeam.submit')}
        </Button>
        <Button onClick={onClose} disabled={busy}>{t('editTeam.cancel')}</Button>
      </Modal.Footer>
    </Modal>
  );
}

/**
 * MemberSection —— team 成员列表 + 移除操作。
 * AddMemberDialog / CreatedUserKeyModal —— 添加已有用户 / 新建用户弹窗。
 */

import { useState } from 'react';
import { Alert, Button, Copy, Form, Input, Modal, Segment, Select, Switch, Tag } from 'tea-component';
import { useTranslation } from 'react-i18next';
import { AddIcon, CloseIcon } from 'tea-icons-react';
import { isTeamAdmin, invalidateBackendCache, type Team } from '@/services';
import { membersApi, usersApi } from '@/lib/teamApi';
import { tea } from '@/lib/tea-bridge';
import { canRemoveMember } from './types';

// =================== Members section ===================

export function MemberSection({
  team,
  currentUser,
  onAdd,
  isAdmin: _globalAdmin,
}: {
  team: Team;
  currentUser: string;
  onAdd: () => void;
  isAdmin: boolean;
}) {
  const [removing, setRemoving] = useState<string | null>(null);
  const { t } = useTranslation();
  // 只有全局 admin 或 team admin/owner 才能添加成员；普通成员无此入口。
  const canAddMember = _globalAdmin || isTeamAdmin(team, currentUser);

  async function handleRemove(userId: string) {
    const ok = await tea.confirm({
      message: t('member.remove.confirm', { userId }),
      description: t('member.remove.desc'),
      okText: t('member.remove.ok'),
    });
    if (!ok) return;
    setRemoving(userId);
    try {
      await membersApi.remove(team.team_id, userId);
      invalidateBackendCache();
    } catch (err) {
      tea.notify.error(err);
    } finally {
      setRemoving(null);
    }
  }

  return (
    <div className="_memory-panel-card">
      <div className="_memory-section-header">
        <div className="_memory-section-header-info">
          <div className="_memory-section-header-title-row">
            <div className="_memory-section-title">{t('member.title', { count: team.members.length })}</div>
            <Tag size="sm">{team.team_id}</Tag>
          </div>
          <div className="_memory-section-subtitle">
            {t('member.subtitle', { name: team.name })}
          </div>
        </div>
        {canAddMember && (
          <Button onClick={onAdd} title={t('member.add.tooltip')} data-guide="add-member">
            <AddIcon size={14} /> {t('member.add')}
          </Button>
        )}
      </div>
      <div className="_memory-member-grid" data-guide="members-list">
        {team.members.map((m) => {
          const isOwner = team.owner_user_id === m.user_id;
          const canRemove = canRemoveMember(team, m.user_id, currentUser, _globalAdmin);
          return (
            <MemberCard
              key={m.user_id}
              user_id={m.user_id}
              username={m.username}
              role={m.role}
              isOwner={isOwner}
              isMe={m.user_id === currentUser}
              canRemove={canRemove}
              removing={removing === m.user_id}
              onRemove={() => void handleRemove(m.user_id)}
            />
          );
        })}
      </div>
    </div>
  );
}

function MemberCard({
  user_id,
  username,
  role,
  isOwner,
  isMe,
  canRemove,
  removing,
  onRemove,
}: {
  user_id: string;
  username?: string;
  role: 'admin' | 'member' | 'reviewer';
  isOwner: boolean;
  isMe: boolean;
  canRemove: boolean;
  removing: boolean;
  onRemove: () => void;
}) {
  const displayName = username?.trim() || user_id;
  const hasUsername = !!username?.trim();
  const { t } = useTranslation();

  return (
    <div className="_memory-member-card">
      <div className={`_memory-member-avatar${isOwner ? ' _memory-member-avatar--owner' : ''}`}>
        {displayName.slice(0, 2).toUpperCase()}
      </div>
      <div className="_memory-member-info">
        <div className="_memory-member-id">
          {displayName}
          {isMe && <span className="_memory-member-me-tag">{t('member.me')}</span>}
        </div>
        {hasUsername && (
          <div className="_memory-member-role" style={{ fontSize: '10px', color: 'var(--tea-color-text-tertiary)' }}>
            {user_id}
          </div>
        )}
        <div className="_memory-member-role">
          {role}
          {isOwner ? t('member.role.creator') : ''}
        </div>
      </div>
      <div className="_memory-member-actions">
        {canRemove && (
          <button
            type="button"
            onClick={(e) => { e.stopPropagation(); onRemove(); }}
            disabled={removing}
            className="_memory-member-remove-btn"
            title={t('member.remove.tooltip')}
            aria-label={t('member.remove.tooltip')}
          >
            {removing ? '…' : <CloseIcon size={12} />}
          </button>
        )}
      </div>
    </div>
  );
}

// =================== Add/create member dialog ===================

/**
 * 添加用户 — 两种模式：
 *   - 添加已有用户：按已知 user_id 加入 team
 *   - 新建用户并加入团队：调 meta/user/create 创建用户账号，再自动加入 team
 */
export function AddMemberDialog({
  team,
  onClose,
  onCreatedUser,
  currentUser,
  isAdmin: _globalAdmin,
}: {
  team: Team;
  onClose: () => void;
  /** 新建用户成功后，回调父组件展示初始 API Key */
  onCreatedUser?: (info: { username: string; userId: string; keyValue: string }) => void;
  currentUser: string;
  isAdmin: boolean;
}) {
  const [mode, setMode] = useState<'existing' | 'new'>('existing');
  const [userId, setUserId] = useState('');
  const [role, setRole] = useState<'admin' | 'member'>('member');
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const { t } = useTranslation();

  // 新建用户表单
  const [newUsername, setNewUsername] = useState('');
  // 自定义 user_key 开关（仅新建用户模式生效）：默认关 → 内核自动生成；开启 → 走 user/create-with-key
  const [customKeyEnabled, setCustomKeyEnabled] = useState(false);
  const [customKey, setCustomKey] = useState('');

  const canGrantAdmin = isTeamAdmin(team, currentUser) || _globalAdmin;
  // user/create 须 system_admin 权限（见 docs/api/metadata-api.md §1.4），
  // 非 全局 admin 调了必 403 —— 这里直接隐藏"新建用户"选项，避免用户操作后才报错。
  const canCreateUser = _globalAdmin;



  async function submitExisting() {
    const id = userId.trim();
    if (!id) {
      setError(t('addMember.error.emptyId'));
      return;
    }
    if (id === currentUser) {
      setError(t('addMember.error.self'));
      return;
    }
    setSubmitting(true);
    setError(null);
    try {
      await membersApi.add(team.team_id, { user_id: id, role });
      invalidateBackendCache();
      onClose();
    } catch (err) {
      tea.notify.error(err);
    } finally {
      setSubmitting(false);
    }
  }

  async function submitNew() {
    const username = newUsername.trim();
    if (!username) {
      setError(t('addMember.error.emptyName'));
      return;
    }
    // 用户名只允许英文字母、数字、下划线（与后端 user_id 段校验规则一致）
    if (!/^[A-Za-z0-9_]+$/.test(username)) {
      setError(t('addMember.error.invalidName'));
      return;
    }
    // 自定义 key 模式下额外校验 user_key 非空
    const trimmedKey = customKey.trim();
    if (customKeyEnabled && !trimmedKey) {
      setError(t('addMember.error.emptyKey'));
      return;
    }
    setSubmitting(true);
    setError(null);
    try {
      // Step 1: 创建用户
      //   - 默认走 meta/user/create（内核自动生成 default_user_key）
      //   - 开启「自定义 user_key」→ 走 meta/user/create-with-key，把 key 交给内核作为默认 key
      const created = customKeyEnabled
        ? await usersApi.createWithKey({ username, user_key: trimmedKey })
        : await usersApi.create({
            username,
            auth_provider: 'api_key',
            external_id: username,
          });
      const keyValue = created.default_user_key ?? '';
      // Step 3: 自动加入当前 team
      await membersApi.add(team.team_id, { user_id: created.user_id, role });
      invalidateBackendCache();
      // Step 4: 关闭添加弹窗，通过回调让父组件展示密钥弹窗
      onClose();
      onCreatedUser?.({
        username,
        userId: created.user_id,
        keyValue,
      });
    } catch (err) {
      tea.notify.error(err);
    } finally {
      setSubmitting(false);
    }
  }

  const canSubmit =
    mode === 'existing'
      ? userId.trim().length > 0
      : newUsername.trim().length > 0 &&
        /^[A-Za-z0-9_]+$/.test(newUsername.trim()) &&
        (!customKeyEnabled || customKey.trim().length > 0);

  async function handleSubmit() {
    if (mode === 'existing') await submitExisting();
    else await submitNew();
  }

  return (
    <Modal
      visible
      caption={<>{t('addMember.caption', { name: team.name })}<Tag size="sm">{team.team_id}</Tag></>}
      size="m"
      onClose={onClose}
      disableEscape={submitting}
    >
      <Modal.Body>
        {!canGrantAdmin && <Alert type="info">{t('addMember.adminOnlyHint')}</Alert>}
        <Form>
      <Form.Item label={t('addMember.mode')}>
        {canCreateUser ? (
          <Segment
            value={mode}
            onChange={(v) => {
              setMode(v as 'existing' | 'new');
              setError(null);
              if (v === 'new') setRole('member');
            }}
            options={[
              { value: 'existing', text: t('addMember.mode.existing') },
              { value: 'new', text: t('addMember.mode.new') },
            ]}
          />
        ) : (
          <div className="_memory-field-hint">
            {t('addMember.mode.hint')}
          </div>
        )}
      </Form.Item>

      {mode === 'existing' ? (
        <Form.Item label={t('addMember.userId')}>
          <div>
            <Input
              autoFocus
              size="full"
              value={userId}
              onChange={(v) => {
                setUserId(v);
                setError(null);
              }}
              onPressEnter={() => void handleSubmit()}
              placeholder={t('addMember.userId.placeholder')}
            />
            <div className="_memory-field-hint">{t('addMember.userId.hint')}</div>
          </div>
        </Form.Item>
      ) : (
        <>
          <Form.Item label={t('addMember.username')} required>
            <div>
              <Input
                autoFocus
                size="full"
                value={newUsername}
                onChange={(v) => {
                  setNewUsername(v);
                  setError(null);
                }}
                onPressEnter={() => void handleSubmit()}
                placeholder={t('addMember.username.placeholder')}
              />
              {newUsername.trim() && !/^[A-Za-z0-9_]+$/.test(newUsername.trim()) ? (
                <div className="_memory-field-hint" style={{ color: 'var(--tea-color-text-error-default)' }}>
                  {t('addMember.username.invalid')}
                </div>
              ) : (
                <div className="_memory-field-hint">{t('addMember.username.hint')}</div>
              )}
            </div>
          </Form.Item>

          {/*
            自定义 user_key 开关：
            - 关（默认）：走 user/create，内核自动生成 default_user_key（现有行为）
            - 开：走 user/create-with-key，把用户指定的 key 作为默认 key
          */}
          <Form.Item label={t('addMember.customKey.label')}>
            <div>
              <Switch
                value={customKeyEnabled}
                onChange={(v) => {
                  setCustomKeyEnabled(v);
                  setError(null);
                  if (!v) setCustomKey('');
                }}
              />
              <div className="_memory-field-hint">{t('addMember.customKey.hint')}</div>
            </div>
          </Form.Item>

          {customKeyEnabled && (
            <Form.Item label={t('addMember.customKey.value')} required>
              <div>
                <Input
                  size="full"
                  value={customKey}
                  onChange={(v) => {
                    setCustomKey(v);
                    setError(null);
                  }}
                  onPressEnter={() => void handleSubmit()}
                  placeholder={t('addMember.customKey.placeholder')}
                />
                <div className="_memory-field-hint">{t('addMember.customKey.valueHint')}</div>
              </div>
            </Form.Item>
          )}
        </>
      )}

      <Form.Item label={t('addMember.role')}>
        <Select
          size="full"
          value="member"
          disabled
          options={[
            { value: 'member', text: t('addMember.role.default') },
          ]}
        />
        <div className="_memory-field-hint">{t('addMember.role.hint')}</div>
      </Form.Item>
          {error && <Form.Item><Alert type="error">{error}</Alert></Form.Item>}
        </Form>
      </Modal.Body>
      <Modal.Footer>
        <Button type="primary" onClick={() => void handleSubmit()} disabled={!canSubmit || submitting} loading={submitting}>
          {mode === 'existing' ? t('addMember.existing.submit') : t('addMember.new.submit')}
        </Button>
        <Button onClick={onClose} disabled={submitting}>{t('addMember.cancel')}</Button>
      </Modal.Footer>
    </Modal>
  );
}

/**
 * 创建用户成功后展示初始 API Key —— 仅此一次，关闭后无法再次获取。
 */
export function CreatedUserKeyModal({
  info,
  onClose,
}: {
  info: { username: string; userId: string; keyValue: string };
  onClose: () => void;
}) {
  const [copied, setCopied] = useState(false);
  const { t } = useTranslation();

  return (
    <Modal visible caption={t('createdUserKey.caption')} size="m" onClose={onClose}>
      <Modal.Body>
        <Form>
          <Alert type="success">{t('createdUserKey.success', { username: info.username, userId: info.userId })}</Alert>
          <div className="space-y-4 text-[13px]">
        {info.keyValue ? (
          <>
            <Alert type="warning">
              <strong>{t('createdUserKey.warning')}</strong>
            </Alert>
            <Form.Item label={t('createdUserKey.keyLabel')}>
              <div className="flex items-center gap-2">
                <code className="flex-1 rounded border bg-muted px-3 py-2 text-[12px] font-mono break-all select-all">
                  {info.keyValue}
                </code>
                <Copy text={info.keyValue}>
                  <Button onClick={() => setCopied(true)}>
                    {copied ? t('createdUserKey.copied') : t('createdUserKey.copy')}
                  </Button>
                </Copy>
              </div>
            </Form.Item>
          </>
        ) : (
          <Alert type="warning">
            {t('createdUserKey.noKey')}
            <code
              className="mt-1 block rounded px-2 py-1 text-[12px] font-mono select-all"
              style={{ background: 'var(--tea-color-bg-primary-default)' }}
            >
              {info.userId}
            </code>
          </Alert>
        )}
          </div>
        </Form>
      </Modal.Body>
      <Modal.Footer>
        <Button type="primary" onClick={onClose}>{t('createdUserKey.close')}</Button>
      </Modal.Footer>
    </Modal>
  );
}

/**
 * TeamHeaderCard — 当前 team 概览卡片（头像 + 名称 + team_id + 成员数 + 描述）。
 *
 * 抽自 TeamManagementPanel 头部，供 team 管理页与 Task 工作台等页面复用，
 * 统一「我现在操作的是哪个 team」的展示。样式类定义在 team-management-panel.css。
 */

import type { ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import { Tag } from 'tea-component';
import type { Team } from '@/services';

export function TeamHeaderCard({ team, ops }: { team: Team; ops?: ReactNode }) {
  const { t } = useTranslation();
  return (
    <div className="_memory-panel-card">
      <div className="_memory-team-header-row">
        <div className="_memory-team-header-info">
          <div className="_memory-team-header-avatar">
            {team.name.slice(0, 1).toUpperCase()}
          </div>
          <div className="_memory-team-header-meta">
            <div className="_memory-team-header-meta-row">
              <span className="_memory-team-header-name">{team.name}</span>
              <Tag size="sm">{team.team_id}</Tag>
              <span className="_memory-team-header-count">
                {t('team.memberCount', { count: team.members.length })}
              </span>
            </div>
            {team.description && (
              <div className="_memory-team-header-desc">{team.description}</div>
            )}
          </div>
        </div>
        {ops && <div className="_memory-team-header-ops">{ops}</div>}
      </div>
    </div>
  );
}

/**
 * TeamManagementPanel — 团队管理。
 *
 * 承担「Team + 成员 + Agent」管理：
 *   - 顶部是当前 team 概览 + team 级操作入口（仅新建 Team）；
 *     团队级「编辑 / 删除」已统一迁到左上角 TeamSwitcher 下拉框（active team 行右侧），
 *     不再在此面板重复入口。
 *   - 中部是当前 team 的成员管理：按 user_id 添加 / 删除成员
 *   - 下部是当前 team 的 Agent 卡片网格：新建 / 编辑 / 删除
 *
 * 数据存储（后端持久化）：
 *   - team/members/agent 均走 @/lib/teamApi；
 *   - 写操作成功后统一调用 invalidateBackendCache()，驱动 useTeams/useAgents 重新拉取；
 *   - 后端 schema 还没有的展示字段，序列化进 agent.metadata_json 的 "ui" namespace。
 *
 * 已知限制（如实反映后端当前能力，不做假 UI）：
 *   - Agent owner 由后端在创建时固定为当前登录用户，暂不支持转交；
 *   - Team 删除为级联操作（连带删除成员/agent/task/资产），仅 owner / admin 可删
 *     （入口在 TeamSwitcher 下拉框）。
 *
 * 文件拆分（本文件仅保留组合/编排逻辑，具体实现见同目录下）：
 *   - types.ts / useAgentAssets.ts / shared.tsx / AgentGrid.tsx / MemberSection.tsx /
 *     CreateTeamDialog.tsx / CreateAgentDialog.tsx / AgentEditDialog.tsx
 *   - EditTeamDialog 已迁到 TeamSwitcher 共用（@/layouts/GlobalHeader/TeamSwitcher）
 */

import { useState, useMemo } from 'react';
import { Button } from 'tea-component';
import { useTranslation } from 'react-i18next';
import { UsergroupIcon, AddIcon } from 'tea-icons-react';
import {
  useTeams,
  useAgents,
  isTeamAdmin,
  canManageAsset,
  invalidateBackendCache,
  writeAgentUiMeta,
  type Agent as StoreAgent,
} from '@/services';
import { teamsApi, agentsApi, skillApi } from '@/lib/teamApi';
import { knowledgeApi } from '@/lib/api/knowledge-api';
import { useDisplayNameResolver } from '@/services/user-profile-store';
import { tea } from '@/lib/tea-bridge';
import { getErrorMessage } from '@/lib/error-message';
import './team-management-panel.css';

import { MAX_IMPORTED_CHAT_MEMORIES, importedChatMemoryIds, type AgentCard } from './types';
import { useAgentMountedCounts, syncChatMemoryBindings } from './useAgentAssets';
import AgentGrid from './AgentGrid';
import { TeamHeaderCard } from './TeamHeaderCard';
import { MemberSection, AddMemberDialog, CreatedUserKeyModal } from './MemberSection';
import CreateTeamDialog from './CreateTeamDialog';
import CreateAgentDialog from './CreateAgentDialog';
import AgentEditDialog from './AgentEditDialog';
import DefaultAgentTemplateSection from './DefaultAgentTemplateSection';

function errMsg(e: unknown): string {
  return getErrorMessage(e);
}

// =================== Component ===================

export default function TeamManagementPanel({
  currentUser,
  instanceId: _instanceId,
  isAdmin: _isAdmin,
  section = 'all',
}: {
  currentUser: string;
  instanceId: string;
  isAdmin: boolean;
  /**
   * 控制本面板渲染哪一块内容（拆 tab 用，功能完全不变）：
   *   - 'members'：仅成员管理
   *   - 'agents' ：仅 Agent 管理
   *   - 'all'    ：两者都渲染（向后兼容旧的单页用法）
   */
  section?: 'members' | 'agents' | 'all';
}) {
  const showMembers = section === 'members' || section === 'all';
  const showAgents = section === 'agents' || section === 'all';
  const { activeTeamId, activeTeam, loading: teamsLoading } = useTeams();
  // 只取当前 team 的 agent — agent 严格归属 team，不会跨 team 显示
  const { agents: allAgents, loading: agentsLoading } = useAgents(activeTeamId);
  const { t } = useTranslation();
  // Agent 可见性：
  //   - 全局 admin / 当前 team 的 admin(owner)：可见 team 内全部 agent
  //   - 普通成员：只能看到自己 owner（创建）的 agent
  const canSeeAllAgents = !!activeTeam && (_isAdmin || isTeamAdmin(activeTeam, currentUser));
  const agents = useMemo(() => {
    if (!activeTeam || canSeeAllAgents) return allAgents;
    return allAgents.filter((a) => a.owner_user_id === currentUser);
  }, [allAgents, activeTeam, canSeeAllAgents, currentUser]);
  const { counts: mountedCounts, countsLoading } = useAgentMountedCounts(activeTeamId, agents);
  // 通知文案里展示 display_name 而非 user_id（复用全局缓存，幂等无额外请求）
  const resolveUserName = useDisplayNameResolver();

  const [showCreateAgent, setShowCreateAgent] = useState(false);
  const [showCreateTeam, setShowCreateTeam] = useState(false);
  const [showAddMember, setShowAddMember] = useState(false);
  const [editingAgent, setEditingAgent] = useState<StoreAgent | null>(null);
  const [busy, setBusy] = useState(false);
  const [createdUserKeyInfo, setCreatedUserKeyInfo] = useState<{
    username: string;
    userId: string;
    keyValue: string;
  } | null>(null);

  async function handleCreateAgent(card: Omit<AgentCard, 'id' | 'icon' | 'accent'>) {
    if (!activeTeamId || !activeTeam) return;
    if (
      importedChatMemoryIds(activeTeamId, '__new_agent__', card.chatMemories).length >
      MAX_IMPORTED_CHAT_MEMORIES
    ) {
      tea.notify.error('IMPORT_LIMIT_EXCEEDED');
      return;
    }
    const accents: AgentCard['accent'][] = ['blue', 'purple', 'orange', 'emerald', 'rose', 'slate'];
    const icons = ['🤖', '✨', '⚡', '🎯', '🚀', '🧩'];
    const accent = accents[agents.length % accents.length];
    const icon = icons[agents.length % icons.length];
    setBusy(true);
    try {
      const created = await agentsApi.create(activeTeamId, {
        name: card.name,
        description: card.description,
        prompt: [card.rolePrompt, card.rulesPrompt].filter(Boolean).join('\n\n'),
        visibility: 'team',
      });
      const metadataJson = writeAgentUiMeta(created.metadata_json, {
        role_prompt: card.rolePrompt,
        rules_prompt: card.rulesPrompt,
        icon,
        accent,
      });
      await agentsApi.update(created.agent_id, { metadata_json: metadataJson });

      // 资产绑定统一走真实挂载接口（不写 metadata_json.ui）。串行执行，任一失败即抛错，
      // 由外层 catch 统一提示 —— 避免 allSettled 静默导致「显示绑了但实际没绑」。
      //   - skill → forkToAgent（复制 owner=新 agent 的独立副本）
      //   - code_graph / wiki → allocate（引用绑定）
      //   - chat_memory → syncChatMemoryBindings
      await syncChatMemoryBindings(activeTeamId, created.agent_id, card.chatMemories);
      for (const skillId of card.skills) {
        await skillApi.forkToAgent(activeTeamId, skillId, created.agent_id);
      }
      for (const id of card.codeGraphs) {
        await knowledgeApi.code.allocate(activeTeamId, id, created.agent_id);
      }
      for (const id of card.llmWikis) {
        await knowledgeApi.wiki.allocate(activeTeamId, id, created.agent_id);
      }

      invalidateBackendCache();
    } catch (err) {
      tea.notify.error(errMsg(err));
      setBusy(false);
      return;
    }
    setBusy(false);
    setShowCreateAgent(false);
  }

  async function handleDeleteAgent(agent: StoreAgent) {
    if (!activeTeamId || !activeTeam) return;
    if (
      !canManageAsset(
        { owner_user_id: agent.owner_user_id, team_id: agent.team_id },
        activeTeam,
        currentUser,
        false,
      )
    ) {
      tea.notify.error(
        t('team.deleteAgent.noPermission', { name: agent.name, id: agent.agent_id, teamName: activeTeam.name, owner: agent.owner_user_id ? resolveUserName(agent.owner_user_id) : t('team.deleteAgent.ownerUnset') }),
      );
      return;
    }
    const ok = await tea.confirm({
      message: t('team.deleteAgent.confirm', { name: agent.name }),
      description: t('team.deleteAgent.desc', { id: agent.agent_id }),
      okText: t('common.delete'),
    });
    if (!ok) return;
    try {
      await agentsApi.delete(agent.agent_id);
      invalidateBackendCache();
    } catch (err) {
      // SKILL_DELETE_FAILED：控制台层已删了一部分 skill 但被中断，agent 未 archive
      // —— 明确告诉用户去 skill 面板处理后重试，别只给一句技术错误码
      const raw = err instanceof Error ? err.message : String(err);
      if (raw.includes('SKILL_DELETE_FAILED')) {
        tea.notify.error(
          t('team.deleteAgent.skillFailed', { name: agent.name, raw }),
        );
      } else {
        tea.notify.error(errMsg(err));
      }
    }
  }

  async function handleCreateTeam(input: { name: string; description: string }) {
    setBusy(true);
    try {
      await teamsApi.create(input);
      invalidateBackendCache();
    } catch (err) {
      tea.notify.error(errMsg(err));
      setBusy(false);
      return;
    }
    setBusy(false);
    setShowCreateTeam(false);
  }

  return (
    <div className="_memory-team-mgmt">
      {/* === Header: 当前 team 概览 + ops ===
        切 team 的入口只在左上角全局 TeamSwitcher（App.tsx），这里不再提供
        平铺 chips 的切换入口，避免跟全局切换器形成两个语义重叠的控件。
        本卡片只承担三件事：
          1. 告诉用户「我现在操作的是哪个 team」（name + team_id + 成员数 + 描述）
          2. 提供 team 级的操作（+ 新建 Team / + 新建 Agent）
          3. 当尚未选 team 时，给出引导 */}
      {teamsLoading ? (
        <div className="_memory-panel-card">
          <div className="_memory-team-header-row">
            <div className="_memory-team-header-info">
              <div className="_memory-team-header-avatar" style={{ opacity: 0.3 }}>
                …
              </div>
              <div className="_memory-team-header-meta">
                <div className="_memory-team-header-meta-row">
                  <span
                    className="_memory-team-header-name"
                    style={{ color: 'var(--muted-foreground)' }}
                  >
                    {t('team.loading')}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>
      ) : activeTeam ? (
        <TeamHeaderCard
          team={activeTeam}
          ops={
            <>
              {_isAdmin && (
                <Button onClick={() => setShowCreateTeam(true)} title={t('team.createTeam')}>
                  <AddIcon size={14} /> {t('team.createTeam')}
                </Button>
              )}
            </>
          }
        />
      ) : (
        <div className="_memory-panel-card">
          <div className="_memory-team-header-row">
            <div className="_memory-team-header-empty-hint">
              {t('team.empty.hint')}
            </div>
          </div>
        </div>
      )}

      {teamsLoading ? (
        <div
          className="_memory-panel-card"
          style={{ padding: '2rem', textAlign: 'center', color: 'var(--muted-foreground)' }}
        >
          {t('team.loading')}
        </div>
      ) : !activeTeam ? (
        <EmptyTeamState
          onCreateTeam={_isAdmin ? () => setShowCreateTeam(true) : undefined}
        />
      ) : (
        <>
          {/* === Members === */}
          {showMembers && (
            <MemberSection
              team={activeTeam}
              currentUser={currentUser}
              onAdd={() => setShowAddMember(true)}
              isAdmin={_isAdmin}
            />
          )}

          {/* === 默认 Agent 模板（仅全局 admin 可见）=== */}
          {showAgents && _isAdmin && (
            <DefaultAgentTemplateSection
              teamId={activeTeam.team_id}
              teamName={activeTeam.name}
            />
          )}

          {/* === Agent grid === */}
          {showAgents && (
            <AgentGrid
              activeTeam={activeTeam}
              agents={agents}
              agentsLoading={agentsLoading}
              countsLoading={countsLoading}
              mountedCounts={mountedCounts}
              currentUser={currentUser}
              isAdmin={_isAdmin}
              canSeeAllAgents={canSeeAllAgents}
              onCreateAgent={() => setShowCreateAgent(true)}
              onEditAgent={setEditingAgent}
              onDeleteAgent={handleDeleteAgent}
            />
          )}
        </>
      )}

      {/* Modals */}
      {showCreateTeam && (
        <CreateTeamDialog
          onClose={() => setShowCreateTeam(false)}
          onCreate={handleCreateTeam}
          busy={busy}
        />
      )}
      {showCreateAgent && activeTeam && (
        <CreateAgentDialog
          team={{ team_id: activeTeam.team_id, name: activeTeam.name }}
          currentUser={currentUser}
          onClose={() => setShowCreateAgent(false)}
          onCreated={handleCreateAgent}
          busy={busy}
        />
      )}
      {showAddMember && activeTeam && (
        <AddMemberDialog
          team={activeTeam}
          onClose={() => setShowAddMember(false)}
          onCreatedUser={setCreatedUserKeyInfo}
          currentUser={currentUser}
          isAdmin={_isAdmin}
        />
      )}
      {createdUserKeyInfo && (
        <CreatedUserKeyModal
          info={createdUserKeyInfo}
          onClose={() => setCreatedUserKeyInfo(null)}
        />
      )}
      {editingAgent && activeTeam && (
        <AgentEditDialog
          agent={editingAgent}
          onClose={() => setEditingAgent(null)}
        />
      )}
    </div>
  );
}

// =================== Empty state ===================

/**
 * 空态引导。
 *
 * 历史行为：任何已登录用户都能创建自己的第一个 team（team/create 无 admin 限制，
 * 创建者自动成为 owner），所以这里曾不区分 admin / 非 admin。
 *
 * 现行行为：前端暂时屏蔽普通用户创建 team 的入口，
 * 仅 admin 可见创建 CTA；普通用户只看到"联系管理员"提示。
 * 后端 team/create 本身仍无角色限制，此屏蔽仅在前端实现。
 */
function EmptyTeamState({ onCreateTeam }: { onCreateTeam?: () => void }) {
  const { t } = useTranslation();
  return (
    <div className="_memory-empty-team">
      <UsergroupIcon size={32} className="_memory-empty-team-icon" />
      <div className="_memory-empty-team-title">{t('team.emptyTeam.title')}</div>
      <div className="_memory-empty-team-desc">
        {onCreateTeam ? t('team.emptyTeam.desc') : t('team.emptyTeam.contactAdmin')}
      </div>
      {onCreateTeam && (
        <Button type="primary" onClick={onCreateTeam} className="_memory-empty-team-cta">
          <AddIcon size={14} /> {t('team.emptyTeam.cta')}
        </Button>
      )}
    </div>
  );
}

/**
 * 公共展示型小组件：
 *   - Mounted：Agent 卡片上的「已挂载资产」计数 chip
 *   - LightField：轻量表单字段（label + hint + children）
 *   - CollapseGroup：可折叠分组（skills / code_graph / llm_wiki / chat_memory 复选列表容器）
 *   - AssetCheckList：分组渲染的资产复选框列表
 *
 * 均为纯展示组件，不含业务逻辑 / 数据请求。
 */

import { type ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import { Checkbox } from 'tea-component';
import { ChevronRightIcon } from 'tea-icons-react';
import type { MountableAsset } from './types';

/** 资产是否可被勾选/挂载：无状态（skill）或状态为 ready 才可选中，其他状态（pending/failed/...）视为不可用。 */
export function isAssetSelectable(a: MountableAsset): boolean {
  return !a.status || a.status === 'ready';
}

/** 过滤出全部可勾选的资产 key（供「一键全选」使用，保证与列表勾选禁用状态一致）。 */
export function selectableAssetKeys(assets: MountableAsset[]): string[] {
  return assets.filter(isAssetSelectable).map((a) => a.key);
}

export function Mounted({ label, count, loading = false }: { label: string; count: number; loading?: boolean }) {
  // counts 还在加载时，单独把数字区换成骨架占位，不动 label。
  // 让 agent 卡片主体立刻可见（避免「4 骨架 → 1 真实卡」的突兀跳变），
  // 只把不确定的计数数据占位起来，比整个网格保留骨架更平滑。
  return (
    <div className={`_memory-mounted-chip${loading ? ' _memory-mounted-chip--loading' : ''}`}>
      <span className="_memory-mounted-chip-label">{label}</span>
      {loading ? (
        <span className="_memory-mounted-chip-count _memory-mounted-chip-count--loading" aria-label="loading" />
      ) : (
        <span className="_memory-mounted-chip-count">{count}</span>
      )}
    </div>
  );
}

export function LightField({
  label,
  hint,
  children,
}: {
  label: string;
  hint?: string;
  children: ReactNode;
}) {
  return (
    <label className="_memory-light-field">
      <div className="_memory-light-field-label">{label}</div>
      {hint && <div className="_memory-light-field-hint">{hint}</div>}
      {children}
    </label>
  );
}

export function CollapseGroup({
  icon,
  title,
  selectedCount,
  totalCount,
  open,
  onToggle,
  hideTotal = false,
  loading = false,
  children,
}: {
  icon: ReactNode;
  title: string;
  selectedCount: number;
  totalCount: number;
  open: boolean;
  onToggle: () => void;
  /** 只展示已绑定数量、不展示团队池总数（用于只读详情场景）。 */
  hideTotal?: boolean;
  /**
   * 加载态：count 数字区换成骨架占位（保留 label/title 等结构，避免布局抖动）。
   * 用于详情弹窗打开时资产绑定还没拉完的场景，避免「已选 0/共 0 → 真实数字」的突兀跳变。
   */
  loading?: boolean;
  children: ReactNode;
}) {
  const { t } = useTranslation();
  return (
    <div className={`_memory-collapse-group${loading ? ' _memory-collapse-group--loading' : ''}`}>
      <button type="button" onClick={onToggle} className="_memory-collapse-group-header" disabled={loading}>
        <ChevronRightIcon
          size={12}
          className={`_memory-collapse-group-chevron${open ? ' _memory-collapse-group-chevron--open' : ''}`}
        />
        <span className="_memory-collapse-group-icon">{icon}</span>
        <span className="_memory-collapse-group-title">{title}</span>
        {loading ? (
          // 加载中：保留图标 + 标题，仅把 count 区换成骨架；按钮禁用防止「加载中点开」出现空面板
          <span className="_memory-collapse-group-count _memory-collapse-group-count--loading" aria-label="loading" />
        ) : (
          <span className="_memory-collapse-group-count">
            {hideTotal ? t('shared.bound', { count: selectedCount }) : t('shared.selected', { selected: selectedCount, total: totalCount })}
          </span>
        )}
      </button>
      {open && !loading && <div className="_memory-collapse-group-body">{children}</div>}
    </div>
  );
}

export function AssetCheckList({
  assets,
  checkedKeys,
  onToggle,
  readOnly = false,
  disabledKeys = new Set<string>(),
}: {
  assets: MountableAsset[];
  checkedKeys: string[];
  onToggle: (key: string) => void;
  readOnly?: boolean;
  disabledKeys?: Set<string>;
}) {
  const { t } = useTranslation();
  const groups = new Map<string, MountableAsset[]>();
  for (const a of assets) {
    if (!groups.has(a.group)) groups.set(a.group, []);
    groups.get(a.group)!.push(a);
  }
  return (
    <div className="_memory-asset-check-groups">
      {Array.from(groups.entries()).map(([group, items]) => (
        <div key={group}>
          <div className="_memory-asset-check-group-label">{group}</div>
          <ul className="_memory-asset-check-list">
            {items.map((a) => {
              const checked = checkedKeys.includes(a.key);
              const notReady = !isAssetSelectable(a);
              const disabled = readOnly || disabledKeys.has(a.key) || notReady;
              return (
                <li key={a.key} className="_memory-asset-check-item">
                  <Checkbox value={checked} disabled={disabled} onChange={() => { if (!disabled) onToggle(a.key); }}>
                    <span className="_memory-asset-check-item-row">
                      <span className="_memory-asset-check-item-title">{a.title}</span>
                      <span className="_memory-asset-check-item-slug">
                        {a.slug}{disabledKeys.has(a.key) ? t('shared.selfMemory') : notReady ? ` · ${a.status}` : ''}
                      </span>
                    </span>
                  </Checkbox>
                </li>
              );
            })}
          </ul>
        </div>
      ))}
    </div>
  );
}

/**
 * 公共类型 + 纯函数。
 * 无 React 依赖，方便被 hooks / 各 Dialog 子模块共用。
