  const [creating, setCreating] = useState(false);
  // 编辑弹窗可见状态
  const [editingTeamId, setEditingTeamId] = useState<string | null>(null);

  const myTeams = teams;
  const active = myTeams.find((tm) => tm.team_id === activeTeamId) ?? null;
  // 当前用户 user_id（panelSession 同步可读）
  const currentUserId = getPanelSession()?.user?.user_id ?? '';
  // 是否可编辑 / 删除当前 active team：全局 admin 或当前 team 的 owner / admin
  const canManageActiveTeam =
    !!active && (userRole === 'admin' || isTeamAdmin(active, currentUserId));

  function resetCreateForm() {
    setShowCreateTeam(false);
    setNewTeamName('');
    setNewTeamDesc('');
  }

  function pick(team_id: string, close: () => void) {
    // 只切换 activeTeamId，不 invalidateTeamCache：
    //  - useAgents/useTasks 按 teamId 分桶缓存，切到目标 team 时若已有缓存（之前看过）
    //    会直接秒开，无需重新 loading；无缓存才走 fetch —— 这才是"自动刷新"而不是
    //    "整页重刷"。
    //  - invalidateTeamCache 会删目标 team 缓存 + 广播 BACKEND_REFRESH_EVENT，
    //    导致切 team 后所有页面（含 counts/participation 等无关数据）连带重新拉取，
    //    表现为"切换一次 = 全部重新刷新一次"。写操作后的 invalidateBackendCache
    //    已经保证数据新鲜度，切换本身不需要再强刷。
    writeActiveTeamId(team_id);
    close();
  }

  async function handleCreate() {
    const name = newTeamName.trim();
    if (!name) return;
    setCreating(true);
    try {
      const created = await teamsApi.create({ name, description: newTeamDesc.trim() });
      invalidateBackendCache();
      writeActiveTeamId(created.team_id);
      resetCreateForm();
    } catch (err) {
      tea.notify.error(getErrorMessage(err));
    } finally {
      setCreating(false);
    }
  }

  async function handleUpdateTeam(input: { name: string; description: string }) {
    const id = editingTeamId;
    if (!id) return;
    try {
      await teamsApi.update(id, input);
      invalidateBackendCache();
      setEditingTeamId(null);
    } catch (err) {
      tea.notify.error(getErrorMessage(err));
    }
  }

  async function handleDeleteTeam(teamId: string, teamName: string, memberCount: number) {
    // 取一次 agent 数（用于级联展示）—— 走 store 缓存避免额外请求
    let agentCount = 0;
    try {
      const cached = useBackendStore.getState().agentsByTeam[teamId];
      if (cached) agentCount = cached.length;
    } catch {
      /* 静默：仅用于展示级联范围，拿不到不影响删除 */
    }
    const ok = await tea.confirm({
      message: t('teamSwitcher.delete.confirm', { name: teamName }),
      description: t('teamSwitcher.delete.desc', {
        members: memberCount,
        agents: agentCount,
      }),
      okText: t('common.delete'),
    });
    if (!ok) return;
    try {
      await teamsApi.delete(teamId);
      // 删除当前 active team 时清空 activeTeamId，让 ensureValidActiveTeamId
      // 在 store 刷新后自动落到剩余的第一个 team（或空态）。
      if (teamId === activeTeamId) writeActiveTeamId(null);
      invalidateBackendCache();
    } catch (err) {
      tea.notify.error(getErrorMessage(err));
    }
  }

  const editingTeam = editingTeamId ? myTeams.find((tm) => tm.team_id === editingTeamId) ?? null : null;

  return (
    <>
      <Dropdown
        appearance="pure"
        clickClose={false}
        matchButtonWidth={false}
        className="_memory-team-switcher-dropdown"
        boxClassName="_memory-team-switcher-box"
        // 静默刷新：仅让下拉框里的 team 列表保新鲜，不翻转 teamsLoading，
        // 否则 TeamManagementPanel 等消费方会整体进入 loading 占位（表现为
        // "点开选择 team 的选项框，成员/Agents 管理页面就刷新一下"）。
        onOpen={() => { void refreshTeams({ silent: true }); }}
        onClose={resetCreateForm}
        button={
          <button
            type="button"
            className="_memory-team-switcher-trigger"
            title={active?.name ?? t('teamSwitcher.selectTeam')}
          >
            <span className={`_memory-team-switcher-avatar ${active ? teamColor(active.team_id) : 'bg-primary'}`}>
              {(active?.name ?? '?').slice(0, 1).toUpperCase()}
            </span>
            <span className="_memory-team-switcher-meta">
              <span className="_memory-team-switcher-name">{active?.name ?? t('teamSwitcher.selectTeam')}</span>
              <span className="_memory-team-switcher-id">{active?.team_id ?? t('teamSwitcher.noTeam')}</span>
            </span>
            <ChevronDownIcon size={12} className="_memory-team-switcher-chevron" />
          </button>
        }
      >
        {(close) => (
          <div className="_memory-team-switcher-panel">
            <div className="_memory-team-switcher-panel-header">
              <div className="_memory-team-switcher-panel-title">{t('teamSwitcher.title')}</div>
              <div className="_memory-team-switcher-panel-desc">
                {t('teamSwitcher.desc')}
              </div>
            </div>

            <div className="_memory-team-switcher-panel-label">{t('teamSwitcher.teamCount', { count: myTeams.length })}</div>

            <div className="_memory-team-switcher-list-wrap">
              {myTeams.length === 0 ? (
                <div className="_memory-team-switcher-empty">
                  {userRole === 'admin'
                    ? t('teamSwitcher.empty.admin')
                    : t('teamSwitcher.empty.member')}
                </div>
              ) : (
                // 用原生 ul/li 而非 Tea List：Tea 的 List.Item selected 会自动渲染 ✓
                // 并改变内边距，split="divide" 又会注入 padding/border-top，与自定义
                // 卡片式行样式（圆角 + 描边 + 间距）反复冲突（表现为选中行左侧被裁切、
                // 行分割线被上一行压住）。这里自己掌控全部样式，行为更可控。
                <ul className="_memory-team-switcher-list">
                  {myTeams.map((tm) => {
                    const isActive = tm.team_id === activeTeamId;
                    // 仅当前 active team 行显示编辑/删除按钮，且仅 owner/admin 可操作
                    const showOps = isActive && canManageActiveTeam;
                    return (
                      <li key={tm.team_id} className="_memory-team-switcher-row">
                        <button
                          type="button"
                          className={`_memory-team-switcher-item${isActive ? ' is-active' : ''}`}
                          aria-current={isActive || undefined}
                          onClick={() => pick(tm.team_id, close)}
                        >
                          <span className={`_memory-team-switcher-item-avatar ${teamColor(tm.team_id)}`}>
                            {tm.name.slice(0, 1).toUpperCase()}
                          </span>
                          <span className="_memory-team-switcher-item-meta">
                            <span className="_memory-team-switcher-item-name">{tm.name}</span>
                            <span className="_memory-team-switcher-item-count">
                              {t('teamSwitcher.memberCount', { count: tm.members.length })}
                            </span>
                          </span>
                          {/* 选中态由背景色 + 描边传达，不再额外显示 ✓ —— 避免与右侧
                              操作按钮挤在一起。操作按钮为绝对定位浮层，不占行内布局宽度。 */}
                        </button>
                        {showOps && (
                          <span className="_memory-team-switcher-item-ops">
                            <button
                              type="button"
                              className="_memory-team-switcher-item-op"
                              title={t('teamSwitcher.edit.tooltip')}
                              aria-label={t('teamSwitcher.edit.tooltip')}
                              onClick={() => setEditingTeamId(tm.team_id)}
                            >
                              <EditIcon size={14} />
                            </button>
                            <button
                              type="button"
                              className="_memory-team-switcher-item-op _memory-team-switcher-item-op-danger"
                              title={t('teamSwitcher.delete.tooltip')}
                              aria-label={t('teamSwitcher.delete.tooltip')}
                              onClick={() => {
                                void handleDeleteTeam(tm.team_id, tm.name, tm.members.length);
                              }}
                            >
                              <DeleteIcon size={14} />
                            </button>
                          </span>
                        )}
                      </li>
                    );
                  })}
                </ul>
              )}
            </div>

            <div className="_memory-team-switcher-footer">
              {userRole !== 'admin' ? null : showCreateTeam ? (
                <div className="_memory-team-switcher-create-form">
                  <Input
                    autoFocus
                    size="full"
                    value={newTeamName}
                    onChange={setNewTeamName}
                    placeholder={t('teamSwitcher.teamNamePlaceholder')}
                  />
                  <Input
                    size="full"
                    value={newTeamDesc}
                    onChange={setNewTeamDesc}
                    placeholder={t('teamSwitcher.teamDescPlaceholder')}
                  />
                  <div className="_memory-team-switcher-create-actions">
                    <Button onClick={resetCreateForm}>{t('teamSwitcher.cancel')}</Button>
                    <Button type="primary"
                      loading={creating}
                      disabled={!newTeamName.trim() || creating}
                      onClick={handleCreate}
                    >
                      {t('teamSwitcher.create')}
                    </Button>
                  </div>
                </div>
              ) : (
                <Button type="text"
                  className="_memory-team-switcher-create-trigger"
                  onClick={() => setShowCreateTeam(true)}
                >
                  <AddIcon size={14} />
                  {t('teamSwitcher.newTeam')}
                </Button>
              )}
            </div>
          </div>
        )}
      </Dropdown>

      {/* 编辑弹窗挂在 Dropdown 之外：避免 Dropdown clickClose 干扰 Modal 可见性 */}
      {editingTeam && (
        <EditTeamDialog
          team={editingTeam}
          onClose={() => setEditingTeamId(null)}
          onSave={handleUpdateTeam}
          busy={false}
        />
      )}
    </>
  );
}

/**
 * GlobalHeader — 全局顶栏（跨越侧边栏 + 内容区，最外层通栏）
 *
 *   左侧：品牌 Logo「Memory Hub」 + 分隔线 + 团队切换器（TeamSwitcher）
 *   右侧：同步状态指示 + 语言切换 + 用户头像菜单
 */
import { useState } from 'react';
import {
  Avatar,
  Button,
  Copy,
  Dropdown,
  Input,
  InputAdornment,
  Justify,
  List,
  Modal,
  Tag,
  Text,
} from 'tea-component';
import { SettingIcon } from 'tea-icons-react';
import { useTranslation } from 'react-i18next';
import { useLocation, useNavigate } from 'react-router-dom';
import { SettingsDialog } from '@/components/SettingsDialog';
import { type TeamRole } from '@/services/useCurrentRole';
import { TeamSwitcher } from './TeamSwitcher';
import { LanguageSwitcher } from './LanguageSwitcher';
import './style.css';

export function GlobalHeader({
  userRole,
  currentUser,
  currentUserId,
  instanceName,
  onReplayOnboarding,
  onLogout,
}: {
  userRole: TeamRole | null;
  currentUser: string;
  currentUserId?: string;
  /** 当前登录所在的 memory 实例名（来自 auth.instance_name），用于「我的资料」展示 */
  instanceName?: string;
  /**
   * 「回顾引导」入口回调：ConsoleLayout 注入。
   * 未传则下拉菜单不展示该项，避免在「尚未拿到 auth」等中间态误出。
   */
  onReplayOnboarding?: () => void;
  onLogout: () => void;
}) {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const location = useLocation();
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);

  return (
    <header className="_memory-global-header">
      {/* 左侧：品牌 + 团队切换器 */}
      <div className="_memory-global-header-left">
        <div className="_memory-global-header-brand">
          <img src="/logo.png" alt="Memory Hub" className="_memory-global-header-logo" />
          <span className="_memory-global-header-brand-text">{t('header.brand')}</span>
        </div>
        <TeamSwitcher userRole={userRole} />
      </div>

      {/* 右侧：同步状态 + 语言切换 + 用户菜单 */}
      <div className="_memory-global-header-right">
        {/* <span className="_memory-global-header-sync" title={t('header.sync.title')}>
        <span className="_memory-global-header-sync-dot" />
        {t('header.sync')}
      </span> */}

        {/* 使用说明：进入独立引导页；当前在该页时展示激活态 */}
        <button
          type="button"
          className={`_memory-global-header-guide-btn${location.pathname === '/guide' ? ' is-active' : ''}`}
          onClick={() => navigate('/guide')}
        >
          {t('header.guide')}
        </button>

        <LanguageSwitcher />

        <button
          type="button"
          className="_memory-global-header-icon-btn"
          title={t('header.settings')}
          onClick={() => setSettingsOpen(true)}
        >
          <SettingIcon size={16} />
        </button>

        <Dropdown
          appearance="pure"
          button={
            <button type="button" className="_memory-global-header-user-btn">
              <span className="_memory-global-header-avatar">
                {currentUser.slice(0, 1).toUpperCase()}
              </span>
              <span className="_memory-global-header-username">{currentUser}</span>
            </button>
          }
        >
          {(close) => (
            <List type="option">
              <List.Item
                onClick={() => {
                  close();
                  setProfileOpen(true);
                }}
              >
                {t('header.profile')}
              </List.Item>
              {onReplayOnboarding && (
                <List.Item
                  onClick={() => {
                    close();
                    onReplayOnboarding();
                  }}
                >
                  {t('header.replayGuide')}
                </List.Item>
              )}
              <List.Item
                onClick={() => {
                  close();
                  onLogout();
                }}
              >
                {t('header.logout')}
              </List.Item>
            </List>
          )}
        </Dropdown>
      </div>

      {profileOpen && currentUserId && (
        <ProfileModal
          currentUser={currentUser}
          currentUserId={currentUserId}
          userRole={userRole}
          instanceName={instanceName}
          onClose={() => setProfileOpen(false)}
          onReplayOnboarding={onReplayOnboarding}
        />
      )}

      {settingsOpen && <SettingsDialog onClose={() => setSettingsOpen(false)} />}
    </header>
  );
}

// =================== Profile Modal ===================

/** TeamRole → 展示文案 + Tag 主题色 */
function roleDisplay(role: TeamRole | null): { label: string; theme: 'primary' | 'default' | 'warning' } {
  if (role === 'admin') return { label: 'admin', theme: 'primary' };
  if (role === 'reviewer') return { label: 'reviewer', theme: 'warning' };
  return { label: 'member', theme: 'default' };
}

/**
 * 「我的资料」弹窗：tea Avatar + Justify + Text/Tag 描述型展示。
 *
 * 关键设计：
 *   - 头部 Avatar + 用户名 + 角色 Tag 一行展示（Justify 左右对齐）
 *   - User ID 用 InputAdornment + Copy 一行可复制，避免单独开块
 *   - 所属实例（如有）用 Card.Body 单独分组，与 User ID 区分语义
 *   - Footer 用 Justify 让「回顾引导」左对齐、「关闭」右对齐
 */
function ProfileModal({
  currentUser,
  currentUserId,
  userRole,
  instanceName,
  onClose,
  onReplayOnboarding,
}: {
  currentUser: string;
  currentUserId: string;
  userRole: TeamRole | null;
  instanceName?: string;
  onClose: () => void;
  onReplayOnboarding?: () => void;
}) {
  const { t } = useTranslation();
  const initial = currentUser.slice(0, 1).toUpperCase();
  const role = roleDisplay(userRole);

  return (
    <Modal visible size="s" onClose={onClose} caption={t('header.profile.caption')}>
      <Modal.Body>
        {/* 头部：Avatar + 用户名 + 角色 Tag */}
        <Justify
          left={
            <div className="_memory-profile-identity">
              <Avatar
                color={currentUserId}
                text={initial}
                width={48}
                height={48}
              />
              <div className="_memory-profile-identity-meta">
                <Text theme="strong" parent="div" className="_memory-profile-identity-name">
                  {currentUser}
                </Text>
                <Text theme="weak" parent="div" className="_memory-profile-identity-id">
                  {currentUserId}
                </Text>
              </div>
            </div>
          }
          right={<Tag theme={role.theme} variant="soft">{t(`header.profile.role.${role.label}`)}</Tag>}
        />

        <div className="_memory-profile-divider" />

        {/* User ID：单独成块 + Copy，admin 给成员邀请用 */}
        <div className="_memory-profile-section">
          <Text theme="label" parent="div" className="_memory-profile-section-label">
            {t('header.profile.userId')}
          </Text>
          <InputAdornment after={<Copy text={currentUserId} />} className="_memory-profile-input-adornment">
            <Input value={currentUserId} readonly size="full" />
          </InputAdornment>
          <Text theme="weak" parent="div" className="_memory-profile-section-hint">
            {t('header.profile.userIdHint')}
          </Text>
        </div>

        {/* Username：明文提示，方便用户核对自己注册名 */}
        <div className="_memory-profile-section">
          <Text theme="label" parent="div" className="_memory-profile-section-label">
            {t('header.profile.username')}
          </Text>
          <Input value={currentUser} readonly size="full" />
          <Text theme="weak" parent="div" className="_memory-profile-section-hint">
            {t('header.profile.usernameHint')}
          </Text>
        </div>

        {/* 所属实例（可选）—— 多实例用户知道现在连的是哪个 */}
        {instanceName && (
          <div className="_memory-profile-section">
            <Text theme="label" parent="div" className="_memory-profile-section-label">
              {t('header.profile.instance')}
            </Text>
            <InputAdornment
              after={<Tag size="sm" variant="outlined">{currentUserId.split('-')[0]}</Tag>}
              className="_memory-profile-input-adornment"
            >
              <Input value={instanceName} readonly size="full" />
            </InputAdornment>
          </div>
        )}
      </Modal.Body>
      <Modal.Footer>
        {/* Justify：左回顾引导 / 右关闭；onReplayOnboarding 未传时只显示关闭 */}
        <Justify
          left={
            onReplayOnboarding ? (
              <Button
                type="link"
                onClick={() => {
                  onClose();
                  onReplayOnboarding();
                }}
              >
                {t('header.replayGuide')}
              </Button>
            ) : null
          }
          right={<Button onClick={onClose}>{t('header.profile.close')}</Button>}
        />
      </Modal.Footer>
    </Modal>
  );
}

/**
 * OnboardingGuide — 首次使用引导（Tea Guide 组件版）
 *
 * 使用 tea-component `Guide` 组件逐步高亮页面元素，替代旧的全屏双栏引导。
 *
 * 双角色 SOP（步骤切换时自动跳转到对应页面，不只是展示）：
 *   - Admin：登录身份 → 新建/切换团队 → 新建成员发放 user_key → Agent → 点击 Agent 绑定资产 → 四个资产页
 *   - Member：登录身份 → 邀请成员 → Agent → 点击 Agent 绑定资产 → User_Key 管理 → 四个资产页
 *
 * Admin 与 Member 的 Agent / 资产操作能力一致（均可编辑）；唯一差异在成员管理：
 * member 不能创建用户账号，只能按 user_id 邀请已有用户；admin 可新建用户并发放
 * user_key，也可新建团队。资产步骤逐一跳入 Wiki / Code / Skill / Chat Memory 页面介绍。
 *
 * 健壮性：每步 element 选择器若在目标页缺失（如成员无「添加成员」权限），
 * 自动 fallback 到全局 Header 品牌区，避免 Guide 因元素缺失而整体消失。
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { Guide, type GuideStep } from 'tea-component';

const STORAGE_PREFIX = 'tdai-panel.onboarded';

/** 全局始终存在的锚点元素（Header 品牌区），用于目标元素缺失时的 fallback */
const FALLBACK_SELECTOR = '._memory-global-header-brand';

/** 每用户维度的「已看过引导」localStorage key */
function onboardedKey(userId?: string): string {
  return `${STORAGE_PREFIX}.${userId || 'anonymous'}`;
}

/** 是否应当自动弹出引导（未标记过 = 首次） */
export function shouldShowOnboarding(userId?: string): boolean {
  try {
    return window.localStorage.getItem(onboardedKey(userId)) !== '1';
  } catch {
    // localStorage 不可用时不打扰用户
    return false;
  }
}

/**
 * 重置「已看过引导」标记。
 *
 * 用户在「我的资料 → 回顾引导」手动触发：清掉 onboarded 标记，下次进主面板
 * useEffect 检测 shouldShowOnboarding() === true 会再次自动弹出。
 *
 * 注意：调用方还需把 OnboardingGuide 的 visible 设回 true，因为之前的 close()
 * 已经把内部 current 推进到 -1 并调了 onClose，仅清标记不足以重新打开。
 */
export function resetOnboarding(userId?: string): void {
  try {
    window.localStorage.removeItem(onboardedKey(userId));
  } catch {
    /* localStorage 不可用时静默忽略 */
  }
}

function markOnboarded(userId?: string): void {
  try {
    window.localStorage.setItem(onboardedKey(userId), '1');
  } catch {
    /* localStorage 不可用时静默忽略 */
  }
}

interface OnboardingStep {
  /** 目标路由：切换步骤时自动跳转（省略表示停留在当前页面） */
  path?: string;
  /**
   * 要高亮的元素选择器。支持数组按序回退（例如 admin 优先高亮"添加成员"按钮，
   * 按钮不存在时回退到成员列表区），全部缺失时最终回退到 Header 品牌区。
   */
  selector: string | string[];
  placement?: GuideStep['placement'];
  titleKey: string;
  descKey: string;
}

/** 按顺序返回第一个匹配的元素，找不到返回 null */
function firstMatch(selectors: string[]): Element | null {
  for (const sel of selectors) {
    const el = document.querySelector(sel);
    if (el) return el;
  }
  return null;
}

/** 解析步骤高亮元素；目标元素缺失时按序回退，最终回退到全局 Header 品牌区，保证 Guide 始终可渲染 */
function resolveElement(selector: string | string[]): Element {
  const list = Array.isArray(selector) ? selector : [selector];
  return firstMatch(list) || document.querySelector(FALLBACK_SELECTOR) || document.body;
}

/**
 * 按元素在视口中的实际位置动态计算气泡展开方向：
 *   - 水平：元素中心在左半屏 → 向右展开（*-start）；右半屏 → 向左展开（*-end）
 *   - 垂直：元素中心在上半屏 → 向下展开（bottom-*）；下半屏 → 向上展开（top-*）
 * 这样气泡永远朝视口中央方向展开，任何页面/任何位置的元素都不会被挤出屏幕。
 */
function computePlacement(
  selector: string | string[],
  fallback: GuideStep['placement'],
): GuideStep['placement'] {
  const list = Array.isArray(selector) ? selector : [selector];
  const el = firstMatch(list);
  // 元素缺失（页面未跳转/未渲染）时无法用位置推断方向，直接使用步骤预设的安全方向。
  // 绝不能 fallback 到 body 计算：body rect 高度远超视口，cy 必大于 innerHeight/2，
  // 会算出 top-* 把气泡定位到屏幕外（"框超出屏幕点不到"的根因）。
  if (!el) return fallback;
  const rect = el.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  const horizontal = cx < window.innerWidth / 2 ? 'start' : 'end';
  const vertical = cy < window.innerHeight / 2 ? 'bottom' : 'top';
  const placement = `${vertical}-${horizontal}`;
  if (
    placement === 'bottom-start' ||
    placement === 'bottom-end' ||
    placement === 'top-start' ||
    placement === 'top-end'
  ) {
    return placement;
  }
  return fallback;
}

/**
 * 点击 Agent 进入编辑弹窗绑定资产的引导步骤（Admin / Member 共有，
 * 紧跟「新建 Agent」步骤，同页切换无跳转）。
 * 锚点三级回退：
 *   1. 卡片视图：框选第一个可编辑 Agent 的整张卡片；
 *   2. 列表视图（无卡片）：回退到可编辑 Agent 的名称按钮；
 *   3. 用户还没有任何 Agent：回退到「新建 Agent」按钮，
 *      文案同步提示「先新建一个 Agent 再回来点它」。
 */
const AGENT_BIND_STEP: OnboardingStep = {
  path: '/team/agents',
  selector: [
    '[data-guide="agent-card-editable"]',
    '[data-guide="agent-name-editable"]',
    '[data-guide="create-agent"]',
  ],
  placement: 'bottom-start',
  titleKey: 'onboarding.guide.agentBind.title',
  descKey: 'onboarding.guide.agentBind.desc',
};

/** 每个资产页各自跳入介绍的引导步骤（Wiki / Code / Skill / Chat Memory） */
const ASSET_STEPS: OnboardingStep[] = [
  {
    path: '/wiki',
    // 优先框「新建 Wiki」按钮；按钮缺失（固定资产 tab / 无 team）时回退到顶部 Wiki tab，
    // 而不是回退到 logo，避免框错区域。
    selector: ['[data-guide="create-wiki"]', '[data-guide="tab-wiki"]'],
    // ActionPanel 左侧"新建 Wiki"按钮：向右展开
    placement: 'bottom-start',
    titleKey: 'onboarding.guide.asset.wiki.title',
    descKey: 'onboarding.guide.asset.wiki.desc',
  },
  {
    path: '/code',
    // 优先框「注册仓库」按钮；按钮缺失时回退到顶部 Code tab。
    selector: ['[data-guide="create-code"]', '[data-guide="tab-code"]'],
    // ActionPanel 左侧"注册仓库"按钮：向右展开
    placement: 'bottom-start',
    titleKey: 'onboarding.guide.asset.code.title',
    descKey: 'onboarding.guide.asset.code.desc',
  },
  {
    path: '/skills',
    selector: '[data-guide="import-skill"]',
    // 页头右侧 actions 中的"导入 Skill"按钮（与 Memory 一致）：向左展开
    placement: 'bottom-end',
    titleKey: 'onboarding.guide.asset.skill.title',
    descKey: 'onboarding.guide.asset.skill.desc',
  },
  {
    path: '/memory',
    selector: '[data-guide="import-memory"]',
    // 右侧"导入记忆"按钮：向左展开
    placement: 'bottom-end',
    titleKey: 'onboarding.guide.asset.memory.title',
    descKey: 'onboarding.guide.asset.memory.desc',
  },
];

function buildSteps(role: 'admin' | 'member'): OnboardingStep[] {
  const loginStep: OnboardingStep = {
    selector: '._memory-global-header-user-btn',
    // header 右上角用户按钮：用 bottom-end 让气泡右边缘对齐元素右边缘，向左展开，
    // 避免在窄视口下气泡被裁掉"下一步"按钮
    placement: 'bottom-end',
    titleKey: 'onboarding.guide.login.title',
    descKey: 'onboarding.guide.login.desc',
  };

  // Admin 与 Member 的 Agent / 资产操作能力一致（都可编辑），仅成员管理不同：
  //   - admin：可新建团队、新建用户并发放 user_key（member 无此权限）
  //   - member：只能按 user_id 邀请已有用户加入团队；但可管理自己的 User_Key（admin 无此入口）
  // placement 选择：右侧元素用 bottom-end（向左展开），左侧元素用 bottom-start（向右展开）
  if (role === 'admin') {
    return [
      loginStep,
      {
        selector: '._memory-team-switcher-trigger',
        // header 左上角：向左展开避免右移溢出
        placement: 'bottom-start',
        titleKey: 'onboarding.guide.team.title',
        descKey: 'onboarding.guide.team.desc',
      },
      {
        path: '/team/members',
        // 优先高亮"添加成员"按钮；无 team 时按钮不存在，回退到成员列表区
        selector: ['[data-guide="add-member"]', '[data-guide="members-list"]'],
        placement: 'bottom-end',
        titleKey: 'onboarding.guide.memberAdmin.title',
        descKey: 'onboarding.guide.memberAdmin.desc',
      },
      {
        path: '/team/agents',
        selector: '[data-guide="create-agent"]',
        // ActionPanel 左侧"新建 Agent"按钮：向右展开
        placement: 'bottom-start',
        titleKey: 'onboarding.guide.agent.title',
        descKey: 'onboarding.guide.agent.desc',
      },
      AGENT_BIND_STEP,
      ...ASSET_STEPS,
    ];
  }

  return [
    loginStep,
    {
      path: '/team/members',
      // 普通 member 没有"添加成员"按钮（仅 admin/teamAdmin 可见），
      // 所以高亮始终存在的成员列表区，避免 fallback 到 header 导致"没跳转/定位错"
      selector: '[data-guide="members-list"]',
      placement: 'bottom-start',
      titleKey: 'onboarding.guide.member.title',
      descKey: 'onboarding.guide.member.desc',
    },
    {
      path: '/team/agents',
      selector: '[data-guide="create-agent"]',
      // ActionPanel 左侧"新建 Agent"按钮：向右展开
      placement: 'bottom-start',
      titleKey: 'onboarding.guide.agent.title',
      descKey: 'onboarding.guide.agent.desc',
    },
    AGENT_BIND_STEP,
    {
      path: '/team/api-keys',
      selector: '[data-guide="create-key"]',
      // Justify 右侧"新建 Key"按钮：向左展开
      placement: 'bottom-end',
      titleKey: 'onboarding.guide.apikey.title',
      descKey: 'onboarding.guide.apikey.desc',
    },
    ...ASSET_STEPS,
  ];
}

export function OnboardingGuide({
  visible,
  userId,
  userRole,
  onClose,
}: {
  visible: boolean;
  userId?: string;
  userRole: 'admin' | 'member' | 'reviewer' | null;
  /** 关闭引导（无论「跳过」还是「完成」都会标记为已看过） */
  onClose: () => void;
}) {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const location = useLocation();

  const isAdmin = userRole === 'admin';
  const steps = useMemo(() => buildSteps(isAdmin ? 'admin' : 'member'), [isAdmin]);

  const [current, setCurrent] = useState(-1);
  const pendingRef = useRef<number | null>(null);

  /**
   * 动画对齐策略（替代旧的"隐藏→显示"门控，消除无遮罩空窗）：
   *   - 同页切换：气泡（popper transform）与高亮框（top/left/width/height）带
   *     CSS transition，随 scrollIntoView smooth 滚动平滑滑到新位置，全程可见；
   *   - 跨页切换：旧锚点会随页面卸载（popper 对 detached 元素会定位到 0,0），
   *     先 fadeOut 淡出 → 跳转 → 新锚点就绪后 no-anim 瞬间落位 → fadeIn 淡入。
   */
  const fadeOut = useCallback(() => {
    document.body.classList.add('_guide-fading');
  }, []);

  /** 新步骤首帧定位完成后淡入（双 rAF：等 React commit + popper 定位） */
  const fadeIn = useCallback(() => {
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        document.body.classList.remove('_guide-fading');
        document.body.classList.remove('_guide-no-anim');
      });
    });
  }, []);

  // 卸载时清理全局 class
  useEffect(() => {
    return () => {
      document.body.classList.remove('_guide-fading');
      document.body.classList.remove('_guide-no-anim');
    };
  }, []);

  const close = useCallback(() => {
    markOnboarded(userId);
    pendingRef.current = null;
    document.body.classList.remove('_guide-fading');
    document.body.classList.remove('_guide-no-anim');
    setCurrent(-1);
    onClose();
  }, [userId, onClose]);

  // 步骤切换：finish/cancel 直接关闭；next/back/start 先跳转目标页面，
  // 等目标路径匹配且元素出现后再推进 current（避免 Guide 因元素缺失闪退）。
  const handleCurrentChange = useCallback(
    (next: number, context: { from: 'start' | 'back' | 'next' | 'finish' | 'cancel' }) => {
      const { from } = context;
      if (from === 'finish' || from === 'cancel') {
        close();
        return;
      }
      if (next < 0 || next >= steps.length) return;
      const target = steps[next];
      if (!target) return;
      if (target.path && target.path !== location.pathname) {
        // 跨页跳转：先淡出（遮住"锚点卸载→新页加载"窗口），pending 完成后淡入
        fadeOut();
        pendingRef.current = next;
        navigate(target.path);
      } else {
        // 同页切换：直接推进，位置 transition 与滚动动画对齐，平滑滑过去
        setCurrent(next);
      }
    },
    [steps, location.pathname, navigate, close, fadeOut],
  );

  // 等待跳转完成：路径匹配后轮询目标元素出现，再推进 current（最多等 60 帧约 1s）
  useEffect(() => {
    const pending = pendingRef.current;
    if (pending === null) return;
    const target = steps[pending];
    if (!target || !target.path) return;
    if (location.pathname !== target.path) return;

    let cancelled = false;
    let tries = 0;
    const tick = () => {
      if (cancelled) return;
      // selector 可能是回退数组：任一元素出现即视为目标页面已就绪
      const list = Array.isArray(target.selector) ? target.selector : [target.selector];
      if (firstMatch(list) || tries >= 60) {
        pendingRef.current = null;
        // 新锚点瞬间落位（no-anim 禁用过渡，避免从旧位置滑入），然后淡入
        document.body.classList.add('_guide-no-anim');
        setCurrent(pending);
        fadeIn();
        return;
      }
      tries += 1;
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
    return () => {
      cancelled = true;
    };
  }, [location.pathname, steps, fadeIn]);

  // 初次显示：popper 首帧定位前禁用过渡（避免气泡从 (0,0) 滑入），定位完成后启用
  useEffect(() => {
    if (!visible) return;
    document.body.classList.add('_guide-no-anim');
    const timer = window.setTimeout(() => {
      document.body.classList.remove('_guide-no-anim');
    }, 50);
    return () => {
      window.clearTimeout(timer);
      document.body.classList.remove('_guide-no-anim');
    };
  }, [visible]);
  const guideSteps: GuideStep[] = useMemo(
    () =>
      steps.map((s) => ({
        element: () => resolveElement(s.selector),
        placement: computePlacement(s.selector, s.placement),
        title: t(s.titleKey),
        description: t(s.descKey),
      })),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [steps, t, current, visible],
  );

  const startContent: GuideStep = useMemo(
    () => ({
      element: () => resolveElement(FALLBACK_SELECTOR),
      // 欢迎页高亮 header 品牌区：按实际位置动态计算方向
      placement: computePlacement(FALLBACK_SELECTOR, 'bottom-start'),
      title: t(
        isAdmin ? 'onboarding.guide.start.admin.title' : 'onboarding.guide.start.member.title',
      ),
      description: t(
        isAdmin ? 'onboarding.guide.start.admin.desc' : 'onboarding.guide.start.member.desc',
      ),
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [isAdmin, t, visible],
  );

  // ===== 自定义精确高亮层 =====
  // tea Guide 内置 mask 基于 react-popper 定位：在内部滚动容器（tea-layout__content）
  // 下存在固定偏差（约 3~5px），且不随滚动更新（滚动后偏差进一步放大），导致高亮框
  // "漏边"。这里改用 getBoundingClientRect 实时计算（capture 监听内部容器滚动 +
  // resize），并用全局 CSS 隐藏 Guide 自带 mask（见 index.css `.tea-overlay[style*="z-index: 9999"]`）。
  const anchorSelector =
    current >= 0 && steps[current] ? steps[current].selector : FALLBACK_SELECTOR;
  const [anchorBox, setAnchorBox] = useState<{
    top: number;
    left: number;
    width: number;
    height: number;
  } | null>(null);

  useEffect(() => {
    if (!visible) {
      setAnchorBox(null);
      return;
    }
    const update = () => {
      const el = resolveElement(anchorSelector);
      if (!el || el === document.body) return;
      const r = el.getBoundingClientRect();
      setAnchorBox({ top: r.top, left: r.left, width: r.width, height: r.height });
    };
    update();
    // 步骤切换瞬间 Guide 的 scrollIntoView(smooth) 动画可能尚未结束，
    // 立即测到的是动画中间位置；用 rAF + 延迟兜底在布局稳定后修正。
    const raf = requestAnimationFrame(update);
    const late = window.setTimeout(update, 400);
    // capture 阶段监听，能捕获内部滚动容器（非 window）的滚动事件
    const onScrollOrResize = () => requestAnimationFrame(update);
    window.addEventListener('scroll', onScrollOrResize, true);
    window.addEventListener('resize', onScrollOrResize);
    // 数据加载等导致的布局变化也会移动锚点（ResizeObserver 比 resize 事件覆盖更全）
    const ro = new ResizeObserver(() => requestAnimationFrame(update));
    ro.observe(document.body);
    return () => {
      cancelAnimationFrame(raf);
      clearTimeout(late);
      window.removeEventListener('scroll', onScrollOrResize, true);
      window.removeEventListener('resize', onScrollOrResize);
      ro.disconnect();
    };
  }, [visible, anchorSelector]);

  return (
    <>
      <Guide
        visible={visible}
        steps={guideSteps}
        startContent={startContent}
        current={current}
        onCurrentChange={handleCurrentChange}
        showBackButton
        showDot
        nextButtonTheme="primary"
        cancelText={t('onboarding.skip')}
        backText={t('onboarding.prev')}
        nextText={t('onboarding.next')}
        finishText={t('onboarding.finish')}
        startFinishText={t('onboarding.start')}
        autoScrollIntoView
      />
      {anchorBox && (
        <div className="_guide-mask" aria-hidden="true">
          {/* 上下左右四块半透明遮罩拼出高亮洞 */}
          <div
            className="_guide-mask-block"
            style={{ top: 0, left: 0, right: 0, height: anchorBox.top }}
          />
          <div
            className="_guide-mask-block"
            style={{ top: anchorBox.top + anchorBox.height, left: 0, right: 0, bottom: 0 }}
          />
          <div
            className="_guide-mask-block"
            style={{ top: anchorBox.top, left: 0, width: anchorBox.left, height: anchorBox.height }}
          />
          <div
            className="_guide-mask-block"
            style={{
              top: anchorBox.top,
              left: anchorBox.left + anchorBox.width,
              right: 0,
              height: anchorBox.height,
            }}
          />
          {/* 高亮描边 */}
          <div
            className="_guide-mask-ring"
            style={{
              top: anchorBox.top,
              left: anchorBox.left,
              width: anchorBox.width,
              height: anchorBox.height,
            }}
          />
        </div>
      )}
    </>
  );
}

/**
 * TabBar — 多标签页栏。
 *
 * 使用 Tea Design Token 统一样式。
 */
import { ITEM_ICON, usePageMeta, type PageId } from '@/constants/menu';
import './style.css';

export function TabBar({
  pages,
  activePage,
  onNavigate,
  onClose,
}: {
  pages: PageId[];
  activePage: PageId;
  onNavigate: (id: PageId) => void;
  onClose: (id: PageId) => void;
}) {
  const PAGE_META = usePageMeta();
  return (
    <div className="_memory-tabbar">
      {pages.map((id) => {
        const meta = PAGE_META[id];
        const isActive = id === activePage;
        return (
          <div
            key={id}
            role="tab"
            tabIndex={0}
            aria-selected={isActive}
            data-guide={`tab-${id}`}
            onClick={() => onNavigate(id)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onNavigate(id);
              }
            }}
            className={`_memory-tabbar-item${isActive ? ' _memory-tabbar-item--active' : ''}`}
          >
            <span className="_memory-tabbar-icon" aria-hidden="true">{ITEM_ICON[id]}</span>
            <span className="_memory-tabbar-label">{meta.label}</span>
            {!meta.affix && (
              <button
                type="button"
                aria-label={`${meta.label} close`}
                onClick={(e) => {
                  e.stopPropagation();
                  onClose(id);
                }}
                className="_memory-tabbar-close"
              >
                <svg viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="1.5" width="10" height="10" aria-hidden="true">
                  <path d="M3 3l6 6M9 3l-6 6" />
                </svg>
              </button>
            )}
          </div>
        );
      })}
    </div>
  );
}

/**
 * api/agents.ts — Agent 管理（meta/agent/* + meta/agent-fixed-asset/*）。
 */
import { getPanelSession } from '../panelSession';
import { metaPost, metaListAll, getCurrentUser, request, ApiError } from './base';
import type { MetaEnvelope, Agent, AssetType, AssetStatus, FixedAssetBinding } from './types';

// ========================= 默认 Agent 模板 =========================

export interface AgentTemplateAssetIds {
  /** 团队 skill ID（skl-xxx） */
  skills?: string[];
  /** 团队 code graph ID（code-xxx） */
  code_graphs?: string[];
  /** 团队 wiki ID（wiki-xxx） */
  wikis?: string[];
}

/**
 * 默认 Agent 模板配置（agent/get-default-template / set-default-template 的 template 结构）。
 * 注意：
 *   - asset_ids 为团队资产 ID 快照，只允许选 visibility=team 的公共资产；
 *   - 覆盖式写入：set 时需一次回传完整 template；
 *   - metadata_json 为 JSON 字符串，ui.role_prompt / ui.rules_prompt 存拆分 prompt。
 */
export interface AgentTemplateConfig {
  name: string;
  description?: string | null;
  prompt?: string | null;
  /** 'private' | 'team'(默认) | 'restricted' */
  visibility?: string;
  metadata_json?: string;
  asset_ids?: AgentTemplateAssetIds;
}

export const agentsApi = {
  /**
   * 列出 team 下的 agents。
   *
   * @param teamId team ID
   * @param params.owner_user_id 可选：只返该 user owner 的 agent（"agent 私有可见性"场景，
   *   如 Skill 面板固定资产 tab）；不传则返 team 全量。`agent/list` 支持
   *   `team_id + owner_user_id` 组合过滤。
   */
  list: (teamId: string, params?: { owner_user_id?: string }) =>
    metaListAll<Agent>('agent/list', {
      team_id: teamId,
      status: 'active',
      owner_user_id: params?.owner_user_id,
    }),

  /** agent 详情 */
  get: (agentId: string) => metaPost<Agent>('agent/get', { agent_id: agentId }),

  /** 创建 agent */
  create: async (
    teamId: string,
    data: { name: string; description?: string; prompt?: string; visibility?: string }
  ) => {
    const me = await getCurrentUser();
    return metaPost<Agent>('agent/create', {
      team_id: teamId,
      owner_user_id: me.user_id,
      name: data.name,
      description: data.description,
      prompt: data.prompt,
      visibility: data.visibility ?? 'team',
    });
  },

  /**
   * 更新 agent。
   *
   * `metadata_json` 是给前端自定义关系的兜底通道：后端 schema 未落地的展示字段
   * （如 icon / accent / 关联 user 等 UI-only 字段）可以序列化进这里的自定义 namespace。
   */
  update: (
    agentId: string,
    data: {
      name?: string;
      description?: string;
      prompt?: string;
      visibility?: string;
      status?: string;
      metadata_json?: string;
    }
  ) => metaPost<Agent>('agent/update', { agent_id: agentId, ...data }),

  /**
   * 删除 agent：走业务路由 /api/v1/agent/delete-cascade。
   *
   * 该路由会先把 owner_agent_id = 当前 agent 的所有 active skill 走 skill/delete，
   * 全部成功后才调 meta/agent/archive；任一 skill 删失败即中断，agent 不会被 archive，
   * 抛出 SKILL_DELETE_FAILED 让调用方给用户展示（错误 data 里带上已删的 skill_ids
   * 和失败的 skill_id）。归档时后端会顺手清 chat_memory asset。
   */
  delete: async (agentId: string) => {
    const session = getPanelSession();
    if (!session) {
      throw new ApiError(401, 'Unauthorized', 'no active panel session');
    }
    const envelope = await request<MetaEnvelope<{
      archived: boolean;
      agent_id: string;
      deleted_skill_count: number;
      deleted_skill_ids: string[];
    }>>('POST', '/api/v1/agent/delete-cascade', { agent_id: agentId }, {
      'X-Tdai-Service-Id': session.instanceId,
      'X-Tdai-User-Key': session.userKey,
    });
    if (envelope.code !== 0) {
      throw new ApiError(200, envelope.message, '', {
        code: envelope.code,
        requestId: envelope.request_id,
        rawMessage: envelope.message,
      });
    }
  },

  /** 获取 agent 的资产聚合视图（binding + asset 详情）。
   *  用 metaListAll 翻页拉全量（list-with-detail 默认 limit 20，绑定资产一多会被截断）。
   *
   *  applyVisibilityFilter：默认 true（屏蔽已私密的绑定，用于普通展示）。
   *  owner 视角管理自己的资产时应传 false —— 否则自己 owner 的 private skill
   *  会被接口过滤掉，导致 fixed tab 拿不到它的 visibility、共享/私密切换按钮消失。 */
  getAssets: async (agentId: string, applyVisibilityFilter = true) => {
    const items = await metaListAll<{
      asset_id: string;
      asset_type: AssetType;
      name: string;
      description?: string;
      status: AssetStatus;
      visibility: string;
      injection_mode: FixedAssetBinding['injection_mode'];
      priority: number;
      created_at: string;
    }>('agent-fixed-asset/list-with-detail', {
      agent_id: agentId,
      apply_visibility_filter: applyVisibilityFilter,
      touch_usage: false,
    });
    return items.map((item) => ({
      asset_id: item.asset_id,
      asset_type: item.asset_type,
      name: item.name,
      description: item.description,
      status: item.status,
      visibility: item.visibility,
      injection_mode: item.injection_mode ?? 'direct',
      priority: item.priority,
      created_at: item.created_at,
    }));
  },

  /** 获取 agent 固定资产 binding（仅 binding 字段） */
  getFixedAssets: async (agentId: string) => {
    const rows = await metaListAll<{
      asset_id: string;
      asset_type: AssetType;
      injection_mode?: FixedAssetBinding['injection_mode'];
      priority: number;
    }>('agent-fixed-asset/list', { agent_id: agentId });
    return rows.map((r) => ({
