 * 通过 i18n 实例动态翻译，跟随用户当前语言切换。
 */
function lookupErrorCode(code: string): string | null {
  if (KNOWN_ERROR_CODES.has(code)) return i18n.t('error.' + code);
  // snake_case 归一：后端可能返回小写
  if (/^[a-z][a-z0-9_]+$/.test(code)) {
    const upper = code.toUpperCase();
    if (KNOWN_ERROR_CODES.has(upper)) return i18n.t('error.' + upper);
  }
  return null;
}

function getMessagePatterns(): Array<[RegExp, string]> {
  return [
    [/unauthorized:\s*invalid_user_key/i, i18n.t('error.INVALID_USER_KEY')],
    [/user_id or user_key is required/i, i18n.t('error.MISSING_USER_KEY')],
    [/missing.*team_id/i, i18n.t('error.MISSING_TEAM_ID')],
    [/missing.*agent_id/i, i18n.t('error.MISSING_AGENT_ID')],
    [/not team member/i, i18n.t('error.NOT_TEAM_MEMBER')],
    // 注：asset_not_bindable / visibility_restricted 在 PRIORITY_MESSAGE_PATTERNS 里前置匹配，
    // 因为它们会被 permission_denied 前缀吞掉。
    [/permission[_\s-]?denied/i, i18n.t('error.PERMISSION_DENIED')],
    [/fetch failed|networkerror|failed to fetch/i, i18n.t('error.network')],
    [/timeout|aborted/i, i18n.t('error.timeout')],
    [/empty .* response/i, i18n.t('error.emptyResponse')],
    [/internal server error/i, i18n.t('error.INTERNAL_ERROR')],
  ];
}

/**
 * 优先匹配的语义 pattern —— 在 extractCodeLike 兜底提取之前先跑。
 *
 * 场景：内核抛的错误消息形如 `permission_denied: visibility_restricted` —— 前缀 `permission_denied`
 * 会被 extractCodeLike 提取成 `PERMISSION_DENIED` 直接命中通用文案，掩盖后面的 `visibility_restricted`
 * 语义关键词。因此凡是"通用错误码 + 细化子原因"的组合都必须在这里精准命中。
 */
function getPriorityPatterns(): Array<[RegExp, string]> {
  return [
    [/visibility[_\s-]?restricted/i, i18n.t('error.ASSET_PRIVATE_INACCESSIBLE')],
    [/asset_not_bindable/i, i18n.t('error.ASSET_NOT_BINDABLE')],
  ];
}

function tryParseJson(input: string): unknown | null {
  const text = input.trim();
  if (!text || (!text.startsWith('{') && !text.startsWith('['))) return null;
  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

function extractCodeLike(message: string): string | null {
  const trimmed = message.trim();
  if (!trimmed) return null;
  const exact = trimmed.match(/^[A-Z][A-Z0-9_]{2,}$/);
  if (exact) return exact[0];
  const lowerPrefix = trimmed.match(/^([a-z][a-z0-9_]{2,})\s*:/);
  if (lowerPrefix) return lowerPrefix[1].toUpperCase();
  const upperInside = trimmed.match(/\b([A-Z][A-Z0-9_]{2,})\b/);
  return upperInside?.[1] ?? null;
}

function stripTechnicalPrefix(message: string): string {
  return message
    .replace(/^(skill|knowledge)\s+\d+\s*:\s*/i, '')
    .replace(/^\d{3}\s+[A-Za-z ]+\s*·\s*/, '')
    .trim();
}

function isJsonLike(message: string): boolean {
  const trimmed = message.trim();
  return trimmed.startsWith('{') || trimmed.startsWith('[');
}

export function mapErrorCode(codeOrMessage: number | string | undefined, fallbackMessage?: string): string | null {
  const raw = String(codeOrMessage ?? '').trim();
  const text = fallbackMessage ?? raw;

  // 先跑优先 pattern：避免 extractCodeLike 用 `permission_denied` 前缀吃掉子原因关键词。
  for (const [pattern, message] of getPriorityPatterns()) {
    if (pattern.test(text) || pattern.test(raw)) return message;
  }

  const direct = lookupErrorCode(raw);
  if (direct) return direct;

  const fromMessage = extractCodeLike(fallbackMessage ?? raw);
  if (fromMessage) {
    const mapped = lookupErrorCode(fromMessage);
    if (mapped) return mapped;
  }

  for (const [pattern, message] of getMessagePatterns()) {
    if (pattern.test(text)) return message;
  }
  return null;
}

export function formatApiErrorMessage(input: {
  code?: number | string;
  message?: string;
  requestId?: string;
  httpStatus?: number;
  httpStatusText?: string;
  body?: string;
  fallback?: string;
}): string {
  const bodyJson = input.body ? tryParseJson(input.body) : null;
  const env = bodyJson && !Array.isArray(bodyJson) ? bodyJson as ErrorEnvelopeLike : null;
  const code = input.code ?? env?.code ?? input.httpStatus;
  const rawMessage = env?.message ?? input.message ?? input.httpStatusText ?? input.body ?? input.fallback ?? '';

  const mapped = mapErrorCode(code, rawMessage) ?? mapErrorCode(rawMessage);
  if (mapped) return mapped;

  const clean = stripTechnicalPrefix(rawMessage);
  if (clean && !isJsonLike(clean)) return clean;

  if (input.httpStatus === 401) return i18n.t('error.UNAUTHORIZED');
  if (input.httpStatus === 403) return i18n.t('error.PERMISSION_DENIED');
  if (input.httpStatus === 404) return i18n.t('error.NOT_FOUND');
  if (input.httpStatus && input.httpStatus >= 500) return i18n.t('error.INTERNAL_ERROR');
  return input.fallback ?? i18n.t('error.fallback');
}

export function getErrorMessage(err: unknown): string {
  if (err instanceof Error && err.name === 'ApiError') {
    const apiErr = err as Error & {
      status: number;
      statusText: string;
      body: string;
      code?: number | string;
      requestId?: string;
      rawMessage?: string;
    };
    return formatApiErrorMessage({
      code: apiErr.code,
      message: apiErr.rawMessage ?? apiErr.message,
      requestId: apiErr.requestId,
      httpStatus: apiErr.status,
      httpStatusText: apiErr.statusText,
      body: apiErr.body,
      fallback: apiErr.message,
    });
  }
  if (err instanceof Error) return formatApiErrorMessage({ message: err.message, fallback: err.message });
  if (typeof err === 'string') return formatApiErrorMessage({ message: err, fallback: err });
  return i18n.t('error.fallback');
}

/**
 * Panel Session — 新面板前端会话缓存（localStorage）。
 *
 * 对接 docs/architecture/09-new-panel-control-backend-design.md §3.3.2：
 * 新面板 Control 是无状态代理，不建 Cookie/Session；登录凭证
 * （instance_id + user_key）由前端自行持有，缓存在 localStorage
 * （跨 tab 共享，关 tab 不失效），每次 meta 请求从这里读出注入 Header：
 *   - X-Tdai-Service-Id（= 注册表 id = 内核 x-tdai-service-id；早期版本文档曾用
 *     `X-Metadata-Instance-Id` 这个名字，meta-api.openapi.yaml v1.1.0 起已改名，
 *     务必以最新契约为准，否则 Control 会报 400 MISSING_INSTANCE_ID）
 *   - X-Tdai-User-Key（auth/verify 除外）
 *
 * 之前用 sessionStorage（tab 级），导致新开 tab 需要重新登录。
 * 改为 localStorage 后多 tab 共享登录态，登出时通过 storage 事件同步。
 */
import type { PublicUser } from './teamApi';

export interface PanelSession {
  /** = 注册表 id = 内核 x-tdai-service-id；登录页选择实例时确定 */
  instanceId: string;
  /** 仅展示用（实例列表里的 name），非必需 */
  instanceName?: string;
  /** 用户自持的 API 密钥 sk-mem-…；经 auth/verify 验活后缓存 */
  userKey: string;
  /** auth/verify 响应 data.user（可选，用于展示 + 作为 owner_user_id/creator_user_id 来源） */
  user?: PublicUser;
}

const STORAGE_KEY = 'tdai-panel.session';

/** 读取当前会话；无会话或解析失败均返回 null（不抛错，调用方按未登录处理） */
export function getPanelSession(): PanelSession | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    return JSON.parse(raw) as PanelSession;
  } catch {
    return null;
  }
}

/** 登录成功（auth/verify 返回 valid===true）后写入会话 */
export function setPanelSession(session: PanelSession): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(session));
  } catch {
    /* 隐私模式 / 存储配额异常：静默失败，不阻断登录后的本次会话内存态 */
  }
}

/** 登出 / 401 兜底时清空会话 */
export function clearPanelSession(): void {
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch {
    /* ignore */
  }
}

/**
 * Tea 组件桥接工具
 *
 * 提供便捷的方式在现有代码中使用 Tea 组件，
 * 逐步替换原生 HTML 元素和自定义实现。
 *
 * 使用方式:
 *   import { tea } from '@/lib/tea-bridge';
 *   tea.confirm({ message: '确认删除？' }).then(ok => { ... });
 *   tea.notify.success('操作成功');
 *   tea.notify.error('加载失败');  // 弹右上角通知卡片，需手动关闭，不会一闪而过
 *   tea.notify.error(err);  // 传入 Error / ApiError，自动提取 message + request_id
 */

import { getErrorMessage } from './error-message';
import { Modal, message, notification } from 'tea-component';
import i18n from '@/i18n';

function t(key: string, opts?: Record<string, unknown>): string {
  return i18n.t(key, opts);
}

/**
 * 结构化错误通知入参 — 适合需要展示 title + detail + requestId 的场景。
 */
interface StructuredErrorInput {
  title?: string;
  detail?: string;
  requestId?: string;
}

/**
 * 从 unknown 错误对象中尽力提取 request_id。
 * 支持 ApiError（name === 'ApiError'）、SkillApiError、KnowledgeApiError 等。
 */
function extractRequestId(err: unknown): string | undefined {
  if (err && typeof err === 'object' && 'requestId' in err) {
    const v = (err as { requestId?: unknown }).requestId;
    if (typeof v === 'string' && v) return v;
  }
  if (err && typeof err === 'object' && 'request_id' in err) {
    const v = (err as { request_id?: unknown }).request_id;
    if (typeof v === 'string' && v) return v;
  }
  return undefined;
}

export const tea = {
  /**
   * 确认对话框 — 替代 confirm()
   */
  confirm: async (opts: {
    message: string;
    description?: string;
    okText?: string;
    cancelText?: string;
  }) => {
    return Modal.confirm({
      message: opts.message,
      description: opts.description,
      okText: opts.okText ?? t('teaBridge.confirm.ok'),
      cancelText: opts.cancelText ?? t('teaBridge.confirm.cancel'),
    });
  },

  /**
   * 消息提示
   *
   * - success: 轻量 toast（一闪即过，不打断操作）
   * - error:   右上角通知卡片（需手动关闭，确保用户看到错误信息）
   * - warning:  右上角通知卡片（同 error，需手动关闭）
   * - info:     右上角通知卡片
   *
   * 之前 error/warning 用 message.error（toast），3 秒自动消失，
   * 用户经常看不到错误提示就消失了。改用 notification 后错误提示
   * 会一直停留在右上角直到用户手动关闭，确保不会被遗漏。
   *
   * error 入参支持三种形式：
   *   - string：直接作为 description
   *   - Error / ApiError / SkillApiError / KnowledgeApiError：自动提取 message + request_id
   *   - StructuredErrorInput { title?, detail?, requestId? }：结构化方式
   */
  notify: {
    success: (msg: string) => message.success({ content: msg }),
    error: (msg: unknown) => {
      // 结构化入参 { title?, detail?, requestId? }
      if (msg && typeof msg === 'object' && !((msg as unknown) instanceof Error) && ('title' in msg || 'detail' in msg || 'requestId' in msg)) {
        const input = msg as StructuredErrorInput;
        const desc = input.requestId
          ? input.detail
            ? `${input.detail}\nrequest_id: ${input.requestId}`
            : `request_id: ${input.requestId}`
          : input.detail;
        notification.error({
          title: input.title ?? t('teaBridge.notify.errorTitle'),
          description: desc,
        });
        return;
      }
      // Error / string / 其他 — 走 getErrorMessage 提取友好提示
      const friendly = getErrorMessage(msg);
      const requestId = extractRequestId(msg);
      const desc = requestId
        ? `${friendly}\nrequest_id: ${requestId}`
        : friendly;
      notification.error({
        title: t('teaBridge.notify.errorTitle'),
        description: desc,
      });
    },
    warning: (msg: string) =>
      notification.warning({
        title: t('teaBridge.notify.warningTitle'),
        description: msg,
      }),
    info: (msg: string) =>
      notification.success({ description: msg }),
  },

  /**
   * 复杂通知（带自定义标题）
   */
  notification: {
    success: (title: string, description?: string) =>
      notification.success({ title, description }),
    error: (title: string, description?: string) =>
      notification.error({ title, description: description ? getErrorMessage(description) : undefined }),
    warning: (title: string, description?: string) =>
      notification.warning({ title, description }),
  },

  /**
   * 确认删除
   */
  confirmDelete: (name: string, detail?: string) =>
    Modal.confirm({
      message: t('teaBridge.confirmDelete.message', { name }),
      description: detail ?? t('teaBridge.confirmDelete.desc'),
      okText: t('teaBridge.confirmDelete.ok'),
      cancelText: t('teaBridge.confirm.cancel'),
    }),
};

/**
 * 「确认后执行」帮助函数 —— 收敛各资产页大量重复的
 * `tea.confirm(...) → if (!ok) return → try/catch → tea.notify.error` 样板。
 *
 * 用户确认后执行 action；action 抛错时默认走 tea.notify.error(err)
 * （可传 onError 自定义错误提示，如带 i18n 兜底文案）。
 *
 * @returns 用户是否确认并成功执行（取消 / 执行失败均为 false）
 */
export async function confirmThenRun(
  opts: {
    message: string;
    description?: string;
    okText?: string;
    cancelText?: string;
  },
  action: () => Promise<void> | void,
  onError?: (err: unknown) => void,
): Promise<boolean> {
  const ok = await tea.confirm(opts);
  if (!ok) return false;
  try {
    await action();
    return true;
  } catch (err) {
    if (onError) {
      onError(err);
    } else {
      tea.notify.error(err);
    }
    return false;
  }
}

