/**
 * ForkSkillDialog — "复制一份 skill 给某个 agent，且该副本可被该 agent 编辑"。
 *
 * 与「授权（asset visibility=team + acl/grant）」的区别：
 *   - 授权 → 通过\"我的资产分配\"tab 切共享或 acl/grant，不复制内容，其他人
 *     拿到的是对同一份 skill 的读/使用权限；
 *   - fork（本对话框）→ 拉源 skill 的 SKILL.md，**沿用原名 + 目标 agent 为 owner**
 *     调用 skill-api.createSkill 落一份独立副本，之后该 agent 可写。
 *
 * 命名约定：副本**沿用源 skill 原名**，不加后缀。skill 唯一约束基于
 * (team_id, owner_agent_id, name)：同一 team 允许多个同名副本（分属不同 agent），
 * 但目标 agent 下若已存在同名 skill，后端会拒绝（42201），此处提前拦截并提示。
 *
 * 实现：走「getSkill(源) → readSkillFile(附件们) → createSkill(新)」三步。
 */

import { useState } from 'react';
import { Alert, Button, Form, Input, Modal, Select } from 'tea-component';
import { useTranslation } from 'react-i18next';
import '@/components/asset/allocate-dialog.css';

import {
  createSkill,
  getSkill,
  listSkills,
  readSkillFile,
  type SkillSummary,
  type SkillResourcePayload,
} from '@/lib/api/skill-api';

/**
 * 改写 SKILL.md frontmatter 里的 name 字段，保证 DB 记录名与文件内容一致。
 * 仅替换第一个 `--- ... ---` frontmatter 块内的 `name:` 行；无 frontmatter 则原样返回。
 */
function rewriteFrontmatterName(content: string, newName: string): string {
  const fmMatch = content.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!fmMatch) return content;
  const fmBody = fmMatch[1];
  if (!/^\s*name\s*:/m.test(fmBody)) return content; // 无 name 字段，不强行插入
  const newFmBody = fmBody.replace(/^(\s*name\s*:\s*).*/m, `$1${newName}`);
  return content.replace(fmBody, newFmBody);
}

export default function ForkSkillDialog(props: {
  /** 要 fork 的源 skill 名 */
  skillName: string;
  /** v3 API 需要的 skill_id */
  skillId: string;
  agents: Array<{ id: string; name: string }>;
  /** 当前 team ID（v3 API 必传） */
  teamId: string;
  /** 当前用户 ID（v3 API 必传） */
  userId: string;
  onClose: () => void;
  onForked: (newSkill: SkillSummary) => void;
}) {
  const { t } = useTranslation();
  const [agentId, setAgentId] = useState(props.agents[0]?.id ?? '');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  // 副本名默认沿用源 skill 原名，用户可编辑。唯一约束靠 owner_agent_id 区分，
  // 同一 agent 下不允许重名（后端 42201），下方 submit 会提前拦截。
  const [newName, setNewName] = useState(props.skillName);

  async function submit(): Promise<void> {
    if (!agentId) {
      setError(t('forkSkill.error.noAgent'));
      return;
    }
    setError(null);
    setSubmitting(true);
    try {
      // Step 1: 拉源 skill 详情（含 content + manifest）。
      const full = await getSkill({
        skill_id: props.skillId,
        team_id: props.teamId,
        include_content: true,
        include_manifest: true,
      });

      // Step 2: 防御性检查 —— 目标 agent 下已存在同名 skill 则提前拦截，避免后端 42201。
      const existing = await listSkills({
        team_id: props.teamId,
        filters: { owner_agent_id: agentId, status: ['active'] },
        pagination: { limit: 100 },
      });
      if (existing.items.some((s) => s.name === newName)) {
        throw new Error(
          t('forkSkill.error.duplicate', { agent: agentId, name: newName })
        );
      }

      // Step 3: 复制附属资源文件（逐个 readSkillFile；单个失败跳过，不阻断主流程）。
      const resources: SkillResourcePayload[] = [];
      for (const entry of full.manifest ?? []) {
        try {
          const f = await readSkillFile({
            skill_id: props.skillId,
            team_id: props.teamId,
            path: entry.path,
          });
          resources.push({
            path: f.path,
            content: f.content,
            encoding: f.encoding,
            mime_type: f.mime_type || undefined,
            is_executable: entry.is_executable || undefined,
          });
        } catch {
          /* 单个资源读取失败则跳过，不阻断 fork 主流程 */
        }
      }

      // Step 4: 以（可编辑的）副本名 + 目标 agent 为 owner 创建 skill（v3 API）。
      // 若用户改了名，同步改写 SKILL.md frontmatter 的 name 字段，保持 DB 与文件一致。
      const trimmedName = newName.trim();
      const finalContent = trimmedName !== props.skillName
        ? rewriteFrontmatterName(full.content, trimmedName)
        : full.content;
      const created = await createSkill({
        user_id: props.userId,
        team_id: props.teamId,
        agent_id: agentId,
        name: trimmedName,
        content: finalContent,
        resources: resources.length ? resources : undefined,
      });

      const resourceInfo = resources.length > 0
        ? t('forkSkill.success.withResources', { name: props.skillName, agent: agentId, count: resources.length })
        : (full.manifest?.length ?? 0) > 0
          ? t('forkSkill.success.allFailed', { name: props.skillName, agent: agentId, count: full.manifest?.length ?? 0 })
          : t('forkSkill.success.noResources', { name: props.skillName, agent: agentId });
      setSuccess(resourceInfo);
      setTimeout(() => props.onForked(created), 800);
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <Modal visible caption={t('forkSkill.caption')} size="s" onClose={props.onClose} disableEscape={submitting}>
      <Modal.Body>
        <Form>
          <Form.Item label={t('forkSkill.descLabel')}>
            <Form.Text>{t('forkSkill.desc', { name: props.skillName })}</Form.Text>
          </Form.Item>
          <Form.Item label={t('forkSkill.agent')} required>
            <Select
              size="full"
              value={agentId}
              onChange={setAgentId}
              placeholder={t('forkSkill.agent.placeholder')}
              options={props.agents.map((a) => ({ value: a.id, text: `${a.id} · ${a.name}` }))}
            />
          </Form.Item>
          <Form.Item label={t('forkSkill.copyName')} required>
            <Input
              size="full"
              value={newName}
              onChange={setNewName}
              placeholder={t('forkSkill.copyName.placeholder')}
            />
          </Form.Item>
          {error && <Form.Item><Alert type="error">{error}</Alert></Form.Item>}
          {success && <Form.Item><Alert type="success">{success}</Alert></Form.Item>}
        </Form>
      </Modal.Body>
      <Modal.Footer>
        <Button type="primary" onClick={() => void submit()} disabled={submitting || !agentId || !newName.trim()} loading={submitting}>{t('forkSkill.submit')}</Button>
        <Button onClick={props.onClose} disabled={submitting}>{t('forkSkill.cancel')}</Button>
      </Modal.Footer>
    </Modal>
  );
}

/**
 * ImportSkillDialog — 导入 Skill 弹窗。仅支持两种导入方式：
 *
 *   1. 目录导入（directory）
 *      用户选一个本地目录，前端把里面的 File 拆成「主文件」（SKILL.md，
 *      必须在根目录或 <skill-name>/ 下）和「资源文件」（其他文件，保留
 *      相对路径）。走 v3 create 一次性落库（含资源，新建即 v1）。
 *      浏览器目录选择无 Tea 组件等价物，保留原生 <input type="file"
 *      webkitdirectory>，隐藏后由 Tea Button 触发。
 *
 *   2. 对话导入（session）
 *      用户粘贴一段与该 agent 的对话（skill/extract 接口入参 JSON，
 *      含 messages 数组）。前端只做 JSON 校验 + 用当前上下文 ID 覆盖
 *      身份字段，然后调 extractSkills。服务端 LLM 从对话里自动归纳
 *      skill 的 name / description / content，通过工具调用直接落库
 *      （走 SkillCore.create/update 同一条链路），不经过审核。
 *      支持 sync（直接返回结果）和 async（返回 task_id 即视为已受理，
 *      提示用户预计出结果时间后关闭弹窗，不在前端阻塞轮询 —— 结果会异步
 *      沉淀到该 agent 的 skill 列表，用户后续手动刷新即可看到）。
 *
 * 移除说明：原有的「粘贴 SKILL.md 文本」模式已下线 —— 目录导入已覆盖
 * 该场景，且用户手写 frontmatter 极易踩坑（name/description 缺失、
 * YAML 语法错），改由目录导入引导用户放好 SKILL.md 更稳。
 */

import { useMemo, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';

import {
  createSkill,
  extractSkills,
  type SkillResourcePayload,
  type ExtractParams,
} from '@/lib/api/skill-api';
import { Alert, Button, Form, Input, Modal, Segment, Select } from 'tea-component';
import { FolderOpenIcon } from 'tea-icons-react';
import i18n from '@/i18n';
import '../styles/import-skill-dialog.css';

type Mode = 'directory' | 'session';

/**
 * Read a File as base64. Used for binary/executable resources where we
 * can't safely treat bytes as utf8.
 */
async function readAsBase64(file: File): Promise<string> {
  const buf = await file.arrayBuffer();
  // Browser-side base64: chunked to avoid stack-overflow on big files.
  let bin = '';
  const arr = new Uint8Array(buf);
  const chunk = 8192;
  for (let i = 0; i < arr.length; i += chunk) {
    bin += String.fromCharCode(...arr.subarray(i, i + chunk));
  }
  return btoa(bin);
}

async function readAsUtf8(file: File): Promise<string> {
  return file.text();
}

/**
 * Heuristic: extension-based + small-size = text. The gateway already
 * enforces a 5MB cap, but we want to send big binaries as base64 not
 * as a 5MB-of-mojibake string.
 */
function looksLikeText(file: File): boolean {
  const lower = file.name.toLowerCase();
  if (/\.(md|markdown|txt|json|yaml|yml|sh|js|ts|tsx|py|go|rs|toml|html|css|csv|conf|cfg)$/.test(lower)) {
    return true;
  }
  if (file.size < 64 * 1024) return true;
  return false;
}

/**
 * Walk webkitRelativePath like "my-skill/SKILL.md" or "my-skill/files/scripts/x.sh".
 * Returns { skillName, mainFile, resources }; resource paths are
 * normalised relative to `<skill-name>/files/`.
 */
function partitionFiles(files: File[]): {
  skillName: string | null;
  mainFile: File | null;
  resources: Array<{ path: string; file: File }>;
  warning?: string;
} {
  let mainFile: File | null = null;
  let mainRelPath = '';
  for (const f of files) {
    const rel = (f.webkitRelativePath || f.name).replace(/\\/g, '/');
    const segments = rel.split('/');
    const lastSegment = segments[segments.length - 1] ?? '';
    if (lastSegment === 'SKILL.md') {
      // Prefer the shallowest SKILL.md (depth = number of segments).
      if (!mainFile || segments.length < mainRelPath.split('/').length) {
        mainFile = f;
        mainRelPath = rel;
      }
    }
  }
  if (!mainFile) {
    return {
      skillName: null,
      mainFile: null,
      resources: [],
      warning: i18n.t('importSkill.directory.warning'),
    };
  }
  const mainSegments = mainRelPath.split('/');
  const baseDir = mainSegments.slice(0, -1).join('/');
  const skillName = mainSegments.length >= 2 ? mainSegments[mainSegments.length - 2] : null;

  const resources: Array<{ path: string; file: File }> = [];
  for (const f of files) {
    if (f === mainFile) continue;
    let rel = (f.webkitRelativePath || f.name).replace(/\\/g, '/');
    if (baseDir && rel.startsWith(baseDir + '/')) {
      rel = rel.slice(baseDir.length + 1);
    }
    if (rel.startsWith('files/')) rel = rel.slice('files/'.length);
    if (!rel) continue;
    resources.push({ path: rel, file: f });
  }
  return { skillName, mainFile, resources };
}

export default function ImportSkillDialog(props: {
  onClose: () => void;
  onImported: () => void;
  /** 当前激活 team（skill 归属，create 必填） */
  teamId: string;
  /** Import target: 'team' = team pool (default), 'fixed' = agent fixed assets. */
  target?: 'team' | 'fixed';
  /** Agent roster (for fixed-target agent selector). */
  agents?: Array<{ id: string; name: string }>;
  /** Pre-selected agent id (when target='fixed'). */
  agentId?: string;
  /** 当前用户 ID（v3 API 必传） */
  userId: string;
}) {
  const [mode, setMode] = useState<Mode>('directory');
  const [pickedFiles, setPickedFiles] = useState<File[]>([]);
  // session-import：用户粘贴 skill/extract 接口入参（含 messages 数组）。
  // 服务端 LLM 从 messages 自行归纳 skill 的 name / description / content。
  const [sessionPayload, setSessionPayload] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<string | null>(null);
  const [selectedAgentId, setSelectedAgentId] = useState<string>(props.agentId ?? '');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { t } = useTranslation();

  const partition = useMemo(() => (mode === 'directory' ? partitionFiles(pickedFiles) : null), [
    mode,
    pickedFiles
  ]);

  async function submit(): Promise<void> {
    setError(null);
    setResult(null);
    setSubmitting(true);
    try {
      const agentId = props.target === 'fixed' ? (selectedAgentId || props.agentId || '') : '';
      if (props.target === 'fixed' && !agentId) {
        throw new Error(t('importSkill.error.noAgent'));
      }
      if (!props.teamId) throw new Error(t('importSkill.error.noTeam'));

      // ==== 对话导入：直接调 skill/extract ====
      if (mode === 'session') {
        const raw = sessionPayload.trim();
        if (!raw) throw new Error(t('importSkill.error.noPayload'));
        let parsed: Record<string, unknown>;
        try {
          parsed = JSON.parse(raw);
        } catch (e) {
          throw new Error(t('importSkill.error.jsonParse', { msg: e instanceof Error ? e.message : String(e) }));
        }
        if (!Array.isArray((parsed as { messages?: unknown }).messages)) {
          throw new Error(t('importSkill.error.noMessages'));
        }
        const msgs = (parsed as { messages: unknown[] }).messages;
        if (msgs.length === 0) {
          throw new Error(t('importSkill.error.emptyMessages'));
        }
        // 后端 extract 接口限制 messages 最多 500 条（见 iWiki §3.13），
        if (msgs.length > 500) {
          throw new Error(t('importSkill.error.tooManyMessages', { count: msgs.length }));
        }

        // 组装 extract 入参。身份字段（user_id/team_id/agent_id）强制用当前 UI
        // 上下文覆盖，避免用户粘错 team / 伪造他人身份 —— 参见 <security_rules> §3。
        // space_id 不需要显式传：跟其他 skill 接口一致, 后端从 X-Tdai-Service-Id
        // header (= panelSession.instanceId) 取。session_id / task_id 也不传,
        // 让后端生成 —— 避免前端硬编码 "default" / "import-${Date.now()}" 污染归档路径。
        // extract 接口本身不接受 name/description 字段（skill 名和描述由 LLM
        // 从 messages 中自行归纳），JSON 中即便带了这两个字段也不会透传给服务端。
        const extractParams: ExtractParams = {
          user_id: props.userId,
          team_id: props.teamId,
          agent_id: agentId || props.userId,
          task_id: typeof parsed.task_id === 'string' && parsed.task_id ? parsed.task_id : undefined,
          session_id:
            typeof parsed.session_id === 'string' && parsed.session_id
              ? parsed.session_id
              : undefined,
          messages: parsed.messages as ExtractParams['messages'],
          reason:
            typeof parsed.reason === 'string' && parsed.reason
              ? parsed.reason
              : 'manual import from console',
          options:
            typeof parsed.options === 'object' && parsed.options !== null
              ? (parsed.options as ExtractParams['options'])
              : undefined,
        };

        // 后端 extract 恒走 archive → agent 队列 → worker 异步链路,
        // 永远返回 task_id (没有 sync candidates 分支了)。前端拿到 task_id 即
        // 视为"已受理"，提示预计出结果时间后关闭弹窗；结果由 SkillCoreSink 异步
        // 写入 skill 表，用户回列表刷新即可看到。
        //
        // 前端软超时兜底（5s）：archive 链路涉及 COS 顺序读写（读 _tasks.json →
        // 写 data-xxx.jsonl → 写 _tasks.json），当 COS 慢时整体耗时容易超过
        // Panel 后端 15s 硬超时（KERNEL_TIMEOUT/504），从而在 UI 上误报失败。
        // 实际上请求已经在服务端排入队列，后端会继续跑完 archive。因此这里
        // 5s 内后端有响应就按真结果走；5s 到点还没回就直接展示"已受理"文案，
        // 不再阻塞用户 —— 后端调用在浏览器 fetch 层继续跑（不 abort），最坏
        // 情况是 15s 后 Panel 回 504，我们的 catch 静默吞掉（用户已经看到成功了）。
        const TIMEOUT_MS = 5000;
        let softTimedOut = false;
        const extractPromise = extractSkills(extractParams).catch((e) => {
          // 如果已经软超时展示了成功文案，这里就静默吞掉后续错误（504 等）。
          if (softTimedOut) return null;
          throw e;
        });
        const timeoutPromise = new Promise<'timeout'>((resolve) =>
          setTimeout(() => resolve('timeout'), TIMEOUT_MS),
        );
        const raced = await Promise.race([extractPromise, timeoutPromise]);
        if (raced === 'timeout') {
          softTimedOut = true;
          setResult(t('importSkill.result.session.accepted'));
        } else if (raced) {
          setResult(t('importSkill.result.session', { taskId: raced.task_id }));
        } else {
          // extractPromise 被软超时后 catch 成 null 的分支（正常不会走到这里，
          // 因为软超时已经先设过 result 了），兜底保持一致文案。
          setResult(t('importSkill.result.session.accepted'));
        }
        setTimeout(() => props.onImported(), 1500);
        return;
      }

      // ==== 目录导入：走 v3 create + files/write ====
      if (!partition?.mainFile) {
        throw new Error(partition?.warning ?? t('importSkill.error.noMainFile'));
      }
      const content = await readAsUtf8(partition.mainFile);
      const fmMatch = content.match(/^---\n([\s\S]*?)\n---/);
      const nameMatch = fmMatch?.[1].match(/^name:\s*(.+)$/m);
      const name = nameMatch?.[1].trim().replace(/^["']|["']$/g, '') || partition.skillName || '';
      if (!name) {
        throw new Error(t('importSkill.error.noName'));
      }
      const resourceFiles: { path: string; file: File; isBinary: boolean }[] = partition.resources.map(
        ({ path, file }) => ({ path, file, isBinary: !looksLikeText(file) }),
      );

      // 确保 content 以 `---\n` 开头（v3 frontmatter 格式要求）。
      const safeContent = content.trimStart().startsWith('---') ? content : `---\nname: ${name}\n---\n\n${content}`;

      // 资源文件随 create 一次性落库（单版本 v1）。
      // 修复：原实现是 create(resources=[] → v1) + files/write(→ v2) 两步，
      // 导致任何带资源的导入 skill 一落库就是 v2（version 语义错乱）。
      // v3 create 本身支持 resources 数组，合并为一次调用即可保证新建 skill = v1。
      const resources: SkillResourcePayload[] = resourceFiles.length > 0
        ? await Promise.all(
            resourceFiles.map(async ({ path, file, isBinary }) =>
              isBinary
                ? { path, content: await readAsBase64(file), encoding: 'base64' as const }
                : { path, content: await readAsUtf8(file), encoding: 'utf-8' as const },
            ),
          )
        : [];

      await createSkill({
        user_id: props.userId,
        team_id: props.teamId,
        agent_id: agentId || props.userId, // v3 要求 agent_id，固定模式用选中的，否则用 userId 兜底
        name,
        content: safeContent,
        resources: resources.length ? resources : undefined,
      });

      setResult(t('importSkill.result.directory', { name, count: resourceFiles.length }));
      setTimeout(() => props.onImported(), 800);
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setSubmitting(false);
    }
  }

  // 是否需要在弹窗内显示「归属 Agent」选择器：
  //   - 仅 fixed-target 才有 agent 归属概念
  //   - 必须传了 agents 才能渲染下拉
  const showAgentPicker = props.target === 'fixed' && !!props.agents;

  return (
    <Modal visible caption={t('importSkill.caption')} size="l" onClose={props.onClose} disableEscape={submitting}>
      <Modal.Body>
        <Alert type="info">{t('importSkill.hint')}</Alert>
      {/* 归属 Agent —— 必选项。始终展示在导入方式上方，
          与 ChatMemoryPanel.ImportBlockDialog 一致：即便外层已经传了 agentId
          也允许在弹窗里重选。 */}
      {showAgentPicker && (
        <Form layout="vertical" style={{ width: '100%' }}>
          <Form.Item
            label={t('importSkill.agent')}
            extra={t('importSkill.agent.extra')}
          >
            {props.agents!.length === 0 ? (
              <Alert type="warning">{t('importSkill.agent.noAgent')}</Alert>
            ) : (
              <Select
                size="full"
                value={selectedAgentId}
                onChange={setSelectedAgentId}
                placeholder={t('importSkill.agent.placeholder')}
                options={props.agents!.map((a) => ({ value: a.id, text: `${a.name}（${a.id}）` }))}
              />
            )}
          </Form.Item>
        </Form>
      )}

      {/* Mode tabs：只保留 directory（目录导入）/ session（对话导入）两种 */}
      <Segment
        className="_memory-isd-mode-segment"
        value={mode}
        onChange={(v) => setMode(v as Mode)}
        options={[
          { value: 'directory', text: t('importSkill.mode.directory') },
          { value: 'session', text: t('importSkill.mode.session') },
        ]}
      />

      {mode === 'directory' && (
        <div className="_memory-isd-section">
          <div className="_memory-isd-label">{t('importSkill.directory.label')}</div>
          {/*
            目录选择无 Tea 组件等价物，此处保留原生 input 作为唯一豁免，隐藏后由下方
            Tea Button 触发点击。webkitdirectory/directory 是非标准但广泛支持的浏览器
            属性，React 类型定义未收录，用 spread + any 透传而非逐属性 @ts-expect-error。
          */}
          <input
            ref={fileInputRef}
            type="file"
            multiple
            onChange={(e) => {
              const list = e.target.files;
              if (!list) return;
              setPickedFiles(Array.from(list));
            }}
            className="_memory-isd-hidden-file-input"
            {...({ webkitdirectory: '', directory: '' } as Record<string, string>)}
          />
          <Button onClick={() => fileInputRef.current?.click()}>
            <FolderOpenIcon size={14} /> {t('importSkill.directory.selectFile')}
          </Button>
          {pickedFiles.length > 0 && (
            <span className="_memory-isd-picked-count">{t('importSkill.directory.picked', { count: pickedFiles.length })}</span>
          )}
          {pickedFiles.length > 0 && partition && (
            <div className="_memory-isd-partition-box">
              <div>
                {t('importSkill.directory.mainFile')}
                {partition.mainFile ? (
                  <span className="_memory-isd-main-file">
                    {partition.mainFile.webkitRelativePath || partition.mainFile.name}
                  </span>
                ) : (
                  <span className="_memory-isd-error-text">{t('importSkill.directory.noSkillMd')}</span>
                )}
              </div>
              <div>{t('importSkill.directory.resources', { count: partition.resources.length })}</div>
              {partition.resources.length > 0 && (
                <ul className="_memory-isd-resource-list">
                  {partition.resources.map((r) => (
                    <li key={r.path}>· {r.path} ({Math.round(r.file.size / 1024)}KB)</li>
                  ))}
                </ul>
              )}
              {partition.warning && (
                <div className="_memory-isd-warning-text">{partition.warning}</div>
              )}
            </div>
          )}
        </div>
      )}

      {mode === 'session' && (
        <div className="_memory-isd-section">
          <Alert type="info">
            {t('importSkill.session.hintPrefix')}
            <span className="_memory-isd-mono-inline">messages</span>
            {t('importSkill.session.hintSuffix')}
          </Alert>
          <Form layout="vertical" style={{ width: '100%' }}>
            <Form.Item label={t('importSkill.session.label')}>
              <Input.TextArea
                size="full"
                value={sessionPayload}
                onChange={setSessionPayload}
                rows={16}
                placeholder={JSON.stringify(
                  {
                    session_id: 'demo-user-extract-demo-1',
                    task_id: 'default',
                    messages: [
                      { role: 'user', content: t('importSkill.sample.user') },
                      { role: 'assistant', content: t('importSkill.sample.assistant') },
                      { role: 'tool_call', content: t('importSkill.sample.toolCall') },
                      { role: 'tool_result', content: t('importSkill.sample.toolResult') },
                      { role: 'assistant', content: t('importSkill.sample.assistant2') },
                    ],
                  },
                  null,
                  2,
                )}
                className="_memory-isd-mono-input"
              />
            </Form.Item>
          </Form>
        </div>
      )}

      {error && <Alert type="error">{error}</Alert>}
      {result && <Alert type="success"><span className="_memory-isd-result-text">{result}</span></Alert>}
      </Modal.Body>
      <Modal.Footer>
        <Button
          type="primary"
          onClick={() => void submit()}
          disabled={
            submitting
            || (mode === 'directory' ? !partition?.mainFile : !sessionPayload.trim())
            || (props.target === 'fixed' && !selectedAgentId)
          }
          title={props.target === 'fixed' && !selectedAgentId ? t('importSkill.error.noAgentHint') : ''}
          loading={submitting}
        >
          {mode === 'session' ? t('importSkill.session.submit') : t('importSkill.submit')}
        </Button>
        <Button onClick={props.onClose} disabled={submitting}>{t('importSkill.cancel')}</Button>
      </Modal.Footer>
    </Modal>
  );
}

/**
 * SkillDetailPane — SkillsPanel 右栏，展示单条 skill 的 frontmatter、正文
 * Markdown 与资源文件树；owner 还可在此就地编辑。
 *
 * 编辑能力（仅 canEdit=owner 时开放，写操作均带 expected_version 乐观锁）：
 *   - 正文：编辑完整 SKILL.md（updateSkill）
 *   - 资源文件：新建 / 编辑 / 删除（writeSkillFiles / removeSkillFiles）
 *   - 版本历史：按需加载并只读查看任一历史版本（listSkillVersions + getSkill@version）
 *
 * 任一写操作成功后 version 会 +1，因此统一 reload() 重新拉取详情并通知父组件刷新列表，
 * 保证下一次编辑携带的 expected_version 是最新值。
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Card, Copy, Input, Modal, Table, Text } from 'tea-component';
import { MarkdownView } from '@/components/MarkdownView';
import { tea } from '@/lib/tea-bridge';
import {
  getSkill,
  readSkillFile,
  updateSkill,
  writeSkillFiles,
  removeSkillFiles,
  listSkillVersions,
  type SkillDetail,
  type SkillSummary,
  type ReadFileResult,
} from '@/lib/api/skill-api';
import '../styles/skill-detail.css';

interface FileTreeNode {
  name: string;
  fullPath: string | null; // null for directories
  children: FileTreeNode[];
}

/**
 * Build a tree from an array of "scripts/foo.sh" / "templates/x/y.txt" paths.
 * Sorts directories before files at each level for stable layout.
 */
function buildFileTree(paths: string[]): FileTreeNode[] {
  const root: FileTreeNode = { name: '', fullPath: null, children: [] };
  for (const p of paths) {
    const parts = p.split('/').filter(Boolean);
    let cursor = root;
    for (let i = 0; i < parts.length; i++) {
      const isLeaf = i === parts.length - 1;
      const segName = parts[i];
      let child = cursor.children.find((c) => c.name === segName);
      if (!child) {
        child = {
          name: segName,
          fullPath: isLeaf ? p : null,
          children: [],
        };
        cursor.children.push(child);
      }
      cursor = child;
    }
  }
  // Sort: dirs first, then files; alphabetical within each group.
  const sortRec = (node: FileTreeNode): void => {
    node.children.sort((a, b) => {
      const aDir = a.fullPath === null;
      const bDir = b.fullPath === null;
      if (aDir !== bDir) return aDir ? -1 : 1;
      return a.name.localeCompare(b.name);
    });
    node.children.forEach(sortRec);
  };
  sortRec(root);
  return root.children;
}

function FileTreeView(props: { nodes: FileTreeNode[]; onPick: (path: string) => void }) {
  // 缩进靠嵌套 ul 的固定 padding（见 css），不在 li 上写动态内联 style。
  return (
    <ul className="_memory-skill-filetree">
      {props.nodes.map((n) => (
        <li key={n.name}>
          {n.fullPath ? (
            <button
              type="button"
              onClick={() => props.onPick(n.fullPath!)}
              className="_memory-skill-file-btn"
            >
              {n.name}
            </button>
          ) : (
            <>
              <div className="_memory-skill-dir">{n.name}/</div>
              <FileTreeView nodes={n.children} onPick={props.onPick} />
            </>
          )}
        </li>
      ))}
    </ul>
  );
}

export default function SkillDetailPane(props: {
  /** 当前选中的 skill_id —— 权威选中标识，直接来自 selectedSkillId（独立 state），
   *  不经过列表派生，因此不受 agent/skill 列表加载或刷新时序影响。 */
  skillId?: string;
  /** 列表里已知的 skill 名（作标题）；列表未加载完时可能暂为 null，详情返回后用 view.name 兜底 */
  skillName: string | null;
  /** 当前 team（写操作入参）；缺省时回退到详情里的 team_id */
  teamId?: string;
  /** 当前登录用户 id（写操作入参 user_id） */
  userId?: string;
  /** 当前用户是否可编辑该 skill（owner）；false 时全部编辑入口隐藏 */
  canEdit?: boolean;
  /** 编辑成功后回调父组件刷新列表（版本/时间变化） */
  onChanged?: () => void;
}) {
  const { t } = useTranslation();
  const [view, setView] = useState<SkillDetail | null>(null);
  // 初始为 true：有 skillId 时首帧就处于「加载中」，避免首次进入先闪一帧空白再变加载态
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filePreview, setFilePreview] = useState<ReadFileResult | null>(null);
  const [filePreviewLoading, setFilePreviewLoading] = useState(false);

  // 正文编辑态
  const [editingBody, setEditingBody] = useState(false);
  const [bodyDraft, setBodyDraft] = useState('');
  const [savingBody, setSavingBody] = useState(false);

  // 文件编辑态（在预览 Modal 内）
  const [fileEditing, setFileEditing] = useState(false);
  const [fileDraft, setFileDraft] = useState('');
  const [fileSaving, setFileSaving] = useState(false);

  // 新建文件 Modal
  const [showNewFile, setShowNewFile] = useState(false);
  const [newFilePath, setNewFilePath] = useState('');
  const [newFileContent, setNewFileContent] = useState('');
  const [newFileSaving, setNewFileSaving] = useState(false);

  // 版本历史
  const [showVersions, setShowVersions] = useState(false);
  const [versions, setVersions] = useState<SkillSummary[] | null>(null);
  const [versionsLoading, setVersionsLoading] = useState(false);
  const [versionView, setVersionView] = useState<SkillDetail | null>(null);
  const [versionViewLoading, setVersionViewLoading] = useState(false);
  // 历史版本查看 Modal 内的文件预览
  const [versionFile, setVersionFile] = useState<ReadFileResult | null>(null);
  const [versionFileLoading, setVersionFileLoading] = useState(false);

  const stickyRef = useRef<{ id: string; name: string } | null>(null);
  if (props.skillId && props.skillName) {
    stickyRef.current = { id: props.skillId, name: props.skillName };
  }
  const skillId = props.skillId ?? stickyRef.current?.id ?? '';
  const skillName = props.skillName ?? stickyRef.current?.name ?? null;
  const canEdit = !!props.canEdit;

  const loadDetail = useCallback(() => {
    if (!skillId) {
      setView(null);
      setError(null);
      setLoading(false);
      return;
    }
    setLoading(true);
    setError(null);
    getSkill({ skill_id: skillId, include_content: true, include_manifest: true })
      .then((v) => setView(v))
      .catch((err) => setError(err instanceof Error ? err.message : String(err)))
      .finally(() => setLoading(false));
  }, [skillId]);

  useEffect(() => {
    // 切换 skill 时重置所有编辑/版本态，避免残留上一条的草稿
    setView(null);
    setEditingBody(false);
    setVersions(null);
    setShowVersions(false);
    setVersionView(null);
    setVersionFile(null);
    setFilePreview(null);
    loadDetail();
  }, [loadDetail]);

  // view 的清空发生在切换时，渲染期先按 skill_id 校验归属：不属于当前 skillId 就
  // 视为「尚未加载」，避免切换时闪一帧上一个 skill 的正文 / 描述。
  const stale = !!view && view.skill_id !== skillId;
  const currentView = stale ? null : view;
  const showLoading = !!skillId && (loading || stale);

  const fileTree = useMemo(
    () => buildFileTree(currentView?.manifest?.map((e) => e.path) ?? []),
    [currentView],
  );

  // 写操作统一入参：team_id 优先用 props，回退详情；agent_id = owner_agent_id
  const writeCtx = useMemo(() => {
    if (!currentView) return null;
    const teamId = props.teamId || currentView.team_id;
    const agentId = currentView.owner_agent_id;
    if (!teamId || !agentId || !props.userId) return null;
    return { user_id: props.userId, team_id: teamId, agent_id: agentId };
  }, [currentView, props.teamId, props.userId]);

  const editable = canEdit && !!writeCtx;

  // 写成功后：重新拉详情拿最新 version，并通知父组件刷新列表
  const reload = useCallback(() => {
    loadDetail();
    props.onChanged?.();
  }, [loadDetail, props]);

  async function pickFile(path: string): Promise<void> {
    if (!skillId) return;
    setFileEditing(false);
    setFilePreviewLoading(true);
    try {
      const f = await readSkillFile({ skill_id: skillId, path, encoding: 'utf-8' });
      setFilePreview(f);
    } catch (err) {
      setFilePreview({
        path,
        content: t('skills.detail.readFailed', {
          msg: err instanceof Error ? err.message : String(err),
        }),
        encoding: 'utf-8',
        size_bytes: 0,
        mime_type: 'text/plain',
        version: 0,
      });
    } finally {
      setFilePreviewLoading(false);
    }
  }

  // ── 正文编辑 ──
  function startEditBody() {
    if (!currentView) return;
    setBodyDraft(currentView.content);
    setEditingBody(true);
  }

  async function saveBody() {
    if (!currentView || !writeCtx) return;
    if (!bodyDraft.trim()) {
      tea.notify.error({ description: t('skills.detail.emptyContent') });
      return;
    }
    setSavingBody(true);
    try {
      await updateSkill({
        ...writeCtx,
        skill_id: currentView.skill_id,
        expected_version: currentView.version,
        content: bodyDraft,
      });
      tea.notify.success(t('skills.detail.saveSuccess'));
      setEditingBody(false);
      reload();
    } catch (err) {
      tea.notify.error(err);
    } finally {
      setSavingBody(false);
    }
  }

  // ── 文件编辑（预览 Modal 内）──
  function startEditFile() {
    if (!filePreview) return;
    setFileDraft(filePreview.content);
    setFileEditing(true);
  }

  async function saveFile() {
    if (!currentView || !writeCtx || !filePreview) return;
    setFileSaving(true);
    try {
      await writeSkillFiles({
        ...writeCtx,
        skill_id: currentView.skill_id,
        expected_version: currentView.version,
        files: [{ path: filePreview.path, content: fileDraft, encoding: 'utf-8' }],
      });
      tea.notify.success(t('skills.detail.fileSaved'));
      setFilePreview({ ...filePreview, content: fileDraft });
      setFileEditing(false);
      reload();
    } catch (err) {
      tea.notify.error(err);
    } finally {
      setFileSaving(false);
    }
  }

  async function deleteFile(path: string) {
    if (!currentView || !writeCtx) return;
    const ok = await tea.confirm({
      message: t('skills.detail.deleteFileConfirm', { path }),
      description: t('skills.detail.deleteFileDesc'),
      okText: t('skills.detail.deleteFileOk'),
      cancelText: t('skills.detail.deleteFileCancel'),
    });
    if (!ok) return;
    try {
      await removeSkillFiles({
        ...writeCtx,
        skill_id: currentView.skill_id,
        expected_version: currentView.version,
        paths: [path],
      });
      tea.notify.success(t('skills.detail.fileDeleted'));
      setFilePreview(null);
      reload();
    } catch (err) {
      tea.notify.error(err);
    }
  }

  // ── 新建文件 ──
  async function createFile() {
    if (!currentView || !writeCtx) return;
    if (!newFilePath.trim()) {
      tea.notify.error({ description: t('skills.detail.filePathRequired') });
      return;
    }
    setNewFileSaving(true);
    try {
      await writeSkillFiles({
        ...writeCtx,
        skill_id: currentView.skill_id,
        expected_version: currentView.version,
        files: [{ path: newFilePath.trim(), content: newFileContent, encoding: 'utf-8' }],
      });
      tea.notify.success(t('skills.detail.fileSaved'));
      setShowNewFile(false);
      setNewFilePath('');
      setNewFileContent('');
      reload();
    } catch (err) {
      tea.notify.error(err);
    } finally {
      setNewFileSaving(false);
    }
  }

  // ── 版本历史 ──
  async function loadVersions() {
    if (!currentView) return;
    setVersionsLoading(true);
    try {
      const res = await listSkillVersions({
        skill_id: currentView.skill_id,
        team_id: props.teamId || currentView.team_id,
      });
      setVersions(res.items);
    } catch (err) {
      tea.notify.error(err);
      setVersions([]);
    } finally {
      setVersionsLoading(false);
    }
  }

  async function viewVersion(version: number) {
    if (!currentView) return;
    setVersionViewLoading(true);
    try {
      const v = await getSkill({
        skill_id: currentView.skill_id,
        team_id: props.teamId || currentView.team_id,
        version,
        include_content: true,
        include_manifest: true,
      });
      setVersionView(v);
    } catch (err) {
      tea.notify.error(err);
    } finally {
      setVersionViewLoading(false);
    }
  }

  // 历史版本查看 Modal 内的文件预览（只读，按 version 读取历史文件内容）
  async function viewVersionFile(path: string) {
    if (!versionView) return;
    setVersionFileLoading(true);
    setVersionFile({
      path,
      content: '',
      encoding: 'utf-8',
      size_bytes: 0,
      mime_type: 'text/plain',
      version: versionView.version,
    });
    try {
      const f = await readSkillFile({
        skill_id: versionView.skill_id,
        path,
        version: versionView.version,
        encoding: 'utf-8',
      });
      setVersionFile(f);
    } catch (err) {
      setVersionFile({
        path,
        content: t('skills.detail.readFailed', {
          msg: err instanceof Error ? err.message : String(err),
        }),
        encoding: 'utf-8',
        size_bytes: 0,
        mime_type: 'text/plain',
        version: versionView.version,
      });
    } finally {
      setVersionFileLoading(false);
    }
  }

  if (!skillName) {
    return (
      <Card className="_memory-skill-detail-card">
        <Card.Body className="_memory-skill-detail-empty">
          <Text theme="weak">{t('skills.detail.empty')}</Text>
        </Card.Body>
      </Card>
    );
  }

  return (
    <Card className="_memory-skill-detail-card">
      <Card.Body className="_memory-skill-detail-body">
        {/* 固定悬浮头部：skill 名 + 描述 + 操作栏（不随内容滚动，避免用户滑很久才点到功能） */}
        <div className="_memory-skill-detail-head">
          <div className="_memory-skill-detail-head-main">
            <div className="_memory-skill-detail-head-info">
              <div className="_memory-skill-detail-name">{skillName ?? currentView?.name ?? ''}</div>
              {/* skill_id（= asset_id）：给出可复制的资产标识，便于对接 API /
                  排查问题时引用。用 skillId（权威选中值）而非 currentView，
                  详情还在加载时也能立即显示。 */}
              {skillId && (
                <div className="_memory-skill-detail-id">
                  <span className="_memory-skill-detail-id-text" title={skillId}>
                    {skillId}
                  </span>
                  <Copy text={skillId} />
                </div>
              )}
              {currentView?.description && (
                <Text theme="weak" parent="div" className="_memory-skill-detail-desc">
                  {currentView.description}
                </Text>
              )}
            </div>
            {currentView && (
              <div className="_memory-skill-detail-actions">
                {editable && !editingBody && (
                  <Button type="primary" onClick={startEditBody}>
                    {t('skills.detail.edit')}
                  </Button>
                )}
                {editable && (
                  <Button onClick={() => setShowNewFile(true)}>{t('skills.detail.addFile')}</Button>
                )}
                <Button
                  onClick={() => {
                    setShowVersions(true);
                    if (versions === null) void loadVersions();
                  }}
                >
                  {t('skills.detail.versions')}
                </Button>
              </div>
            )}
          </div>
        </div>

        {/* 滚动内容区。刷新中（编辑/新建保存后 reload，此时 currentView 仍在）
            叠加半透明遮罩 + loading，给出明确的加载反馈；首次加载（无 currentView）则显示纯 loading 文字。 */}
        <div
          className={`_memory-skill-detail-scroll${showLoading && currentView ? ' _memory-skill-detail-scroll--refreshing' : ''}`}
        >
          {showLoading && currentView && (
            <div className="_memory-skill-detail-refresh-mask">
              <Text theme="weak">{t('skills.detail.loading')}</Text>
            </div>
          )}
          {!stale && error && (
            <Text theme="danger" parent="div" className="_memory-skill-detail-error">
              {error}
            </Text>
          )}
          {showLoading && !currentView && (
            <Text theme="weak" parent="div">
              {t('skills.detail.loading')}
            </Text>
          )}
          {currentView && (
            <>
              {/* Metadata */}
              <div className="_memory-skill-detail-section">
                <Text theme="label" parent="div" className="_memory-skill-detail-section-title">
                  {t('skills.detail.frontmatter')}
                </Text>
                <pre className="_memory-skill-detail-json">
                  {JSON.stringify(
                    {
                      name: currentView.name,
                      description: currentView.description,
                      version: currentView.version,
                      owner_user_id: currentView.owner_user_id,
                      owner_agent_id: currentView.owner_agent_id,
                      created_at_ms: currentView.created_at_ms,
                      updated_at_ms: currentView.updated_at_ms,
                    },
                    null,
                    2,
                  )}
                </pre>
              </div>

              {/* Body（可编辑完整 SKILL.md，编辑入口在顶部固定操作栏） */}
              <div className="_memory-skill-detail-section">
                <Text theme="label" parent="div" className="_memory-skill-detail-section-title">
                  {t('skills.detail.body')}
                </Text>
                {editingBody ? (
                  <div className="_memory-skill-edit-box">
                    <Input.TextArea
                      size="full"
                      className="_memory-skill-edit-textarea"
                      value={bodyDraft}
                      onChange={(v) => setBodyDraft(v)}
                      disabled={savingBody}
                    />
                    <Text theme="weak" parent="div" className="_memory-skill-edit-hint">
                      {t('skills.detail.editBodyHint')}
                    </Text>
                    <div className="_memory-skill-edit-actions">
                      <Button type="primary" onClick={saveBody} loading={savingBody}>
                        {t('skills.detail.save')}
                      </Button>
                      <Button onClick={() => setEditingBody(false)} disabled={savingBody}>
                        {t('skills.detail.cancel')}
                      </Button>
                    </div>
                  </div>
                ) : (
                  <MarkdownView>{extractBody(currentView.content)}</MarkdownView>
                )}
              </div>
            </>
          )}
        </div>

        {/* 附属资源固定在底部：中间正文可滚动，附属资源始终可见，无需滑到底部查找。
            新建入口在顶部固定操作栏。 */}
        {currentView && (
          <div className="_memory-skill-detail-footer">
            <Text theme="label" parent="div" className="_memory-skill-detail-section-title">
              {t('skills.detail.files', { count: currentView.manifest?.length ?? 0 })}
            </Text>
            {!currentView.manifest || currentView.manifest.length === 0 ? (
              <Text theme="weak" parent="div">
                {t('skills.detail.noFiles')}
              </Text>
            ) : (
              <div className="_memory-skill-files-box _memory-skill-files-box--footer">
                <FileTreeView nodes={fileTree} onPick={pickFile} />
              </div>
            )}
          </div>
        )}
      </Card.Body>

      {/* Inline file-preview modal（支持编辑 / 删除） */}
      {filePreview && (
        <Modal
          visible
          caption={filePreview.path}
          size="xl"
          onClose={() => {
            setFilePreview(null);
            setFileEditing(false);
          }}
        >
          <Modal.Body>
            {filePreviewLoading ? (
              <Text theme="weak" parent="div">
                {t('skills.detail.loading')}
              </Text>
            ) : filePreview.encoding === 'base64' ? (
              <Text theme="weak" parent="div">
                {t('skills.detail.binaryFile', { size: filePreview.size_bytes })}
              </Text>
            ) : fileEditing ? (
              <Input.TextArea
                size="full"
                className="_memory-skill-edit-textarea"
                value={fileDraft}
                onChange={(v) => setFileDraft(v)}
                disabled={fileSaving}
              />
            ) : (
              <pre className="_memory-skill-file-content">{filePreview.content}</pre>
            )}
          </Modal.Body>
          {editable && !filePreviewLoading && (
            <Modal.Footer>
              {filePreview.encoding === 'base64' ? (
                <Text theme="weak">{t('skills.detail.binaryEditHint')}</Text>
              ) : fileEditing ? (
                <>
                  <Button type="primary" onClick={saveFile} loading={fileSaving}>
                    {t('skills.detail.save')}
                  </Button>
                  <Button onClick={() => setFileEditing(false)} disabled={fileSaving}>
                    {t('skills.detail.cancel')}
                  </Button>
                </>
              ) : (
                <>
                  <Button type="primary" onClick={startEditFile}>
                    {t('skills.detail.editFile')}
                  </Button>
                  <Button onClick={() => deleteFile(filePreview.path)}>
                    {t('skills.detail.deleteFile')}
                  </Button>
                </>
              )}
            </Modal.Footer>
          )}
        </Modal>
      )}

      {/* 新建文件 Modal */}
      {showNewFile && (
        <Modal
          visible
          caption={t('skills.detail.newFileTitle')}
          size="l"
          onClose={() => setShowNewFile(false)}
        >
          <Modal.Body>
            <div className="_memory-skill-newfile-field">
              <Text theme="label" parent="div">
                {t('skills.detail.filePathLabel')}
              </Text>
              <Input
                size="full"
                value={newFilePath}
                onChange={(v) => setNewFilePath(v)}
                placeholder={t('skills.detail.filePathPlaceholder')}
                className="_memory-skill-newfile-path"
                disabled={newFileSaving}
              />
            </div>
            <div className="_memory-skill-newfile-field">
              <Text theme="label" parent="div">
                {t('skills.detail.fileContentLabel')}
              </Text>
              <Input.TextArea
                size="full"
                className="_memory-skill-edit-textarea"
                value={newFileContent}
                onChange={(v) => setNewFileContent(v)}
                disabled={newFileSaving}
              />
            </div>
          </Modal.Body>
          <Modal.Footer>
            <Button type="primary" onClick={createFile} loading={newFileSaving}>
              {t('skills.detail.save')}
            </Button>
            <Button onClick={() => setShowNewFile(false)} disabled={newFileSaving}>
              {t('skills.detail.cancel')}
            </Button>
          </Modal.Footer>
        </Modal>
      )}

      {/* 版本历史列表 Modal */}
      {showVersions && currentView && (
        <Modal
          visible
          caption={t('skills.detail.versions')}
          size="l"
          onClose={() => setShowVersions(false)}
        >
          <Modal.Body>
            {versionsLoading ? (
              <Text theme="weak" parent="div">
                {t('skills.detail.loading')}
              </Text>
            ) : !versions || versions.length === 0 ? (
              <Text theme="weak" parent="div">
                {t('skills.detail.versionsEmpty')}
              </Text>
            ) : (
              <Table
                records={versions}
                recordKey="version"
                columns={[
                  {
                    key: 'version',
                    header: t('skills.detail.versionColVersion'),
                    width: 140,
                    render: (v) => (
                      <span className="_memory-skill-version-label">
                        v{v.version}
                        {v.version === currentView.version && (
                          <span className="_memory-skill-version-current">
                            （{t('skills.detail.versionCurrent')}）
                          </span>
                        )}
                      </span>
                    ),
                  },
                  {
                    key: 'updated_at_ms',
                    header: t('skills.detail.versionColTime'),
                    render: (v) => new Date(v.updated_at_ms).toLocaleString(),
                  },
                  {
                    key: 'actions',
                    header: t('skills.detail.versionColActions'),
                    width: 100,
                    render: (v) => (
                      <Button type="link" onClick={() => viewVersion(v.version)}>
                        {t('skills.detail.versionView')}
                      </Button>
                    ),
                  },
                ]}
              />
            )}
          </Modal.Body>
        </Modal>
      )}

      {/* 历史版本查看 Modal（只读：正文 + 附属资源） */}
      {(versionView || versionViewLoading) && (
        <Modal
          visible
          caption={
            versionView
              ? t('skills.detail.versionCaption', { version: versionView.version })
              : t('skills.detail.loading')
          }
          size="xl"
          onClose={() => {
            setVersionView(null);
            setVersionFile(null);
          }}
        >
          <Modal.Body>
            {versionViewLoading ? (
              <Text theme="weak" parent="div">
                {t('skills.detail.loading')}
              </Text>
            ) : versionView ? (
              <>
                <MarkdownView>{extractBody(versionView.content)}</MarkdownView>
                {/* 该历史版本的附属资源（只读） */}
                <div className="_memory-skill-detail-section _memory-skill-version-files">
                  <Text theme="label" parent="div" className="_memory-skill-detail-section-title">
                    {t('skills.detail.files', { count: versionView.manifest?.length ?? 0 })}
                  </Text>
                  {!versionView.manifest || versionView.manifest.length === 0 ? (
                    <Text theme="weak" parent="div">
                      {t('skills.detail.noFiles')}
                    </Text>
                  ) : (
                    <div className="_memory-skill-files-box">
                      <FileTreeView
                        nodes={buildFileTree(versionView.manifest.map((e) => e.path))}
                        onPick={viewVersionFile}
                      />
                    </div>
                  )}
                </div>
              </>
            ) : null}
          </Modal.Body>
        </Modal>
      )}

      {/* 历史版本文件预览 Modal（只读） */}
      {(versionFile || versionFileLoading) && (
        <Modal
          visible
          caption={versionFile?.path ?? t('skills.detail.loading')}
          size="xl"
          onClose={() => setVersionFile(null)}
        >
          <Modal.Body>
            {versionFileLoading ? (
              <Text theme="weak" parent="div">
                {t('skills.detail.loading')}
              </Text>
            ) : versionFile?.encoding === 'base64' ? (
              <Text theme="weak" parent="div">
                {t('skills.detail.binaryFile', { size: versionFile.size_bytes })}
              </Text>
            ) : versionFile ? (
              <pre className="_memory-skill-file-content">{versionFile.content}</pre>
            ) : null}
          </Modal.Body>
        </Modal>
      )}
    </Card>
  );
}

/** 从 SKILL.md 中提取正文（去掉 YAML frontmatter） */
function extractBody(content: string): string {
  const m = content.match(/^---\s*\r?\n[\s\S]*?\r?\n---\s*\r?\n?/);
  return m ? content.slice(m[0].length) : content;
}

/**
 * SkillsPanel — single tab in the App-level top-nav. Shows the team's
 * skill library across two lenses and offers three write actions:
 * import / allocate / fork.
 *
 * Tab 语义：
 *   - team   ＝ 当前 team 内所有 agent 的固定资产并集（按 name 去重）；
 *              用户视角是"团队拥有的所有 skill"，数据上去掉了独立的「浮动池」概念。
 *   - fixed  ＝ 单个 agent 的固定资产（按 agent_id 隔离）。
 *
 * 写操作：
 *   - 导入  → 仅在 fixed tab 下可用，落到当前选中的 agent。
 *   - 分配  → team tab 下选中一条 skill 后可用。后端走 team_to_agent 引用，
 *            被分配的 agent 拿到的是「只读」副本（共享 SKILL.md，编辑会动到团队版）。
 *   - Fork → team tab 下选中一条 skill 后可用。前端拼装 `fetchSkillFull → importSkill`，
 *            以 `<原名>-fork-<agentId>` 落新副本，agent 拿到的是独立可写副本。
 *
 * 权限模型：
 *   - admin 用户：全部可见 + 全部可操作
 *   - skill owner：可编辑自己的 skill；可选择是否让其他人可见
 *   - 其他人：只能看到 owner 设为可见的 skill（可见 = 可复制 + 只读使用）
 *
 * Refresh strategy: poll on tab change + after every write action. No
 * setInterval — skill mutations are user-driven, the auto-refresh cost
 * is not worth it.
 *
 */
import { useTranslation } from 'react-i18next';
import { Button, Select, Segment } from 'tea-component';
import { DeleteIcon } from 'tea-icons-react';
import { tea } from '@/lib/tea-bridge';
import { AssetPageHeader } from '@/components/asset/AssetPageHeader';
import { AssetSplitLayout } from '@/components/asset/AssetSplitLayout';
import {
  AssetListPanel,
  AssetItemHeader,
  AssetItemName,
  AssetItemId,
  AssetItemBadges,
  AssetItemTime,
} from '@/components/asset/AssetListPanel';
import { UserBadge } from '@/components/asset/UserBadge';
import SkillDetailPane from './SkillDetailPane';
import ImportSkillDialog from './ImportSkillDialog';
import ForkSkillDialog from './ForkSkillDialog';
import { TAB_I18N_KEY, useSkillsPanel, type Tab } from '../hooks/useSkillsPanel';
import '../styles/skills-list.css';

export default function SkillsPanel({
  currentUser: _currentUser,
  isAdmin: _isAdmin,
}: {
  currentUser: string;
  isAdmin: boolean;
}) {
  const { t } = useTranslation();
  const store = useSkillsPanel();

  const {
    // context
    activeTeam,
    activeTeamId,
    myUserId,
    teamAgents,
    agentNameMap,
    // state
    tab,
    setTab,
    selectedAgent,
    setSelectedAgent,
    loading,
    selectedSkillId,
    setSelectedSkillId,
    showImport,
    setShowImport,
    showFork,
    setShowFork,
    deleteLoading,
    exportLoading,
    visibilityMap,
    skills,
    // cache
    skillsWithCache,
    // handlers
    refresh,
    handleDelete,
    handleExport,
    handleToggleVisibility,
    selectedSkill,
  } = store;

  return (
    <div className="_memory-skills-body">
      {/* 固定资产的 Agent 选择器与 Code 页 "Agent 资产" 选项栏保持相同呈现。 */}
      <AssetPageHeader
        title={t('skills.title')}
        subtitle={
          activeTeam
            ? t('skills.subtitle.team', { name: activeTeam.name, count: skills.length })
            : t('skills.subtitle.global', { count: skills.length })
        }
        scope={
          <Segment
            value={tab}
            onChange={(v) => setTab(v as Tab)}
            options={(['team', 'fixed'] as Tab[]).map((t2) => ({
              value: t2,
              text: t(TAB_I18N_KEY[t2]),
            }))}
          />
        }
        agent={
          tab === 'fixed' ? (
            <Select
              appearance="button"
              matchButtonWidth
              value={selectedAgent}
              onChange={(value) => {
                setSelectedAgent(value);
                setSelectedSkillId(null);
              }}
              disabled={teamAgents.length === 0}
              placeholder={t('skills.noAgent')}
              options={teamAgents.map((agent) => ({
                value: agent.id,
                text: `${agent.name}（${agent.id}）`,
              }))}
            />
          ) : undefined
        }
        actions={
          <>
            {(() => {
              const canFork = tab === 'team' && !!selectedSkillId;
              const tooltip =
                tab === 'fixed'
                  ? t('skills.fork.tooltip.fixed')
                  : !selectedSkillId
                    ? t('skills.fork.tooltip.team.empty')
                    : undefined;
              return tab === 'fixed' ? null : (
                <Button onClick={() => setShowFork(true)} disabled={!canFork} tooltip={tooltip}>
                  {t('skills.fork')}
                </Button>
              );
            })()}
            {(() => {
              const canExport = !!selectedSkillId;
              const exportTooltip = !selectedSkillId ? t('skills.export.tooltip.empty') : undefined;
              return (
                <Button
                  onClick={handleExport}
                  disabled={!canExport}
                  tooltip={exportTooltip}
                  loading={exportLoading}
                >
                  {t('skills.export')}
                </Button>
              );
            })()}
            <Button
              type="primary"
              onClick={() => setShowImport(true)}
              disabled={teamAgents.length === 0}
              tooltip={teamAgents.length === 0 ? t('skills.import.tooltip.noAgent') : undefined}
              data-guide="import-skill"
            >
              {t('skills.import')}
            </Button>
          </>
        }
      />

      {/* === 团队资产 / 固定资产 Tab === */}
      <AssetSplitLayout
        storageKey="skills:assetSplitWidth"
        sidebar={
          <AssetListPanel
            title={
              <>
                {t(TAB_I18N_KEY[tab])}
                {tab === 'fixed' && selectedAgent && (
                  <span className="_alp-title-suffix">
                    {' '}
                    · {agentNameMap[selectedAgent] ?? selectedAgent}
                  </span>
                )}
              </>
            }
            count={t('skills.count', { count: skillsWithCache.length })}
            loading={loading}
            items={skillsWithCache}
            selectedId={selectedSkillId}
            getItemId={(s) => s.skill_id}
            onSelect={(s) => setSelectedSkillId(s.skill_id)}
            emptyText={
              tab === 'fixed' && !selectedAgent
                ? t('skills.empty.fixed.noAgent')
                : tab === 'fixed'
                  ? t('skills.empty.fixed.hasAgent', { agent: selectedAgent })
                  : t('skills.empty.team')
            }
            renderItem={(s) => {
              const ownerIsMe = !!myUserId && s.owner_user_id === myUserId;
              const canManage = ownerIsMe;
              const vis = visibilityMap[s.skill_id];
              return (
                <>
                  <AssetItemHeader>
                    <AssetItemName title={s.name}>{s.name}</AssetItemName>
                    {canManage && (
                      <Button
                        type="text"
                        tooltip={ownerIsMe ? t('skills.delete.own') : t('skills.delete.admin')}
                        className="_memory-skill-item-delete"
                        onClick={async (e: any) => {
                          e?.stopPropagation();
                          const ok = await tea.confirm({
                            message: t('skills.delete.confirm', { name: s.name }),
                            description: t('skills.delete.confirm.desc'),
                            okText: t('skills.delete.okText'),
                            cancelText: t('skills.delete.cancelText'),
                          });
                          if (ok) {
                            void handleDelete(s);
                          }
                        }}
                        disabled={deleteLoading}
                      >
                        <DeleteIcon size={14} />
                      </Button>
                    )}
                  </AssetItemHeader>

                  {/* 第 2 行：资产真实 id，等宽灰色（与 ChatMemory 页同构） */}
                  <AssetItemId>{s.skill_id}</AssetItemId>

                  <AssetItemBadges>
                    {s.owner_user_id && (
                      <UserBadge
                        userId={s.owner_user_id}
                        isCurrentUser={ownerIsMe}
                        youText={t('skills.ownerTag.you')}
                        getTitle={(name) =>
                          t('skills.ownerTag.title', { name, id: s.owner_user_id })
                        }
                      />
                    )}
                    <AssetItemTime>{new Date(s.updated_at_ms).toLocaleString()}</AssetItemTime>
                  </AssetItemBadges>

                  {/* 共享/私密切换：原「个人资产」tab 的能力，迁到「Agent 资产」tab，
                      仅 owner 可切；owner 视角 getAssets 已关闭 visibility 过滤，
                      private skill 也能拿到 vis。即便 vis 偶发缺失也按 private 兜底渲染，
                      避免 skill 被切成 private 后切换按钮消失、无法再切回 team。 */}
                  {tab === 'fixed' && ownerIsMe && (
                    <div style={{ marginTop: 6 }} onClick={(e) => e.stopPropagation()}>
                      <Segment
                        value={vis === 'team' ? 'team' : 'private'}
                        onChange={(v) => handleToggleVisibility(s, v as 'team' | 'private')}
                        options={[
                          { value: 'team', text: t('skills.personal.scope.shared') },
                          { value: 'private', text: t('skills.personal.scope.private') },
                        ]}
                      />
                    </div>
                  )}
                </>
              );
            }}
          />
        }
        detail={
          <SkillDetailPane
            skillName={selectedSkill?.name ?? null}
            // 传原始 selectedSkillId（独立 state）而非 selectedSkill?.skill_id（列表派生）：
            // 选中即有值，不受 agent/skill 列表加载或刷新时序影响，避免详情面板先闪空态再变加载态。
            skillId={selectedSkillId ?? undefined}
            teamId={activeTeamId ?? undefined}
            userId={myUserId}
            // 编辑权限与删除一致：仅 skill 的 owner（owner_user_id === 当前用户）可编辑
            canEdit={!!myUserId && selectedSkill?.owner_user_id === myUserId}
            onChanged={() => void refresh()}
          />
        }
      />

      {/* Modals (only for team/fixed tabs) */}
      {showImport && (
        // 导入弹窗在 team / fixed 两个 tab 都能打开。
        // target 始终是 fixed —— 所有 skill 都归属于某个具体 agent。
        // agentId 仅在 fixed tab 下作为默认归属带入；team tab 下传 undefined，
        // 由弹窗内的「归属 Agent（必选）」下拉自行兜底选第一个。
        <ImportSkillDialog
          target="fixed"
          teamId={activeTeamId ?? ''}
          userId={myUserId}
          agents={teamAgents}
          agentId={tab === 'fixed' ? selectedAgent : undefined}
          onClose={() => setShowImport(false)}
          onImported={() => {
            // skill 建成功后，内核数据面 onSkillCreated 钩子会自动登记 asset
            // + 绑定为 owner agent 的 fixed-asset（visibility 默认 private）。
            // 前端不再需要额外调 localStorage 存"我的资产"—— 数据源已经是真后端。
            setShowImport(false);
            void refresh();
          }}
        />
      )}
      {showFork &&
        (() => {
          // Fork 弹窗的 skillId/skillName 来源：selectedSkill（列表来自 asset/list-accessible）
          const source = selectedSkill
            ? { skillId: selectedSkill.skill_id, skillName: selectedSkill.name }
            : null;
          if (!source) return null;
          return (
            <ForkSkillDialog
              teamId={activeTeamId ?? ''}
              userId={myUserId}
              skillId={source.skillId}
              skillName={source.skillName}
              agents={teamAgents}
              onClose={() => setShowFork(false)}
              onForked={() => {
                setShowFork(false);
                // fork 出的新副本以 `<原名>-fork-<agentId>` 落库，会作为新条目出现
                void refresh();
              }}
            />
          );
        })()}
    </div>
  );
}

import { useEffect, useState, useCallback, useMemo, type CSSProperties } from "react";
import { useTranslation } from "react-i18next";
import Graph from "graphology";
import { SigmaContainer, useLoadGraph, useRegisterEvents, useSigma } from "@react-sigma/core";
import "@react-sigma/core/lib/style.css";
import forceAtlas2 from "graphology-layout-forceatlas2";
import { SearchIcon, CloseIcon } from 'tea-icons-react';

// --- Types (re-exported from knowledge-api) ---
export interface GraphNode {
  id: string; label: string; type: string; path: string; linkCount: number; community: number;
}
export interface GraphEdge { source: string; target: string; weight: number; }
export interface GraphData {
  nodes: GraphNode[]; edges: GraphEdge[];
  communities?: { id: number; nodeCount: number; topNodes: string[] }[];
}

// Sigma 的 Canvas 绘制不能直接解析 CSS var()，因此在组件渲染时读取 Tea Token 的计算值。
// 这避免模块加载早于 Tea 主题 CSS 时取得空值，并会在主题属性变更后刷新画布调色板。
interface AtlasPalette {
  bg: string;
  toolbarBg: string;
  dim: string;
  dimFaded: string;
  edgeBase: string;
  edgeHover: string;
  label: string;
  nodeColors: Record<string, string>;
  communityColors: string[];
}

function readTeaColor(token: string): string {
  return getComputedStyle(document.documentElement).getPropertyValue(token).trim();
}

function createAtlasPalette(): AtlasPalette {
  const dim = readTeaColor('--tea-color-bg-tertiary-default');
  const accents = [
    readTeaColor('--tea-color-bg-brand-default'),
    readTeaColor('--tea-color-bg-warning-default'),
    readTeaColor('--tea-color-bg-amber-default'),
    readTeaColor('--tea-color-bg-error-default'),
  ];
  const nodeColors: Record<string, string> = {
    entity: accents[0],
    concept: accents[1],
    source: accents[2],
    query: dim,
    synthesis: accents[3],
    overview: accents[2],
    comparison: dim,
    finding: accents[1],
    thesis: accents[3],
    methodology: dim,
    other: dim,
  };

  return {
    bg: readTeaColor('--tea-color-bg-primary-default'),
    toolbarBg: readTeaColor('--tea-color-bg-secondary-default'),
    dim,
    dimFaded: readTeaColor('--tea-color-bg-secondary-default'),
    edgeBase: readTeaColor('--tea-color-border-secondary-default'),
    edgeHover: readTeaColor('--tea-color-border-brand-default'),
    label: readTeaColor('--tea-color-text-primary'),
    nodeColors,
    communityColors: [
      accents[0], dim, accents[1], dim, accents[2], dim,
      accents[3], dim, accents[0], dim, accents[1], dim,
    ],
  };
}

type ColorMode = "type" | "community";

// --- Structural node filter ---
const STRUCTURAL_IDS = new Set(["index", "overview", "log", "schema", "purpose"]);
function isStructuralNode(node: GraphNode): boolean {
  const id = node.id.toLowerCase();
  if (STRUCTURAL_IDS.has(id)) return true;
  if (node.type === "overview") return true;
  const p = node.path.replace(/\\/g, "/").toLowerCase();
  return p.endsWith("/wiki/index.md") || p.endsWith("/wiki/overview.md") || p.endsWith("/wiki/log.md") || p.endsWith("/purpose.md") || p.endsWith("/schema.md");
}
function filterStructuralNodes(data: GraphData): GraphData {
  const hidden = new Set<string>();
  for (const n of data.nodes) if (isStructuralNode(n)) hidden.add(n.id);
  if (hidden.size === 0) return data;
  return { nodes: data.nodes.filter((n) => !hidden.has(n.id)), edges: data.edges.filter((e) => !hidden.has(e.source) && !hidden.has(e.target)), communities: data.communities };
}

// --- Helpers ---
const BASE_NODE_SIZE = 7;
const MAX_NODE_SIZE = 26;
function nc(type: string, palette: AtlasPalette): string { return palette.nodeColors[type] || palette.nodeColors.other; }
function ns(linkCount: number, maxLinks: number, nodeCount: number): number {
  if (maxLinks === 0) return BASE_NODE_SIZE;
  const r = linkCount / maxLinks;
  const s = nodeCount > 150 ? Math.sqrt(150 / nodeCount) : 1;
  return (BASE_NODE_SIZE + Math.pow(r, 0.6) * (MAX_NODE_SIZE - BASE_NODE_SIZE)) * s;
}
function layoutIter(n: number): number { return n > 2500 ? 28 : n > 1200 ? 40 : n > 600 ? 65 : n > 250 ? 90 : 140; }

// --- Graph Loader ---
function GraphLoader({ nodes, edges, colorMode, onNodeClick, highlightNode, palette }: {
  nodes: GraphNode[]; edges: GraphEdge[]; colorMode: ColorMode;
  onNodeClick?: (n: GraphNode) => void; highlightNode?: string | null; palette: AtlasPalette;
}) {
  const loadGraph = useLoadGraph();
  const sigma = useSigma();
  const registerEvents = useRegisterEvents();
  const [hovered, setHovered] = useState<{ node: string; neighbors: Set<string> } | null>(null);

  useEffect(() => {
    const graph = new Graph();
    const maxLinks = Math.max(...nodes.map((n) => n.linkCount), 1);
    for (const node of nodes) {
      const color = colorMode === "community"
        ? palette.communityColors[node.community % palette.communityColors.length]
        : nc(node.type, palette);
      graph.addNode(node.id, { x: Math.random() * 100, y: Math.random() * 100, size: ns(node.linkCount, maxLinks, nodes.length), color, label: node.label });
    }
    const maxW = Math.max(...edges.map((e) => e.weight), 1);
    for (const edge of edges) {
      if (graph.hasNode(edge.source) && graph.hasNode(edge.target)) {
        const key = `${edge.source}->${edge.target}`;
        if (!graph.hasEdge(key) && !graph.hasEdge(`${edge.target}->${edge.source}`)) {
          const nw = edge.weight / maxW;
          // 连接线颜色走 Tea 次级边框 Token，权重仅影响线宽。
          graph.addEdgeWithKey(key, edge.source, edge.target, { size: 0.5 + nw * 1.4, color: palette.edgeBase });
        }
      }
    }
    const settings = forceAtlas2.inferSettings(graph);
    forceAtlas2.assign(graph, { iterations: layoutIter(nodes.length), settings: { ...settings, gravity: 1.2, scalingRatio: nodes.length > 400 ? 3.5 : 2.5, strongGravityMode: true, barnesHutOptimize: nodes.length > 50 } });
    loadGraph(graph);
    sigma.refresh();
  }, [nodes, edges, colorMode, loadGraph, palette, sigma]);

  useEffect(() => {
    registerEvents({
      enterNode: (e) => { const g = sigma.getGraph(); setHovered({ node: e.node, neighbors: new Set(g.neighbors(e.node)) }); const c = sigma.getContainer(); if (c) c.style.cursor = "pointer"; },
      leaveNode: () => { setHovered(null); const c = sigma.getContainer(); if (c) c.style.cursor = "default"; },
      clickNode: (e) => { const n = nodes.find((n) => n.id === e.node); if (n && onNodeClick) onNodeClick(n); },
    });
  }, [registerEvents, sigma, nodes, onNodeClick]);

  useEffect(() => {
    sigma.setSetting("nodeReducer", (node, data) => {
      const res = { ...data };
      if (highlightNode && node === highlightNode) { res.highlighted = true; res.zIndex = 2; }
      if (hovered) {
        if (node === hovered.node) { res.highlighted = true; res.zIndex = 2; res.size = (data.size || BASE_NODE_SIZE) * 1.3; }
        else if (hovered.neighbors.has(node)) { res.zIndex = 1; }
        else { res.color = palette.dimFaded; res.label = ""; res.zIndex = 0; }
      }
      return res;
    });
    sigma.setSetting("edgeReducer", (edge, data) => {
      const res = { ...data };
      if (hovered) {
        const g = sigma.getGraph();
        if (g.source(edge) !== hovered.node && g.target(edge) !== hovered.node) { res.hidden = true; }
        else { res.color = palette.edgeHover; res.size = Math.max((data.size || 1) * 1.8, 2); }
      }
      return res;
    });
    sigma.refresh();
  }, [hovered, highlightNode, palette, sigma]);

  return null;
}

// --- Controls ---
function GraphControls() {
  const sigma = useSigma();
  const cls = "h-7 w-7 bg-card/90 hover:bg-card border border-border text-muted-foreground shadow-md rounded-md flex items-center justify-center transition-colors text-[12px] backdrop-blur";
  return (
    <div className="absolute bottom-3 right-3 flex flex-col gap-1 z-10">
      <button type="button" aria-label="Zoom in" className={cls} onClick={() => sigma.getCamera().animatedZoom({ duration: 200 })}>+</button>
      <button type="button" aria-label="Zoom out" className={cls} onClick={() => sigma.getCamera().animatedUnzoom({ duration: 200 })}>−</button>
      <button type="button" aria-label="Reset view" className={cls} onClick={() => sigma.getCamera().animatedReset({ duration: 300 })}>⊙</button>
    </div>
  );
}

// --- Main Component ---
interface Props {
  data: GraphData | null; loading?: boolean;
  onNodeClick?: (node: GraphNode) => void; highlightNode?: string | null; className?: string;
}

export default function KnowledgeGraph({ data, loading, onNodeClick, highlightNode, className }: Props) {
  const { t } = useTranslation();
  const [colorMode, setColorMode] = useState<ColorMode>("type");
  const [hideStructural, setHideStructural] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<GraphNode[]>([]);
  const [themeRevision, setThemeRevision] = useState(0);

  useEffect(() => {
    const observer = new MutationObserver(() => setThemeRevision((revision) => revision + 1));
    observer.observe(document.body, { attributes: true, attributeFilter: ['class', 'theme-mode'] });
    return () => observer.disconnect();
  }, []);

  const palette = useMemo(() => createAtlasPalette(), [themeRevision]);
  const filteredData = useMemo(() => data ? (hideStructural ? filterStructuralNodes(data) : data) : null, [data, hideStructural]);

  const handleSearch = useCallback((q: string) => {
    setSearchQuery(q);
    if (!q.trim() || !filteredData) { setSearchResults([]); return; }
    const lower = q.toLowerCase();
    setSearchResults(filteredData.nodes.filter((n) => n.label.toLowerCase().includes(lower) || n.id.toLowerCase().includes(lower)).slice(0, 8));
  }, [filteredData]);

  if (loading) return <div className={`flex items-center justify-center ${className}`} style={{ background: palette.bg }}><span className="text-xs text-muted-foreground">{t('graph.loading')}</span></div>;
  if (!filteredData || filteredData.nodes.length === 0) return <div className={`flex items-center justify-center ${className}`} style={{ background: palette.bg }}><span className="text-[12px] text-muted-foreground/70">{t('graph.empty')}</span></div>;

  const typeSet = new Set(filteredData.nodes.map((n) => n.type));
  const types = [...typeSet].sort();

  // 极细网格背景 + 白底，营造"高科技画布"感（CSS grid pattern）
  const gridBg: CSSProperties = {
    background: palette.bg,
    backgroundImage:
      'linear-gradient(var(--tea-color-border-secondary-default) 1px, transparent 1px), linear-gradient(90deg, var(--tea-color-border-secondary-default) 1px, transparent 1px)',
    backgroundSize: '32px 32px'
  };

  return (
    <div className={`relative flex flex-col overflow-hidden ${className}`} style={{ background: palette.bg }}>
      {/* Toolbar */}
      <div className="flex items-center gap-2 border-b border-border px-3 py-2 z-10" style={{ background: palette.toolbarBg, backdropFilter: 'blur(8px)' }}>
        <div className="relative flex-1 max-w-[180px]">
          <span className="absolute left-2 top-1/2 -translate-y-1/2 text-muted-foreground/70 text-xs inline-flex items-center"><SearchIcon size={12} /></span>
          <input
            className="h-7 w-full pl-7 pr-6 text-xs border rounded-md bg-card/80 border-border text-foreground/70 placeholder:text-muted-foreground/70 focus:outline-none focus:ring-1 focus:ring-primary"
            placeholder={t('graph.searchPlaceholder')}
            value={searchQuery}
            onChange={(e) => handleSearch(e.target.value)}
          />
          {searchQuery && (
            <button type="button" aria-label={t('graph.clearSearch')} className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground/70 hover:text-muted-foreground text-xs inline-flex items-center" onClick={() => { setSearchQuery(""); setSearchResults([]); }}><CloseIcon size={12} /></button>
          )}
        </div>
        <div className="flex gap-0.5">
          <button className={`rounded-md px-2 py-1 text-xs font-medium transition ${colorMode === "type" ? "bg-primary/5 text-primary ring-1 ring-primary/30" : "text-muted-foreground hover:text-foreground/70 hover:bg-muted"}`} onClick={() => setColorMode("type")}>{t('graph.colorMode.type')}</button>
          <button className={`rounded-md px-2 py-1 text-xs font-medium transition ${colorMode === "community" ? "bg-primary/5 text-primary ring-1 ring-primary/30" : "text-muted-foreground hover:text-foreground/70 hover:bg-muted"}`} onClick={() => setColorMode("community")}>{t('graph.colorMode.community')}</button>
        </div>
        <button className={`rounded-md px-2 py-1 text-xs font-medium transition ${hideStructural ? "bg-success/10 text-success ring-1 ring-success/30" : "text-muted-foreground hover:text-foreground/70 hover:bg-muted"}`}
          onClick={() => setHideStructural(!hideStructural)} title={t('graph.hideStructural.title')}>{t('graph.hideStructural')}</button>
        <span className="text-xs ml-auto font-mono text-muted-foreground">{t('graph.stats', { nodes: filteredData.nodes.length, edges: filteredData.edges.length })}</span>
      </div>

      {/* Search results dropdown */}
      {searchResults.length > 0 && searchQuery && (
        <div className="absolute top-12 left-3 z-20 w-[190px] rounded-lg border shadow-xl p-1 max-h-[200px] overflow-auto bg-card/95 border-border backdrop-blur">
          {searchResults.map((n) => (
            <div key={n.id} className="flex items-center gap-1.5 rounded-md px-2 py-1 text-xs cursor-pointer hover:bg-muted"
              onClick={() => { onNodeClick?.(n); setSearchQuery(""); setSearchResults([]); }}>
              <div className="h-2 w-2 rounded-full shrink-0" style={{ background: nc(n.type, palette) }} />
              <span className="truncate text-foreground/70">{n.label}</span>
            </div>
          ))}
        </div>
      )}

      {/* Sigma Canvas */}
      <div className="flex-1 min-h-0 relative" style={gridBg}>
        <SigmaContainer
          style={{ width: "100%", height: "100%", background: "transparent" }}
          settings={{
            allowInvalidContainer: true, renderLabels: true,
            labelFont: "system-ui, -apple-system, sans-serif", labelSize: 12, labelWeight: "500",
            labelDensity: (data?.nodes?.length || 0) > 600 ? 0.12 : 0.35, labelGridCellSize: 90,
            labelRenderedSizeThreshold: (data?.nodes?.length || 0) > 600 ? 12 : 7,
            defaultEdgeType: "line", defaultNodeColor: palette.dim,
            defaultEdgeColor: palette.edgeBase,
            labelColor: { color: palette.label }, stagePadding: 40, zIndex: true,
            minCameraRatio: 0.06, maxCameraRatio: 4,
          }}
        >
          <GraphLoader nodes={filteredData.nodes} edges={filteredData.edges} colorMode={colorMode} onNodeClick={onNodeClick} highlightNode={highlightNode} palette={palette} />
          <GraphControls />
        </SigmaContainer>
      </div>

      {/* Legend */}
      <div className="flex flex-wrap items-center gap-3 border-t border-border px-3 py-1.5 z-10" style={{ background: palette.toolbarBg, backdropFilter: 'blur(8px)' }}>
        {types.map((type) => {
          const c = colorMode === "type" ? nc(type, palette) : palette.dim;
          const isAccent = c !== palette.dim;
          return (
            <div key={type} className="flex items-center gap-1.5">
              <div className="h-2.5 w-2.5 rounded-full" style={{ background: c, boxShadow: isAccent ? 'var(--tea-shadow-xs)' : 'none' }} />
              <span className="text-xs text-muted-foreground">{type}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/**
 * WikiSourcesPanel —— Wiki 资产页主面板（列表视图 + 详情/创建/分配组装）。
 * 列表视图渲染与组件组装；状态/数据逻辑在 useWikiSources，详情在 WikiDetailView，
 * 展示小组件 / 常量工具 / 共享 Markdown 分别独立收口。
 */
import { useTranslation } from 'react-i18next';
import { Button, Card, Form, Input, Justify, MetricsBoard, Modal, SearchBox, Segment, Select, StatusTip, Table, Text } from 'tea-component';
import { BooksIcon, ChevronRightIcon, UsergroupIcon, ViewListIcon, ViewModuleIcon } from 'tea-icons-react';
import { knowledgeApi } from '@/lib/api/knowledge-api';
import { tea } from '@/lib/tea-bridge';
import AllocateAssetDialog from '@/components/asset/AllocateAssetDialog';
import { AssetPageHeader } from '@/components/asset/AssetPageHeader';
import { formatShortTime, SCOPE_LABEL_KEYS, type StatusFilter, type ViewMode, type WikiScopeTab } from '../constants/wiki-constants';
import { WikiOwnerLabel, WikiStatusBadge } from './wiki-ui';
import { WikiActions } from './wiki-detail-components';
import { useWikiSources } from '../hooks/useWikiSources';
import { WikiDetailView } from './wiki-detail-view';
import '@/components/asset/asset-card.css';
import '../styles/wiki-sources-panel.css';

const { scrollable } = Table.addons;

export default function WikiSourcesPanel() {
  const { t } = useTranslation();
  const wiki = useWikiSources();

  const {
    // context
    activeTeam,
    activeTeamId,
    currentUser,
    teamAgents,
    // list view
    sources,
    loading,
    scopeTab,
    setScopeTab,
    keyword,
    setKeyword,
    statusFilter,
    setStatusFilter,
    viewMode,
    setViewMode,
    subView,
    // create
    showCreate,
    setShowCreate,
    newName,
    setNewName,
    submitting,
    // allocate
    allocateTarget,
    setAllocateTarget,
    agentFilter,
    setAgentFilter,
    // fetch & handlers
    fetchSources,
    fetchFixedBindings,
    handleIngest,
    handleDelete,
    openDetail,
    handleUnbindWiki,
    handleCreate,
    // computed
    stats,
    filteredSources,
    runningWikiIds,
    ingestBusy,
  } = wiki;

  if (subView === 'detail') {
    return <WikiDetailView store={wiki} />;
  }

  return (
    <div className="_asset-wiki-page">
      <AssetPageHeader
        title={t('wiki.title')}
        subtitle={
          <Text theme="label">
            {activeTeam
              ? t('wiki.subtitle.team', { name: activeTeam.name, count: stats.total })
              : t('wiki.subtitle.global', { count: stats.total })}
          </Text>
        }
        scope={
          <Segment
            value={scopeTab}
            onChange={(value) => setScopeTab(value as WikiScopeTab)}
            options={(['team', 'fixed'] as WikiScopeTab[]).map((tab) => ({
              value: tab,
              text: t(SCOPE_LABEL_KEYS[tab]),
            }))}
          />
        }
        agent={
          scopeTab === 'fixed' ? (
            <Select
              appearance="button"
              matchButtonWidth
              value={agentFilter}
              onChange={setAgentFilter}
              disabled={teamAgents.length === 0}
              placeholder={t('wiki.noAgentPlaceholder')}
              options={teamAgents.map((agent) => ({
                value: agent.id,
                text: `${agent.name}（${agent.id}）`,
              }))}
            />
          ) : undefined
        }
        actions={
          // 创建（新增团队池资产）与 memory/skill 对齐，放右上角 header；
          // 仅「团队资产」tab 开放，固定资产 tab 只做绑定/查看。
          scopeTab !== 'fixed' ? (
            <Button type="primary" onClick={() => setShowCreate(true)} data-guide="create-wiki">
              {t('wiki.create')}
            </Button>
          ) : undefined
        }
      />

      <Card className="_asset-wiki-content-card">
        <Card.Body>
          <div className="_asset-wiki-stats">
            <MetricsBoard title={t('wiki.metrics.total')} value={stats.total} />
            <MetricsBoard title={t('wiki.metrics.ready')} value={stats.ready} />
            <MetricsBoard title={t('wiki.metrics.processing')} value={stats.processing} />
            <MetricsBoard title={t('wiki.metrics.totalPages')} value={stats.totalPages} />
          </div>
          <Table.ActionPanel>
            <Justify
              right={
                <div className="_asset-wiki-toolbar">
                  <SearchBox
                    value={keyword}
                    onChange={setKeyword}
                    placeholder={t('wiki.searchPlaceholder')}
                  />
                  <Segment
                    value={statusFilter}
                    onChange={(value) => setStatusFilter(value as StatusFilter)}
                    options={[
                      { value: 'all', text: t('wiki.filter.allStatus') },
                      { value: 'ready', text: t('wiki.filter.ready') },
                      { value: 'processing', text: t('wiki.filter.processing') },
                    ]}
                  />
                  <Segment
                    value={viewMode}
                    onChange={(value) => setViewMode(value as ViewMode)}
                    options={[
                      { value: 'card', text: <ViewModuleIcon /> },
                      { value: 'list', text: <ViewListIcon /> },
                    ]}
                  />
                </div>
              }
            />
          </Table.ActionPanel>

          {loading ? (
            <div className="_asset-wiki-skeleton-grid">
              {Array.from({ length: 6 }).map((_, i) => (
                <div key={i} className="_asset-wiki-skeleton-card">
                  <div className="_asset-wiki-skeleton-line _asset-wiki-skeleton-line--title" />
                  <div className="_asset-wiki-skeleton-line _asset-wiki-skeleton-line--desc" />
                  <div className="_asset-wiki-skeleton-line _asset-wiki-skeleton-line--meta" />
                </div>
              ))}
            </div>
          ) : sources.length === 0 ? (
            <StatusTip
              status="empty"
              emptyText={
                <div className="_asset-wiki-empty">
                  <BooksIcon size="large" />
                  <Text>{t('wiki.empty.title')}</Text>
                  <Text theme="label">{t('wiki.empty.desc')}</Text>
                </div>
              }
            />
          ) : filteredSources.length === 0 ? (
            <StatusTip status="empty" emptyText={t('wiki.empty.filtered')} />
          ) : viewMode === 'card' ? (
            <div className="_asset-wiki-grid _view-swap">
              {filteredSources.map((source) => (
                <div
                  key={source.wiki_id}
                  className="_asset-wiki-card"
                  onClick={() => openDetail(source.wiki_id)}
                >
                  <div className="_asset-wiki-card-head">
                    <BooksIcon size={16} />
                    <span className="_asset-wiki-card-name" title={source.name}>
                      {source.name}
                    </span>
                    <ChevronRightIcon size={14} className="_asset-wiki-card-chevron" />
                  </div>
                  <div className="_asset-wiki-card-meta">
                    <WikiStatusBadge status={source.status} />
                    <span>
                      {t('wiki.card.pagesAndTime', { pages: source.page_count ?? 0, time: formatShortTime(source.last_sync_at) })}
                    </span>
                  </div>
                  <div className="_asset-wiki-card-owner">
                    <UsergroupIcon size={12} />
                    {scopeTab === 'fixed' ? (
                      t('wiki.fixedAsset', { agent: agentFilter || t('wiki.noAgent') })
                    ) : source.owner_user_id ? (
                      <WikiOwnerLabel userId={source.owner_user_id} currentUserId={currentUser} />
                    ) : (
                      t('wiki.teamPool')
                    )}
                  </div>
                  <div className="_asset-wiki-card-id">{t('wiki.card.id', { id: source.wiki_id })}</div>
                  <WikiActions
                    source={source}
                    scopeTab={scopeTab}
                    ingestBusy={ingestBusy}
                    isCurrentIngesting={runningWikiIds.has(source.wiki_id)}
                    onIngest={handleIngest}
                    onAllocate={setAllocateTarget}
                    onUnbind={handleUnbindWiki}
                    onDelete={handleDelete}
                  />
                </div>
              ))}
            </div>
          ) : (
            <div className="_view-swap">
            <Table
              records={filteredSources}
              recordKey="wiki_id"
              addons={[scrollable({ minWidth: 1040 })]}
              columns={[
                {
                  key: 'name',
                  header: t('wiki.table.name'),
                  width: 240,
                  render: (source) => (
                    <button
                      type="button"
                      className="_asset-wiki-row-name"
                      onClick={() => openDetail(source.wiki_id)}
                    >
                      <BooksIcon size={14} />
                      <span>{source.name}</span>
                      <ChevronRightIcon size={12} />
                    </button>
                  ),
                },
                {
                  key: 'status',
                  header: t('wiki.table.status'),
                  width: 100,
                  render: (source) => <WikiStatusBadge status={source.status} />,
                },
                {
                  key: 'page_count',
                  header: t('wiki.table.pageCount'),
                  width: 80,
                  render: (source) => source.page_count ?? 0,
                },
                {
                  key: 'owner',
                  header: t('wiki.table.owner'),
                  width: 180,
                  render: (source) =>
                    scopeTab === 'fixed' ? (
                      <span className="_asset-wiki-inline-icon">
                        <UsergroupIcon size={12} />
                        {agentFilter || t('wiki.noAgent')}
                      </span>
                    ) : source.owner_user_id ? (
                      <WikiOwnerLabel userId={source.owner_user_id} currentUserId={currentUser} />
                    ) : (
                      <Text theme="label">{t('wiki.teamPool.short')}</Text>
                    ),
                },
                {
                  key: 'last_sync_at',
                  header: t('wiki.table.lastSync'),
                  width: 140,
                  render: (source) => (
                    <Text theme="label">{formatShortTime(source.last_sync_at)}</Text>
                  ),
                },
                {
                  key: 'wiki_id',
                  header: t('wiki.table.wikiId'),
                  width: 220,
                  render: (source) => <span className="_asset-wiki-id">{source.wiki_id}</span>,
                },
                {
                  key: 'actions',
                  header: t('wiki.table.actions'),
                  width: 240,
                  fixed: 'right',
                  render: (source) => (
                    <WikiActions
                      source={source}
                      scopeTab={scopeTab}
                      ingestBusy={ingestBusy}
                      isCurrentIngesting={runningWikiIds.has(source.wiki_id)}
                      onIngest={handleIngest}
                      onAllocate={setAllocateTarget}
                      onUnbind={handleUnbindWiki}
                      onDelete={handleDelete}
                    />
                  ),
                },
              ]}
            />
            </div>
          )}
        </Card.Body>
      </Card>

      {/* Create Modal */}
      {showCreate && (
        <Modal
          visible
          caption={t('wiki.create.caption')}
          size="s"
          onClose={() => setShowCreate(false)}
          disableEscape={submitting}
        >
          <Modal.Body>
            <Form>
              <Form.Item label={t('wiki.create.name')} required extra={t('wiki.create.extra')}>
                <Input
                  size="full"
                  value={newName}
                  onChange={setNewName}
                  placeholder={t('wiki.create.placeholder')}
                />
              </Form.Item>
            </Form>
          </Modal.Body>
          <Modal.Footer>
            <Button
              type="primary"
              onClick={handleCreate}
              disabled={submitting || !newName.trim()}
              loading={submitting}
            >
              {submitting ? t('wiki.create.submitting') : t('wiki.create.submit')}
            </Button>
            <Button onClick={() => setShowCreate(false)} disabled={submitting}>
              {t('common.cancel')}
            </Button>
          </Modal.Footer>
        </Modal>
      )}

      {/* Allocate Wiki → Agent (固定资产) */}
      {allocateTarget && (
        <AllocateAssetDialog
          assetType="llm_wiki"
          assetLabel={allocateTarget.name}
          agents={teamAgents}
          team={activeTeam ? { team_id: activeTeam.team_id, name: activeTeam.name } : null}
          onClose={() => setAllocateTarget(null)}
          onAllocate={async (agentId) => {
            if (!activeTeamId) throw new Error(t('wiki.error.selectTeam'));
            await knowledgeApi.wiki.allocate(activeTeamId, allocateTarget.wiki_id, agentId);
            tea.notify.success(t('wiki.notify.allocated'));
            await fetchSources();
            if (scopeTab === 'fixed') await fetchFixedBindings();
          }}
        />
      )}
    </div>
  );
}

/**
 * wiki-detail-components —— Wiki 详情页的展示子组件。
 * 从 WikiSourcesPanel.tsx 尾部拆出（WikiActions / ResizeHandle /
 * GraphTabContent / PagesTabContent / RawFilesSection）。
 * 均为纯展示组件，数据与回调由外层注入，不含业务状态。
 */
import { useCallback, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Button, Card, StatusTip, Tag, Text } from 'tea-component';
import {
  BooksIcon,
  ChevronRightIcon,
  CloseIcon,
  DeleteIcon,
  FileIcon,
  FolderIcon,
  LayersIcon as ArchitectureIcon,
  StarIcon,
} from 'tea-icons-react';
import { knowledgeApi, type GraphData, type GraphNode, type WikiDetail, type WikiPage } from '@/lib/api/knowledge-api';
import { useResizable } from '@/lib/useResizable';
import { tea } from '@/lib/tea-bridge';
import { AssetMarkdown } from '@/components/asset/AssetMarkdown';
import { TYPE_COLORS, TYPE_COLOR_FALLBACK, type WikiScopeTab } from '../constants/wiki-constants';
import { KnowledgeGraphEmbed } from './wiki-ui';

export function WikiActions({
  source,
  scopeTab,
  ingestBusy,
  isCurrentIngesting,
  onIngest,
  onAllocate,
  onUnbind,
  onDelete,
}: {
  source: WikiDetail;
  scopeTab: WikiScopeTab;
  ingestBusy: boolean;
  /** 当前这条 wiki 自身是否处于 ingest（pending / processing）状态 */
  isCurrentIngesting: boolean;
  onIngest: (wikiId: string) => void;
  onAllocate: (target: { wiki_id: string; name: string }) => void;
  onUnbind: (wikiId: string) => void;
  onDelete: (wikiId: string, name: string) => void;
}) {
  const { t } = useTranslation();
  return (
    <div className="_asset-wiki-actions" onClick={(event) => event.stopPropagation()}>
      <Button type="weak" disabled={ingestBusy} onClick={() => onIngest(source.wiki_id)}>
        <StarIcon size={14} /> {isCurrentIngesting ? t('wiki.action.ingestBusy') : ingestBusy ? t('wiki.action.queuing') : t('wiki.action.ingest')}
      </Button>
      {scopeTab === 'fixed' ? (
        <Button type="weak" onClick={() => onUnbind(source.wiki_id)}>
          {t('wiki.action.unbind')}
        </Button>
      ) : (
        <Button
          type="weak"
          disabled={source.status !== 'ready'}
          tooltip={
            source.status === 'ready'
              ? undefined
              : t('wiki.action.allocate.disabled')
          }
          onClick={() => onAllocate({ wiki_id: source.wiki_id, name: source.name })}
        >
          {t('wiki.action.allocate')}
        </Button>
      )}
      <Button
        type="icon"
        tooltip={t('wiki.action.delete')}
        onClick={() => onDelete(source.wiki_id, source.name)}
      >
        <DeleteIcon size={14} />
      </Button>
    </div>
  );
}

// ═══════════════════════════════════════════
// Resize Handle
// ═══════════════════════════════════════════
function ResizeHandle({ onMouseDown }: { onMouseDown: (e: React.MouseEvent) => void }) {
  return <div className="_wiki-detail-resize-handle" onMouseDown={onMouseDown} />;
}

// ═══════════════════════════════════════════
// Graph Tab (with resizable right panel)
// ═══════════════════════════════════════════
export function GraphTabContent({
  graphData,
  graphLoading,
  selectedPage,
  readLoading,
  displayContent,
  metadata,
  onNodeClick,
  onClearSelection,
}: {
  graphData: GraphData | null;
  graphLoading: boolean;
  selectedPage: WikiPage | null;
  readLoading: boolean;
  displayContent: string;
  metadata: Record<string, string> | null;
  onNodeClick: (node: GraphNode) => void;
  onClearSelection: () => void;
}) {
  const { t } = useTranslation();
  const { width: rightW, onMouseDown } = useResizable(320, 200, 500, 'right');

  return (
    <div
      className="_wiki-detail-split"
      style={{ height: 'calc(100vh - 280px)', minHeight: '400px' }}
    >
      <div className="_wiki-detail-split-main">
        <KnowledgeGraphEmbed
          data={graphData}
          loading={graphLoading}
          onNodeClick={onNodeClick}
          highlightNode={selectedPage ? (selectedPage as any).id || selectedPage.path : null}
        />
      </div>
      <ResizeHandle onMouseDown={onMouseDown} />
      <div className="_wiki-detail-split-side" style={{ width: rightW }}>
        {selectedPage ? (
          <>
            <div className="_wiki-detail-side-head">
              <Text className="_wiki-detail-side-title">{selectedPage.title}</Text>
              <Button type="text" onClick={onClearSelection}>
                <CloseIcon size={14} />
              </Button>
            </div>
            {metadata && (
              <div className="_wiki-detail-side-tags">
                {metadata.type && <Tag size="sm">{metadata.type}</Tag>}
                {metadata.tags &&
                  metadata.tags
                    .replaceAll('[', '')
                    .replaceAll(']', '')
                    .split(',')
                    .filter(Boolean)
                    .map((tag) => (
                      <Tag key={tag.trim()} size="sm">
                        {tag.trim()}
                      </Tag>
                    ))}
              </div>
            )}
            <div className="_wiki-detail-side-content">
              {readLoading ? (
                <StatusTip status="loading" />
              ) : (
                <AssetMarkdown content={displayContent} />
              )}
            </div>
          </>
        ) : (
          <div className="_wiki-detail-side-empty">
            <ArchitectureIcon size="large" />
            <Text theme="label">{t('wiki.detail.graph.clickToView')}</Text>
          </div>
        )}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════
// Pages Tab (with resizable left panel)
// ═══════════════════════════════════════════
export function PagesTabContent({
  pages,
  allPages,
  types,
  typeCounts,
  pageTypeFilter,
  setPageTypeFilter,
  selectedPage,
  readLoading,
  displayContent,
  metadata,
  wikiId,
  rawRefreshKey,
  onReadPage,
  onReadRaw,
  onDeletePage,
  onDeleteRaw,
}: {
  pages: WikiPage[];
  allPages: WikiPage[];
  types: string[];
  typeCounts: Record<string, number>;
  pageTypeFilter: string;
  setPageTypeFilter: (v: string) => void;
  selectedPage: WikiPage | null;
  readLoading: boolean;
  displayContent: string;
  metadata: Record<string, string> | null;
  wikiId: string;
  rawRefreshKey: number;
  onReadPage: (p: WikiPage) => void;
  onReadRaw: (filename: string) => void;
  onDeletePage: (p: WikiPage) => Promise<void> | void;
  onDeleteRaw: (filename: string) => Promise<void> | void;
}) {
  const { t } = useTranslation();
  const { width: leftW, onMouseDown } = useResizable(260, 180, 400, 'left');

  return (
    <div
      className="_wiki-detail-split"
      style={{ height: 'calc(100vh - 280px)', minHeight: '400px' }}
    >
      <div className="_wiki-detail-split-side-left" style={{ width: leftW }}>
        <div className="_wiki-detail-type-filter">
          <button
            className={`_wiki-detail-filter-tag${pageTypeFilter === 'all' ? ' is-active' : ''}`}
            onClick={() => setPageTypeFilter('all')}
          >
            {t('wiki.detail.pages.all', { count: allPages.length })}
          </button>
          {types.map((type) => (
            <button
              key={type}
              className={`_wiki-detail-filter-tag${pageTypeFilter === type ? ' is-active' : ''}`}
              onClick={() => setPageTypeFilter(type)}
            >
              <span
                className="_wiki-detail-type-dot"
                style={{ background: TYPE_COLORS[type] || TYPE_COLOR_FALLBACK }}
              />
              {type} {typeCounts[type]}
            </button>
          ))}
        </div>
        <div className="_wiki-detail-page-list">
          {pages.map((page) => {
            const active =
              selectedPage &&
              ((selectedPage as any).id || selectedPage.path) === ((page as any).id || page.path);
            return (
              <div
                key={(page as any).id || page.path}
                className={`_wiki-detail-page-row${active ? ' is-active' : ''}`}
              >
                <button className="_wiki-detail-page-item" onClick={() => onReadPage(page)}>
                  <span
                    className="_wiki-detail-type-dot"
                    style={{ background: TYPE_COLORS[page.type] || TYPE_COLOR_FALLBACK }}
                  />
                  <span className="_wiki-detail-page-item-title">{page.title}</span>
                </button>
                <Button
                  type="text"
                  className="_wiki-detail-page-delete"
                  onClick={() => onDeletePage(page)}
                  tooltip={t('wiki.detail.pages.deletePage')}
                >
                  {t('wiki.detail.pages.delete')}
                </Button>
              </div>
            );
          })}
        </div>
        <RawFilesSection
          wikiId={wikiId}
          refreshKey={rawRefreshKey}
          onRead={onReadRaw}
          onDelete={onDeleteRaw}
        />
      </div>
      <ResizeHandle onMouseDown={onMouseDown} />
      <div className="_wiki-detail-split-content">
        {selectedPage ? (
          <div className="_wiki-detail-content-inner">
            <div className="_wiki-detail-content-head">
              <span
                className="_wiki-detail-type-dot _wiki-detail-type-dot-lg"
                style={{ background: TYPE_COLORS[selectedPage.type] || TYPE_COLOR_FALLBACK }}
              />
              <h1 className="_wiki-detail-content-title">{selectedPage.title}</h1>
            </div>
            {metadata && (
              <div className="_wiki-detail-side-tags">
                {metadata.type && <Tag size="sm">{metadata.type}</Tag>}
                {metadata.tags &&
                  metadata.tags
                    .replaceAll('[', '')
                    .replaceAll(']', '')
                    .split(',')
                    .filter(Boolean)
                    .map((tag) => (
                      <Tag key={tag.trim()} size="sm">
                        {tag.trim()}
                      </Tag>
                    ))}
                {metadata.created && <Text theme="label">{t('wiki.detail.created', { date: metadata.created })}</Text>}
              </div>
            )}
            {readLoading ? (
              <StatusTip status="loading" />
            ) : (
              <Card className="_wiki-detail-content-card">
                <Card.Body>
                  <AssetMarkdown content={displayContent} />
                </Card.Body>
              </Card>
            )}
          </div>
        ) : (
          <div className="_wiki-detail-side-empty">
            <BooksIcon size="large" />
            <Text theme="label">{t('wiki.detail.pages.selectPage')}</Text>
          </div>
        )}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════
// Raw Files Section — 原始文档列表，默认展开
// ═══════════════════════════════════════════
export function RawFilesSection({
  wikiId,
  refreshKey,
  onRead,
  onDelete,
}: {
  wikiId: string;
  refreshKey?: number;
  onRead: (filename: string) => void;
  onDelete: (filename: string) => Promise<void> | void;
}) {
  const { t } = useTranslation();
  const [files, setFiles] = useState<{ filename: string; size: number }[]>([]);
  const [expanded, setExpanded] = useState(true);
  const [loading, setLoading] = useState(false);

  const reload = useCallback(() => {
    if (!wikiId) {
      setFiles([]);
      return;
    }
    setLoading(true);
    knowledgeApi.wiki
      .rawList(wikiId)
      .then((r: any) => setFiles(r?.files || []))
      .catch((e: any) => tea.notify.error(e?.message || t('wiki.notify.loadRawFailed')))
      .finally(() => setLoading(false));
  }, [wikiId]);

  // refreshKey 变化（如上传成功后）时强制重载原始文档列表，无需用户手动刷新。
  useEffect(() => {
    reload();
  }, [reload, refreshKey]);

  async function handleDelete(filename: string) {
    await onDelete(filename);
    reload();
  }

  // 加载中显示占位提示，避免请求期间直接渲染空态（return null）导致用户无感知。
  if (loading)
    return (
      <div className="_wiki-detail-rawfiles-loading">
        <FolderIcon size={12} /> {t('wiki.detail.rawFiles.loading')}
      </div>
    );
  if (files.length === 0) return null;

  return (
    <div className="_wiki-detail-rawfiles">
      <button className="_wiki-detail-rawfiles-toggle" onClick={() => setExpanded(!expanded)}>
        <span>
          <FolderIcon size={12} /> {t('wiki.detail.rawFiles.title', { count: files.length })}
        </span>
        <ChevronRightIcon size={12} className={expanded ? 'is-open' : ''} />
      </button>
      {expanded && (
        <div className="_wiki-detail-rawfiles-list">
          {files.map((file) => (
            <div key={file.filename} className="_wiki-detail-rawfiles-item">
              <button onClick={() => onRead(file.filename)}>
                <FileIcon size={12} />
                <span>{file.filename}</span>
                <em>{(file.size / 1024).toFixed(1)}K</em>
              </button>
              <Button
                type="text"
                className="_wiki-detail-page-delete"
                onClick={() => void handleDelete(file.filename)}
                tooltip={t('wiki.detail.rawFiles.deleteRaw')}
              >
                {t('common.delete')}
              </Button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/**
 * WikiDetailView —— Wiki 详情视图（概览 / 图谱 / 页面 / 搜索 四个 Tab + 添加文档 Modal）。
 * 全部数据与回调来自 useWikiSources 的返回对象，组件只做渲染。
 */
import { useTranslation } from 'react-i18next';
import { Alert, Button, Card, Input, MetricsBoard, Modal, Progress, SearchBox, StatusTip, TabPanel, Tabs, Tag, Text } from 'tea-component';
import {
  ArrowLeftIcon,
  AttachIcon,
  BooksIcon,
  ChartBarIcon,
  CheckCircleIcon,
  CheckIcon,
  CloseCircleIcon,
  CloseIcon,
  FileIcon,
  LayersIcon as ArchitectureIcon,
  LoadingIcon,
  SearchIcon,
  StarIcon,
} from 'tea-icons-react';
import { knowledgeApi } from '@/lib/api/knowledge-api';
import { tea } from '@/lib/tea-bridge';
import { WIKI_ALLOWED_FILE_RE, TYPE_COLORS, TYPE_COLOR_FALLBACK, type DetailTab } from '../constants/wiki-constants';
import { WikiStatusBadge } from './wiki-ui';
import { GraphTabContent, PagesTabContent } from './wiki-detail-components';
import type { WikiSourcesStore } from '../hooks/useWikiSources';

export function WikiDetailView({ store }: { store: WikiSourcesStore }) {
  const { t } = useTranslation();
  const {
    sources,
    selectedWikiId,
    setSubView,
    fetchSources,
    setShowAddDoc,
    setAddDocTab,
    handleIngest,
    ingestBusy,
    displayIngestState,
    setIngestState,
    activeTab,
    setActiveTab,
    pages,
    types,
    typeCounts,
    edgeCount,
    handleReadPage,
    filteredPages,
    pageTypeFilter,
    setPageTypeFilter,
    selectedPage,
    readLoading,
    displayContent,
    metadata,
    rawRefreshKey,
    handleDeletePage,
    handleDeleteRaw,
    setSelectedPage,
    setReadContent,
    setReadLoading,
    searchQuery,
    setSearchQuery,
    handleSearch,
    searching,
    searchResults,
    pendingFiles,
    setPendingFiles,
    uploadProgress,
    submitting,
    mdDocs,
    setMdDocs,
    handleUploadMdBatch,
    handleBatchUpload,
    fileInputRef,
  } = store;

  const source = sources.find((s) => s.wiki_id === selectedWikiId);
  const wikiName = source?.name ?? '';

  // 选中 Wiki 已不存在（被删除或刷新失败）时给出可返回的空态，避免死胡同
  if (!source) {
    return (
      <Card>
        <Card.Body>
          <Button type="text" onClick={() => { fetchSources(); setSubView('list'); }}>
            <ArrowLeftIcon size={12} /> {t('wiki.breadcrumb')}
          </Button>
          <StatusTip status="empty" emptyText={t('wiki.detail.notFound')} />
        </Card.Body>
      </Card>
    );
  }

  return (
    <div className="_wiki-detail-root">
      <Card>
        <Card.Body className="_wiki-detail-header-body">
          <div className="_wiki-detail-breadcrumb">
            <Button type="link" onClick={() => { fetchSources(); setSubView('list'); }}>
              <ArrowLeftIcon size={12} /> {t('wiki.breadcrumb')}
            </Button>
            <span className="_wiki-detail-breadcrumb-sep">/</span>
            <span className="_wiki-detail-breadcrumb-current">{wikiName}</span>
          </div>
          <div className="_wiki-detail-header-row">
            <div className="_wiki-detail-header-info">
              <BooksIcon size={20} />
              <span className="_wiki-detail-title">{wikiName}</span>
              {source && <WikiStatusBadge status={source.status} />}
            </div>
            <div className="_wiki-detail-header-actions">
              <Button
                type="text"
                onClick={() => {
                  setShowAddDoc(true);
                  setAddDocTab('file');
                }}
              >
                <AttachIcon size={14} /> {t('wiki.detail.add')}
              </Button>
              <Button
                type="primary"
                onClick={() => handleIngest(selectedWikiId)}
                disabled={ingestBusy}
                loading={ingestBusy && displayIngestState.wiki === wikiName}
              >
                {ingestBusy && displayIngestState.wiki === wikiName ? (
                  t('wiki.detail.processing')
                ) : (
                  <>
                    <StarIcon size={14} /> {t('wiki.action.ingest')}
                  </>
                )}
              </Button>
            </div>
          </div>
          <div className="_detail-meta-row">
            <span>{t('wiki.detail.pages', { count: pages.length })}</span>
          </div>
        </Card.Body>
      </Card>

      {(displayIngestState.active || displayIngestState.log.length > 0) &&
        displayIngestState.wiki === wikiName && (
          <Card className="_wiki-detail-ingest-card">
            <Card.Body>
              <div className="_wiki-detail-ingest">
                <div className="_wiki-detail-ingest-head">
                  <Text className="_wiki-detail-ingest-title">
                    {displayIngestState.active ? (
                      <LoadingIcon size={14} />
                    ) : (
                      <CheckCircleIcon size={14} />
                    )}{' '}
                    {t('wiki.detail.ingestTitle', { name: displayIngestState.wiki })}
                  </Text>
                  {!displayIngestState.active && (
                    <Button
                      type="text"
                      onClick={() => setIngestState((state) => ({ ...state, log: [] }))}
                    >
                      {t('wiki.detail.clear')}
                    </Button>
                  )}
                </div>
                {displayIngestState.total > 0 && (
                  <>
                    <Progress
                      percent={Math.round(
                        (displayIngestState.done / displayIngestState.total) * 100,
                      )}
                    />
                    <div className="_wiki-detail-ingest-meta">
                      <Text theme="label">{displayIngestState.detail}</Text>
                      <Text theme="label">
                        {displayIngestState.done}/{displayIngestState.total}
                      </Text>
                    </div>
                    {displayIngestState.checkCount > 0 && (
                      <Text theme="label">
                        {t('wiki.detail.queryCount', { count: displayIngestState.checkCount })}
                        {displayIngestState.lastCheckedAt
                          ? t('wiki.detail.lastQuery', { time: displayIngestState.lastCheckedAt })
                          : ''}
                      </Text>
                    )}
                  </>
                )}
                {displayIngestState.active && displayIngestState.currentFile && (
                  <Text theme="label" className="_wiki-detail-ingest-file">
                    <FileIcon size={12} /> {displayIngestState.currentFile}
                  </Text>
                )}
                {displayIngestState.log.length > 0 && (
                  <div className="_wiki-detail-ingest-log">
                    {displayIngestState.log.map((item, index) => (
                      <div key={`${item.file}-${index}`} className="_wiki-detail-ingest-log-item">
                        {item.status === 'done' ? (
                          <CheckCircleIcon size={12} />
                        ) : (
                          <CloseCircleIcon size={12} />
                        )}
                        <span className="_wiki-detail-ingest-log-file">{item.file}</span>
                        {item.error && (
                          <span className="_wiki-detail-ingest-log-error">{item.error}</span>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </Card.Body>
          </Card>
        )}

      <Tabs
        activeId={activeTab}
        onActive={(tab) => setActiveTab(tab.id as DetailTab)}
        disableTabScrolling
        className="_wiki-detail-tabs"
        tabs={[
          {
            id: 'overview',
            label: (
              <span className="_wiki-detail-tab-label">
                <ChartBarIcon size={14} />
                {t('wiki.detail.tab.overview')}
              </span>
            ),
          },
          {
            id: 'graph',
            label: (
              <span className="_wiki-detail-tab-label">
                <ArchitectureIcon size={14} />
                {t('wiki.detail.tab.graph')}
              </span>
            ),
          },
          {
            id: 'pages',
            label: (
              <span className="_wiki-detail-tab-label">
                <FileIcon size={14} />
                {t('wiki.detail.tab.pages')}
              </span>
            ),
          },
          {
            id: 'search',
            label: (
              <span className="_wiki-detail-tab-label">
                <SearchIcon size={14} />
                {t('wiki.detail.tab.search')}
              </span>
            ),
          },
        ]}
      >
        <TabPanel id="overview">
          <div className="_wiki-detail-overview">
            <div className="_wiki-detail-overview-stats">
              <MetricsBoard title={t('wiki.detail.overview.totalPages')} value={pages.length} />
              <MetricsBoard title={t('wiki.detail.overview.pageTypes')} value={types.length} />
              <MetricsBoard title={t('wiki.detail.overview.edges')} value={edgeCount} />
            </div>
            <Card bordered>
              <Card.Body title={t('wiki.detail.overview.typeDist')}>
                {types.length === 0 ? (
                  <StatusTip status="empty" emptyText={t('wiki.detail.overview.emptyPages')} />
                ) : (
                  <div className="_wiki-detail-type-dist">
                    {types.map((type) => {
                      const count = typeCounts[type];
                      const pct = pages.length ? Math.round((count / pages.length) * 100) : 0;
                      return (
                        <div key={type} className="_wiki-detail-type-row">
                          <span className="_wiki-detail-type-label">
                            <span
                              className="_wiki-detail-type-dot"
                              style={{ background: TYPE_COLORS[type] || TYPE_COLOR_FALLBACK }}
                            />
                            {type}
                          </span>
                          <span className="_wiki-detail-type-bar">
                            <span
                              className="_wiki-detail-type-bar-fill"
                              style={{
                                width: `${pct}%`,
                                background: TYPE_COLORS[type] || TYPE_COLOR_FALLBACK,
                              }}
                            />
                          </span>
                          <Text theme="label" className="_wiki-detail-type-count">
                            {t('wiki.detail.typePct', { count, pct })}
                          </Text>
                        </div>
                      );
                    })}
                  </div>
                )}
              </Card.Body>
            </Card>
            <Card bordered>
              <Card.Body title={t('wiki.detail.overview.pageList')}>
                {pages.length === 0 ? (
                  <StatusTip status="empty" emptyText={t('wiki.detail.overview.emptyPageList')} />
                ) : (
                  <div className="_wiki-detail-overview-grid">
                    {pages.slice(0, 9).map((page) => (
                      <button
                        key={(page as any).id || page.path}
                        onClick={() => {
                          handleReadPage(page);
                          setActiveTab('pages');
                        }}
                        className="_wiki-detail-overview-item"
                      >
                        <span
                          className="_wiki-detail-type-dot"
                          style={{ background: TYPE_COLORS[page.type] || TYPE_COLOR_FALLBACK }}
                        />
                        <span className="_wiki-detail-overview-item-title">{page.title}</span>
                      </button>
                    ))}
                  </div>
                )}
              </Card.Body>
            </Card>
          </div>
        </TabPanel>

        <TabPanel id="graph">
          <GraphTabContent
            graphData={store.graphData}
            graphLoading={store.graphLoading}
            selectedPage={selectedPage}
            readLoading={readLoading}
            displayContent={displayContent}
            metadata={metadata}
            onNodeClick={(node) => {
              const page =
                pages.find((item) => ((item as any).id || item.path) === node.id) ||
                ({ path: node.id, title: node.label, type: node.type } as any);
              handleReadPage(page);
            }}
            onClearSelection={() => setSelectedPage(null)}
          />
        </TabPanel>
        <TabPanel id="pages">
          <PagesTabContent
            pages={filteredPages}
            allPages={pages}
            types={types}
            typeCounts={typeCounts}
            pageTypeFilter={pageTypeFilter}
            setPageTypeFilter={setPageTypeFilter}
            selectedPage={selectedPage}
            readLoading={readLoading}
            displayContent={displayContent}
            metadata={metadata}
            wikiId={selectedWikiId}
            rawRefreshKey={rawRefreshKey}
            onReadPage={handleReadPage}
            onDeletePage={handleDeletePage}
            onDeleteRaw={handleDeleteRaw}
            onReadRaw={(filename) => {
              const rawPage = {
                path: `raw/${filename}`,
                title: filename,
                type: 'raw',
              } as any;
              setSelectedPage(rawPage);
              setReadContent('');
              setReadLoading(true);
              knowledgeApi.wiki
                .rawRead(selectedWikiId, [filename])
                .then((result: any) => setReadContent(result?.items?.[0]?.content || ''))
                .catch((error: any) => {
                  setReadContent('');
                  tea.notify.error(error?.message || t('wiki.notify.readRawFailed'));
                })
                .finally(() => setReadLoading(false));
            }}
          />
        </TabPanel>
        <TabPanel id="search">
          <div className="_wiki-detail-search">
            <SearchBox
              value={searchQuery}
              onChange={setSearchQuery}
              onSearch={handleSearch}
              placeholder={t('wiki.detail.search.placeholder')}
            />
            {searching && <StatusTip status="loading" />}
            {!searching && searchResults.length > 0 && (
              <>
                <Text theme="label">{t('wiki.detail.search.results', { count: searchResults.length })}</Text>
                <div className="_wiki-detail-search-results">
                  {searchResults.map((result, index) => (
                    <button
                      key={`${result.path}-${index}`}
                      type="button"
                      className="_wiki-detail-search-item"
                      onClick={() => {
                        const page =
                          pages.find((item) => ((item as any).id || item.path) === result.path) ||
                          ({
                            path: result.path,
                            title: result.title,
                            type: result.type,
                          } as any);
                        handleReadPage(page);
                        setActiveTab('pages');
                      }}
                    >
                      <span className="_wiki-detail-search-item-head">
                        <span
                          className="_wiki-detail-type-dot"
                          style={{ background: TYPE_COLORS[result.type] || TYPE_COLOR_FALLBACK }}
                        />
                        <span className="_wiki-detail-search-item-title">{result.title}</span>
                        <Tag size="sm">{result.type}</Tag>
                        <Text theme="label" className="_wiki-detail-search-item-score">
                          {result.score.toFixed(1)}
                        </Text>
                      </span>
                      {result.snippet && (
                        <Text theme="label" className="_wiki-detail-search-item-snippet">
                          {result.snippet}
                        </Text>
                      )}
                    </button>
                  ))}
                </div>
              </>
            )}
            {!searching && searchResults.length === 0 && searchQuery && (
              <StatusTip status="empty" emptyText={t('wiki.detail.search.empty')} />
            )}
          </div>
        </TabPanel>
      </Tabs>

      {/* Add Doc Modal */}
      {store.showAddDoc && (
        <Modal
          visible
          caption={t('wiki.detail.addDoc.caption', { name: wikiName })}
          size="m"
          onClose={() => store.setShowAddDoc(false)}
          disableEscape={submitting}
        >
          <Modal.Body>
            <Alert type="info">{t('wiki.detail.addDoc.hint')}</Alert>
            <Tabs
              tabs={[
                { id: 'file', label: t('wiki.detail.addDoc.file') },
                { id: 'markdown', label: t('wiki.detail.addDoc.markdown') },
              ]}
              activeId={store.addDocTab}
              onActive={(tab) => store.setAddDocTab(tab.id as 'file' | 'markdown')}
            >
              <TabPanel id="file">
                <div className="_wiki-detail-upload-panel">
                  <div
                    className="_wiki-detail-dropzone"
                    onClick={() => fileInputRef.current?.click()}
                    onDragOver={(e) => e.preventDefault()}
                    onDrop={(e) => {
                      e.preventDefault();
                      const all = Array.from(e.dataTransfer.files);
                      const allowed = all.filter((f) => WIKI_ALLOWED_FILE_RE.test(f.name));
                      const rejected = all.length - allowed.length;
                      if (rejected > 0) {
                        tea.notify.warning(
                          t('wiki.detail.ignored', { count: rejected }),
                        );
                      }
                      if (allowed.length > 0) setPendingFiles((prev) => [...prev, ...allowed]);
                    }}
                  >
                    <Text theme="weak">{t('wiki.detail.dropzone')}</Text>
                  </div>
                  {pendingFiles.length > 0 && (
                    <div className="_wiki-detail-upload-files">
                      {pendingFiles.map((f, i) => (
                        <div key={i} className="_wiki-detail-upload-file">
                          <span className="_wiki-detail-upload-file-name">{f.name}</span>
                          <span className="_wiki-detail-upload-file-size">
                            {(f.size / 1024).toFixed(1)}K
                          </span>
                          {uploadProgress[f.name] === 'done' && (
                            <span className="_wiki-detail-upload-file-success">
                              <CheckIcon size={12} />
                            </span>
                          )}
                          {uploadProgress[f.name] === 'error' && (
                            <span className="_wiki-detail-upload-file-error">
                              <CloseIcon size={12} />
                            </span>
                          )}
                          {uploadProgress[f.name] === 'pending' && (
                            <span className="_wiki-detail-upload-file-pending">…</span>
                          )}
                          {!submitting && (
                            <Button
                              type="text"
                              onClick={() =>
                                setPendingFiles((prev) => prev.filter((_, j) => j !== i))
                              }
                            >
                              {t('common.delete')}
                            </Button>
                          )}
                        </div>
                      ))}
                    </div>
                  )}
                  {pendingFiles.length > 0 && (
                    <div className="_wiki-detail-upload-footer">
                      <Text theme="weak">{t('wiki.detail.upload.footer', { count: pendingFiles.length })}</Text>
                      <Button
                        type="primary"
                        onClick={handleBatchUpload}
                        disabled={submitting}
                        loading={submitting}
                      >
                        {submitting ? t('wiki.detail.upload.submitting') : t('wiki.detail.upload.confirm')}
                      </Button>
                    </div>
                  )}
                </div>
              </TabPanel>
              <TabPanel id="markdown">
                <div className="_wiki-detail-upload-panel">
                  {mdDocs.map((doc, i) => (
                    <div key={i} className="_wiki-detail-markdown-doc">
                      <div className="_wiki-detail-markdown-doc-head">
                        <Input
                          size="full"
                          value={doc.filename}
                          onChange={(v) =>
                            setMdDocs((prev) =>
                              prev.map((d, j) => (j === i ? { ...d, filename: v } : d)),
                            )
                          }
                          width={100}
                          placeholder="filename.md"
                        />
                        {mdDocs.length > 1 && (
                          <Button
                            type="text"
                            onClick={() => setMdDocs((prev) => prev.filter((_, j) => j !== i))}
                          >
                            {t('common.delete')}
                          </Button>
                        )}
                      </div>
                      <Input.TextArea
                        size="full"
                        rows={6}
                        value={doc.content}
                        onChange={(v) =>
                          setMdDocs((prev) =>
                            prev.map((d, j) => (j === i ? { ...d, content: v } : d)),
                          )
                        }
                        placeholder={t('wiki.detail.md.placeholder')}
                      />
                    </div>
                  ))}
                  <Button
                    onClick={() => setMdDocs((prev) => [...prev, { filename: '', content: '' }])}
                  >
                    {t('wiki.detail.md.add')}
                  </Button>
                  <div className="_wiki-detail-upload-footer">
                    <Text theme="weak">
                      {t('wiki.detail.md.pending', { count: mdDocs.filter((d) => d.filename.trim() && d.content.trim()).length })}
                    </Text>
                    <Button
                      type="primary"
                      onClick={handleUploadMdBatch}
                      disabled={
                        submitting || mdDocs.every((d) => !d.filename.trim() || !d.content.trim())
                      }
                      loading={submitting}
                    >
                      {submitting ? t('wiki.detail.upload.submitting') : t('wiki.detail.upload.confirm')}
                    </Button>
                  </div>
                </div>
              </TabPanel>
            </Tabs>
            <input
              ref={fileInputRef}
              type="file"
              accept=".md,.txt,.markdown"
              multiple
              className="_wiki-detail-hidden-input"
              onChange={(e) => {
                // accept 属性只是浏览器建议，用户可在选择器切换"所有文件"绕过，
                // 这里做二次校验，与拖拽入口一致，避免二进制文件被读成乱码上传。
                const all = Array.from(e.target.files ?? []);
                const allowed = all.filter((f) => WIKI_ALLOWED_FILE_RE.test(f.name));
                const rejected = all.length - allowed.length;
                if (rejected > 0) {
                  tea.notify.warning(
                    t('wiki.detail.ignored', { count: rejected }),
                  );
                }
                if (allowed.length > 0) setPendingFiles((prev) => [...prev, ...allowed]);
                e.target.value = '';
              }}
            />
          </Modal.Body>
        </Modal>
      )}
    </div>
  );
}

/**
 * wiki-ui —— Wiki 资产页的小型展示组件。
 * 从 WikiSourcesPanel.tsx 拆出：状态徽章 / Owner 标签 / 懒加载知识图谱容器。
 */
import { lazy, Suspense } from 'react';
import { useTranslation } from 'react-i18next';
import { StatusTip } from 'tea-component';
import type { GraphData, GraphNode, WikiDetail, WikiPage } from '@/lib/api/knowledge-api';
import { StatusTag } from '@/components/StatusTag';
import { OwnerLabel } from '@/components/OwnerLabel';
import { WIKI_STATUS_KEY, WIKI_STATUS_THEME } from '../constants/wiki-constants';

export function WikiStatusBadge({ status }: { status: WikiDetail['status'] }) {
  const { t } = useTranslation();
  const theme = WIKI_STATUS_THEME[status] ?? ('default' as const);
  const label = WIKI_STATUS_KEY[status] ? t(WIKI_STATUS_KEY[status]) : status;
  return <StatusTag label={label} theme={theme} />;
}

/**
 * Owner 展示 —— 复用通用 OwnerLabel（显示用户名而非 user_id）。
 * useUserDisplayName 内部有全局缓存 + 只在首次 miss 时发 usersApi.get，
 * 同一 user_id 多行共享同一份缓存，扩展性 O(distinct user 数)，不是 O(行数)。
 * 抽子组件是因为 Rules of Hooks —— 不能在 .map 里循环调 hook。
 */
export function WikiOwnerLabel({ userId, currentUserId }: { userId: string; currentUserId: string }) {
  const { t } = useTranslation();
  return (
    <OwnerLabel
      userId={userId}
      currentUserId={currentUserId}
      title={t('wiki.detail.owner', { userId })}
      youText={t('wiki.detail.you')}
      youClassName="ml-1 text-xs text-primary"
    />
  );
}

// ═══════════════════════════════════════════
// Knowledge Graph Embed (lazy loaded sigma)
// ═══════════════════════════════════════════
const KnowledgeGraphLazy = lazy(() => import('./KnowledgeGraph'));

export function KnowledgeGraphEmbed({
  data,
  loading,
  onNodeClick,
  highlightNode,
}: {
  data: GraphData | null;
  loading: boolean;
  onNodeClick: (node: GraphNode) => void;
  highlightNode: string | null;
}) {
  const { t } = useTranslation();
  return (
    <Suspense fallback={<StatusTip status="loading" loadingText={t('wiki.detail.graph.loading')} />}>
      <KnowledgeGraphLazy
        data={data}
        loading={loading}
        onNodeClick={onNodeClick}
        highlightNode={highlightNode}
        className="_wiki-detail-graph-embed"
      />
    </Suspense>
  );
}

// 导出类型供外层复用，避免 import 类型路径散落
export type { WikiPage };

/**
 * BoardView —— 工作台任务卡片网格 + 详情抽屉。
 */
import { useTranslation } from 'react-i18next';
import { Button, Drawer, Pagination, Tag, Text } from 'tea-component';
import { AddIcon, ChevronRightIcon, UsergroupIcon } from 'tea-icons-react';
import { canDeleteTask, type Task, type Team } from '@/services';
import { useDisplayNameResolver } from '@/services/user-profile-store';
import TaskDetail from './TaskDetail';
import { participationOf, useStatusLabels, type AgentOption, type TaskParticipationView } from '../utils/workbench-utils';

export default function BoardView({
  tasks,
  tasksLoading,
  tasksTotal,
  currentPage,
  setCurrentPage,
  pageSize,
  selected,
  onSelect,
  onCreate,
  onDelete,
  onUpdateStatus,
  onUpdateTask,
  agents,
  teams,
  currentUser,
  participationByTask,
}: {
  tasks: Task[];
  tasksLoading: boolean;
  tasksTotal: number;
  currentPage: number;
  setCurrentPage: (page: number) => void;
  pageSize: number;
  selected: Task | null;
  onSelect: (id: string | null) => void;
  onCreate: () => void;
  onDelete: (task: Task) => void;
  onUpdateStatus: (task: Task, status: Task['status']) => void;
  onUpdateTask: (task: Task, patch: Partial<Pick<Task, 'title' | 'description' | 'source_type' | 'source_url' | 'linked_agents'>>) => void;
  agents: AgentOption[];
  teams: Team[];
  currentUser: string;
  participationByTask: Map<string, TaskParticipationView>;
}) {
  const { t } = useTranslation();
  const statusLabels = useStatusLabels();
  // 参与者 tooltip 展示 display_name 而非 user_id（与抽屉详情 UserChip 同一缓存）
  const resolveUserName = useDisplayNameResolver();
  const selectedTeam = selected ? teams.find((x) => x.team_id === selected.team_id) ?? null : null;

  // 后端分页：useTasks 已只返回当前页数据，不需要前端切片
  const totalPages = Math.max(1, Math.ceil(tasksTotal / pageSize));
  const safePage = Math.min(currentPage, totalPages);
  const pagedTasks = tasks;
  return (
    <div className="_memory-panel-card">
      {/* 头部：复用 members / agents 的 Section 通用头部（标题 + 计数 Tag + 副标题 + 右侧操作） */}
      <div className="_memory-section-header">
        <div className="_memory-section-header-info">
          <div className="_memory-section-header-title-row">
            <div className="_memory-section-title">{t('task.list.title')}</div>
            <Tag size="sm">{t('task.list.count', { count: tasksTotal })}</Tag>
          </div>
          <div className="_memory-section-subtitle">{t('task.list.subtitle')}</div>
        </div>
        <Button type="primary" onClick={onCreate}>
          <AddIcon size={14} />
          {t('task.create')}
        </Button>
      </div>

      {tasksLoading && tasks.length === 0 ? (
        // 首屏加载骨架屏：6 个占位卡片 + shimmer 动画
        <div className="_memory-workbench-skeleton-grid" aria-label="loading">
          {[0, 1, 2, 3, 4, 5].map((i) => (
            <div key={i} className="_memory-workbench-skeleton-card">
              <div className="_memory-workbench-skeleton-line _memory-workbench-skeleton-line--title" />
              <div className="_memory-workbench-skeleton-line _memory-workbench-skeleton-line--desc" />
              <div className="_memory-workbench-skeleton-line _memory-workbench-skeleton-line--meta" />
            </div>
          ))}
        </div>
      ) : tasks.length === 0 ? (
        <div className="_memory-workbench-list-empty">
          <Text theme="weak">{t('task.empty')}</Text>
        </div>
      ) : (
        <div className="_memory-workbench-task-grid">
          {pagedTasks.map((task) => {
            const view = participationOf(participationByTask, task.task_id);
            const imParticipant = view.users.includes(currentUser);
            const agentNameById = new Map(agents.map((a) => [a.id, a.name]));
            const agentLabels = view.agentIds.map((id) => agentNameById.get(id) ?? id);
            return (
              <button
                type="button"
                key={task.task_id}
                className="_memory-workbench-task-card"
                onClick={() => onSelect(task.task_id)}
              >
                {/* 标题行：状态 pill + 标题 + 箭头 */}
                <div className="_memory-workbench-task-card-head">
                  <span className={`_memory-workbench-status-pill _memory-workbench-status-pill--${task.status}`}>
                    {statusLabels[task.status]}
                  </span>
                  <span className="_memory-workbench-task-card-title" title={task.title}>{task.title}</span>
                  <ChevronRightIcon size={14} className="_memory-workbench-task-card-chevron" />
                </div>

                {/* 描述 */}
                {task.description && (
                  <p className="_memory-workbench-task-card-desc">{task.description}</p>
                )}

                {/* 元信息行：参与者 · Agent · 时间 */}
                <div className="_memory-workbench-task-card-meta">
                  <span
                    className="_memory-workbench-meta-item"
                    title={view.users.length === 0 ? t('task.participants.empty') : t('task.participants.tooltip', { users: view.users.map((u) => resolveUserName(u)).join('\n') })}
                  >
                    <UsergroupIcon size={12} />
                    {t('task.peopleCount', { count: view.users.length })}
                    {imParticipant && <span className="_memory-workbench-meta-you">{t('common.you2')}</span>}
                  </span>
                  <span
                    className="_memory-workbench-meta-item"
                    title={agentLabels.length === 0 ? t('task.agents.empty') : t('task.agents.tooltip', { agents: agentLabels.join('\n') })}
                  >
                    {t('task.agentCount', { count: agentLabels.length })}
                  </span>
                  <span className="_memory-workbench-task-card-time">
                    {new Date(task.updated_at_ms).toLocaleString()}
                  </span>
                </div>
              </button>
            );
          })}
        </div>
      )}

      {/* 分页：超过 1 页才展示 */}
      {totalPages > 1 && (
        <div className="_memory-workbench-pagination">
          <Pagination
            pageIndex={safePage}
            pageSize={pageSize}
            recordCount={tasksTotal}
            pageSizeVisible={false}
            onPagingChange={(query) => {
              if (query.pageIndex) setCurrentPage(query.pageIndex);
            }}
          />
        </div>
      )}

      {/* 详情抽屉：设置（状态 / 编辑 / 删除）都在抽屉内完成 */}
      <Drawer
        visible={!!selected}
        size="l"
        onClose={() => onSelect(null)}
        title={selected?.title}
        subtitle={selected && (
          <span className="_memory-workbench-drawer-subtitle">
            <span className="_memory-mono">{selected.task_id}</span>
            {selectedTeam && (
              <>
                <span className="_memory-workbench-meta-sep">·</span>
                {selectedTeam.name}
              </>
            )}
          </span>
        )}
        destroyOnClose
      >
        {selected && (
          <TaskDetail
            task={selected}
            onUpdateStatus={(s) => onUpdateStatus(selected, s)}
            onUpdateTask={(patch) => onUpdateTask(selected, patch)}
            onDelete={() => onDelete(selected)}
            canDelete={canDeleteTask(selected, selectedTeam, currentUser)}
            agents={agents}
            team={selectedTeam}
            currentUser={currentUser}
            participation={participationOf(participationByTask, selected.task_id)}
          />
        )}
      </Drawer>
    </div>
  );
}

/**
 * TaskCreateDialog — 「新建 Task」弹窗。
 *
 * 必填字段（前端校验）：
 *   - title         任务标题
 *   - description   任务描述
 *
 * 关于 team 归属：
 *   不再让用户在 dialog 里选 team。team 由右上角全局 TeamSwitcher 决定，
 *   这里只 readonly 展示「将创建到 team：name (team_id)」，避免出现「右上角是 A
 *   但弹窗里默认选了 B、用户没注意一切就走偏」的两套上下文不一致问题。
 *
 * 不再在创建时选 Agent — 关联 Agent 放到 task 创建之后再做。
 */

import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Alert, Tag, Input, Button, Form, Modal } from 'tea-component';
import '../styles/task-create-dialog.css';

export type TaskSourceType = 'manual' | 'tapd';

export interface TaskDraft {
  team_id: string;
  title: string;
  description: string;
  source_type: TaskSourceType;
  source_url: string;
  linked_agents: string[];
}

export default function TaskCreateDialog(props: {
  team: { team_id: string; name: string };
  onClose: () => void;
  onCreate: (draft: TaskDraft) => Promise<void> | void;
}) {
  const { t } = useTranslation();
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const canSubmit = title.trim().length > 0 && description.trim().length > 0;

  async function submit() {
    if (!canSubmit) return;
    setError(null);
    setSubmitting(true);
    try {
      await props.onCreate({
        team_id: props.team.team_id,
        title: title.trim(),
        description: description.trim(),
        source_type: 'manual',
        source_url: '',
        linked_agents: [],
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
      setSubmitting(false);
    }
  }

  return (
    <Modal visible caption={t('taskCreate.caption')} size="m" onClose={props.onClose} disableEscape={submitting}>
      <Modal.Body>
        <Form>
          <Form.Item label={t('taskCreate.team')}>
            <div className="_memory-tcd-team-row">
              <span className="_memory-tcd-team-avatar">{props.team.name.slice(0, 1).toUpperCase()}</span>
              <div className="_memory-tcd-team-meta">
                <div className="_memory-tcd-team-label">{t('taskCreate.teamLabel')}</div>
                <div className="_memory-tcd-team-name-row">
                  <span className="_memory-tcd-team-name">{props.team.name}</span>
                  <Tag size="sm">{props.team.team_id}</Tag>
                </div>
              </div>
            </div>
          </Form.Item>
          <Form.Item label={t('taskCreate.title')} required>
            <Input
              autoFocus
              size="full"
              value={title}
              onChange={setTitle}
              placeholder={t('taskCreate.titlePlaceholder')}
            />
          </Form.Item>
          <Form.Item label={t('taskCreate.description')} required extra={t('taskCreate.descriptionExtra')}>
            <Input.TextArea
              size="full"
              value={description}
              onChange={setDescription}
              rows={4}
              placeholder={t('taskCreate.descriptionPlaceholder')}
            />
          </Form.Item>
          {error && <Form.Item><Alert type="error">{error}</Alert></Form.Item>}
        </Form>
      </Modal.Body>
      <Modal.Footer>
        <Button type="primary" onClick={() => void submit()} disabled={!canSubmit} loading={submitting}>{t('taskCreate.submit')}</Button>
        <Button onClick={props.onClose} disabled={submitting}>{t('taskCreate.cancel')}</Button>
      </Modal.Footer>
    </Modal>
  );
}

/**
 * TaskDetail —— 工作台任务详情（编辑标题/描述、切换状态、查看参与者、删除）。
 */
import { useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Button, Input, Segment, Text } from 'tea-component';
import { DeleteIcon, EditIcon, UserIcon, UsergroupIcon } from 'tea-icons-react';
import { canEditTask, type Task, type Team } from '@/services';
import { useUserDisplayName } from '@/services/user-profile-store';
import { tea } from '@/lib/tea-bridge';
import { useStatusLabels, type AgentOption, type TaskParticipationView } from '../utils/workbench-utils';

/**
 * 参与者 chip：可见文本显示 display_name（缓存未命中先回退 id），
 * title 保留语义 tooltip + user_id 供排查。
 * 抽子组件是 Rules of Hooks 要求（不能在 .map 里循环调 useUserDisplayName）。
 */
function UserChip({
  userId,
  currentUser,
  tooltip,
}: {
  userId: string;
  currentUser: string;
  tooltip: string;
}) {
  const { t } = useTranslation();
  const name = useUserDisplayName(userId);
  return (
    <span className="_memory-workbench-chip" title={`${tooltip} · ${userId}`}>
      <UserIcon size={12} />
      <Text theme="text">{name || userId}</Text>
      {userId === currentUser && <span className="_memory-workbench-chip-you">{t('common.you.short')}</span>}
    </span>
  );
}

export default function TaskDetail({
  task,
  onUpdateStatus,
  onUpdateTask,
  onDelete,
  canDelete,
  agents,
  team,
  currentUser,
  participation,
}: {
  task: Task;
  onUpdateStatus: (s: Task['status']) => void;
  onUpdateTask: (patch: Partial<Pick<Task, 'title' | 'description' | 'source_type' | 'source_url' | 'linked_agents'>>) => void;
  /** 删除当前 task（权限校验与二次确认由外层统一处理） */
  onDelete: () => void;
  canDelete: boolean;
  agents: AgentOption[];
  /** 当前 task 所属 team — 可能为 null（理论上不会，但 team 被删除场景需兜底） */
  team: Team | null;
  currentUser: string;
  /** 从 useTeamParticipation 分桶后传下来的当前 task 观测数据 */
  participation: TaskParticipationView;
}) {
  const { t } = useTranslation();
  const statusLabels = useStatusLabels();
  // 编辑权限：team 内任意 member 可改 task（含切换 status）。
  const canEdit = canEditTask(task, team, currentUser);

  // —— 编辑态：只在用户点「编辑」后才进入；草稿独立维护，取消即丢弃 —— //
  const [editing, setEditing] = useState(false);
  const [draftTitle, setDraftTitle] = useState(task.title);
  const [draftDesc, setDraftDesc] = useState(task.description);

  // 切换 task / 退出编辑时同步草稿（避免编辑 A 后切换到 B 草稿还停在 A）
  useEffect(() => {
    setEditing(false);
    setDraftTitle(task.title);
    setDraftDesc(task.description);
  }, [task.task_id]);

  function startEdit() {
    setDraftTitle(task.title);
    setDraftDesc(task.description);
    setEditing(true);
  }
  function cancelEdit() {
    setEditing(false);
  }
  function saveEdit() {
    const patch: Partial<Pick<Task, 'title' | 'description' | 'source_type' | 'source_url' | 'linked_agents'>> = {};
    const title = draftTitle.trim();
    if (title.length === 0) {
      tea.notify.warning(t('task.titleRequired'));
      return;
    }
    if (title !== task.title) patch.title = title;
    if (draftDesc !== task.description) patch.description = draftDesc;

    if (Object.keys(patch).length === 0) {
      setEditing(false);
      return;
    }
    onUpdateTask(patch);
    setEditing(false);
  }

  // 参与者展示：creator 单列独立；其余进 "参与的 User"。
  // 数据源统一走 participation-log 观测 —— proxy session init 完成时 append 的
  // "实际起过 session 的 user"。creator 用自己的 agent 开工也算一次真实参与，
  // 所以不再过滤 creator（会同时出现在"创建者"和"参与的 User"两处，语义不同）。
  const participantUsers = participation.users;

  // 「实际参与 Agent」：session 观测到的 agent，映射到 team 的 agent name；
  // 未在 team agents 列表里的（比如已被删除）保留 agent_id 兜底展示。
  const sessionAgents = useMemo(() => {
    const nameById = new Map(agents.map((a) => [a.id, a.name]));
    return participation.agentIds.map((id) => ({ id, name: nameById.get(id) ?? id }));
  }, [participation.agentIds, agents]);

  return (
    <div className="_memory-workbench-detail-content">
      {/* === 工具行：编辑 + 状态切换（标题 / task_id / team 已在抽屉头部展示） === */}
      <div className="_memory-workbench-detail-toolbar">
        {editing ? (
          <>
            <Input
              value={draftTitle}
              onChange={setDraftTitle}
              placeholder={t('task.titlePlaceholder')}
              size="full"
              className="_memory-workbench-title-input"
            />
            <Button onClick={cancelEdit}>{t('common.cancel')}</Button>
            <Button type="primary" onClick={saveEdit}>{t('task.save')}</Button>
          </>
        ) : (
          <>
            {canEdit && (
              <Button type="text" onClick={startEdit} tooltip={t('task.edit.tooltip')}>
                <EditIcon size={14} />
                {t('task.edit')}
              </Button>
            )}
            <Segment
              value={task.status}
              onChange={(v) => onUpdateStatus(v as Task['status'])}
              disabled={!canEdit}
              options={(Object.keys(statusLabels) as Task['status'][]).map((s) => ({
                value: s,
                text: statusLabels[s],
              }))}
            />
          </>
        )}
      </div>

      {/* === 参与者 === */}
      <div className="_memory-workbench-people">
        <div className="_memory-workbench-people-row">
          <Text theme="weak" className="_memory-workbench-people-label">{t('task.creator')}</Text>
          <UserChip
            userId={task.creator_user_id}
            currentUser={currentUser}
            tooltip={t('task.creator.tooltip')}
          />
        </div>
        <div className="_memory-workbench-people-row">
          <Text theme="weak" className="_memory-workbench-people-label">{t('task.participantUsers')}</Text>
          {participantUsers.length === 0 ? (
            <Text theme="weak">—</Text>
          ) : (
            participantUsers.map((u) => (
              <UserChip
                key={u}
                userId={u}
                currentUser={currentUser}
                tooltip={t('task.participantUsers.tooltip')}
              />
            ))
          )}
        </div>
        <div className="_memory-workbench-people-row">
          <Text theme="weak" className="_memory-workbench-people-label">{t('task.sessionAgents')}</Text>
          {sessionAgents.length === 0 ? (
            <Text theme="weak">—</Text>
          ) : (
            sessionAgents.map((a) => (
              <span
                key={a.id}
                className="_memory-workbench-chip"
                title={t('task.sessionAgents.tooltip', { id: a.id })}
              >
                <UsergroupIcon size={12} />
                <Text theme="text">{a.name}</Text>
              </span>
            ))
          )}
        </div>
      </div>

      {/* === 描述 === */}
      <div className="_memory-workbench-block">
        <Text theme="label" className="_memory-workbench-block-label">{t('task.description')}</Text>
        {editing ? (
          <Input.TextArea
            value={draftDesc}
            onChange={setDraftDesc}
            rows={6}
            size="full"
            placeholder={t('task.descriptionPlaceholder')}
          />
        ) : (
          <div className="_memory-workbench-desc-view">{task.description}</div>
        )}
      </div>

      <Text theme="weak" className="_memory-workbench-footer">
        {t('task.footer', { created: new Date(task.created_at_ms).toLocaleString(), updated: new Date(task.updated_at_ms).toLocaleString() })}
      </Text>

      {/* === 危险操作 === */}
      {canDelete && (
        <div className="_memory-workbench-danger">
          <Button type="error" onClick={onDelete}>
            <DeleteIcon size={12} /> {t('task.delete.okText')}
          </Button>
        </div>
      )}
    </div>
  );
}

/**
 * TaskWorkbench — 用户工作台。
 *
 * 收敛到两件事：
 *   1. 列出/创建/管理本团队下的 task；
 *   2. 通过 log tab 看 task 历史记录。
 *
 * 布局：进入页面为全宽卡片网格；点击卡片拉出 Drawer，在抽屉内查看详情与设置
 * （改状态、编辑标题/描述、删除）。
 *
 * 数据走后端链路 A（services/backendStore.ts，内部调用 @/lib/teamApi 的 meta 接口）。
 */
import { useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Card, Text } from 'tea-component';
import {
  useTasks,
  useTeams,
  createTask,
  deleteTask,
  updateTask,
  updateTaskStatus,
  canDeleteTask,
  canEditTask,
} from '@/services';
import { tea } from '@/lib/tea-bridge';
import { TeamHeaderCard } from '@/components/team/TeamHeaderCard';
import TaskCreateDialog, { type TaskDraft } from './TaskCreateDialog';
import BoardView from './BoardView';
import { useTeamParticipation } from '../hooks/useTeamParticipation';
import { errMsg, type AgentOption, type WorkbenchTab } from '../utils/workbench-utils';
import '../styles/task-workbench.css';

function EmptyTeam() {
  const { t } = useTranslation();
  return (
    <Card>
      <Card.Body className="_memory-workbench-empty-card">
        <Text theme="strong" className="_memory-workbench-empty-title">{t('task.emptyTeam.title')}</Text>
        <Text theme="weak" className="_memory-workbench-empty-desc">
          {t('task.emptyTeam.desc')}
        </Text>
      </Card.Body>
    </Card>
  );
}

export default function TaskWorkbench(props: {
  tab?: WorkbenchTab;
  onTabChange?: (tab: WorkbenchTab) => void;
  /** 当前激活的 team id（可空：未选时只显示 empty state） */
  activeTeamId: string | null;
  /** 当前用户名（task 的 creator_user_id） */
  currentUser: string;
  /** 当前 team 下可关联的 Agent 列表（来自 TeamManagementPanel 的同源数据） */
  agents: AgentOption[];
  /** 是否为全局 admin（保留接口兼容；admin 不再有 task 特权） */
  isAdmin?: boolean;
}) {
  const { t } = useTranslation();
  const { activeTeamId, currentUser, agents } = props;
  // 后端分页：useTasks 根据 page + pageSize 调 Panel 聚合接口，内核只返回当前页
  const PAGE_SIZE = 12;
  const [currentPage, setCurrentPage] = useState(1);
  const { tasks, total: tasksTotal, loading: tasksLoading } = useTasks(activeTeamId, currentPage, PAGE_SIZE);
  const { teams, activeTeam } = useTeams();
  const participationByTask = useTeamParticipation(activeTeamId);
  const [showCreate, setShowCreate] = useState(false);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  // 切换 team 时重置到第 1 页
  useEffect(() => { setCurrentPage(1); }, [activeTeamId]);

  const sortedTasks = useMemo(() => {
    return [...tasks].sort((a, b) => b.updated_at_ms - a.updated_at_ms);
  }, [tasks]);

  const selected = useMemo(
    () => (selectedId ? tasks.find((t) => t.task_id === selectedId) ?? null : null),
    [selectedId, tasks]
  );

  /**
   * 创建 task：team_id 完全由当前激活 team 决定，不再让 dialog 选 team
   * （切 team 的唯一入口在右上角全局 TeamSwitcher）。
   */
  async function handleCreate(draft: TaskDraft) {
    // 谁点击「创建 Task」，谁就是 creator_user_id。
    const team = teams.find((t) => t.team_id === draft.team_id);
    if (!team) {
      tea.notify.error(`team "${draft.team_id}" ${t('task.emptyTeam.title')}`);
      return;
    }
    try {
      const task = await createTask({
        team_id: draft.team_id,
        creator_user_id: currentUser,
        title: draft.title,
        description: draft.description,
        source_type: draft.source_type,
        source_url: draft.source_url,
        linked_agents: draft.linked_agents
      });
      setSelectedId(task.task_id);
      setShowCreate(false);
    } catch (err) {
      tea.notify.error(errMsg(err));
    }
  }

  return (
    <div className="_memory-workbench-body">
      {!activeTeamId ? (
        <EmptyTeam />
      ) : (
        <>
          {/* 当前 team 概览（与 team 管理页同一组件） */}
          {activeTeam && <TeamHeaderCard team={activeTeam} />}
          <BoardView
          tasks={sortedTasks}
          tasksLoading={tasksLoading}
          tasksTotal={tasksTotal}
          currentPage={currentPage}
          setCurrentPage={setCurrentPage}
          pageSize={PAGE_SIZE}
          selected={selected}
          onSelect={(id) => setSelectedId(id)}
          onCreate={() => setShowCreate(true)}
          onDelete={async (task) => {
            // 权限：删除 task 仅创建者 / team admin / 全局 admin
            const team = teams.find((t) => t.team_id === task.team_id) ?? null;
            if (!canDeleteTask(task, team, currentUser)) {
              tea.notify.warning(
                t('task.delete.noPermission', { title: task.title, creator: task.creator_user_id })
              );
              return;
            }
            const ok = await tea.confirm({
              message: t('task.delete.confirm', { title: task.title }),
              description: t('task.delete.description', { id: task.task_id }),
              okText: t('task.delete.okText'),
              cancelText: t('task.delete.cancelText'),
            });
            if (ok) {
              try {
                await deleteTask(task.task_id);
                if (selectedId === task.task_id) setSelectedId(null);
              } catch (err) {
                tea.notify.error(errMsg(err));
              }
            }
          }}
          onUpdateStatus={async (task, status) => {
            // 权限：编辑 task（含切换 status）允许 team 内任意 member / admin
            const team = teams.find((t) => t.team_id === task.team_id) ?? null;
            if (!canEditTask(task, team, currentUser)) {
              tea.notify.warning(t('task.noPermissionEdit'));
              return;
            }
            try {
              await updateTaskStatus(task.task_id, status, currentUser);
            } catch (err) {
              tea.notify.error(errMsg(err));
            }
          }}
          onUpdateTask={async (task, patch) => {
            const team = teams.find((t) => t.team_id === task.team_id) ?? null;
            if (!canEditTask(task, team, currentUser)) {
              tea.notify.warning(t('task.noPermissionEdit'));
              return;
            }
            try {
              await updateTask(task.task_id, patch, currentUser);
            } catch (err) {
              tea.notify.error(errMsg(err));
            }
          }}
          agents={agents}
          teams={teams}
          currentUser={currentUser}
          participationByTask={participationByTask}
          />
        </>
      )}

      {showCreate && activeTeam && (
        // team 由右上角全局 TeamSwitcher 决定，dialog 里不再让用户选；
        // 这里 activeTeam 必为非空，因为上面 !activeTeamId 分支已经走 EmptyTeam 了
        <TaskCreateDialog
          team={{ team_id: activeTeam.team_id, name: activeTeam.name }}
          onClose={() => setShowCreate(false)}
          onCreate={handleCreate}
        />
      )}
    </div>
  );
}

