  description: string;
  role_prompt: string;
  rules_prompt: string;
  skills: string[];
  code_graphs: string[];
  llm_wikis: string[];
  chat_memories: string[];
  created_at_ms: number;
}

/** 内置模板 —— 不落库，每次读取时与自定义模板合并返回。 */
function getBuiltinAgentTemplates(): AgentTemplate[] {
