/**
 * storage-utils.ts — 本地演示数据层的共享底座。
 *
 * 供 agent-template-store / asset-scope-store / user-asset-store /
 * account-store / user-profile-store 共用：
 *   - safeParse：容错的 JSON.parse，解析失败时回退默认值；
 *   - emitChange / CHANGE_EVENT：写操作后广播一个全局事件，配合
 *     useChangeNotifier 让订阅方（各 useXxx hook）自动重渲染；
 *   - useChangeNotifier：简易 forceUpdate，监听 CHANGE_EVENT 与浏览器
 *     原生 'storage' 事件（跨 tab 同步）。
 *
 * 这些 store 均为前端演示阶段的 localStorage 实现，后端上线后整批替换为
 * fetch 即可，UI 层不需要改。
 */

import { useEffect, useState } from 'react';

export const CHANGE_EVENT = 'tdai-memory.demo-store-change';

export function safeParse<T>(raw: string | null, fallback: T): T {
  if (!raw) return fallback;
  try {
    const v = JSON.parse(raw);
    return v ?? fallback;
  } catch {
    return fallback;
  }
}

export function emitChange(): void {
  try {
    window.dispatchEvent(new Event(CHANGE_EVENT));
  } catch {
    /* ignore */
  }
}

/** 简易 forceUpdate：localStorage / 自定义事件触发后 +1。 */
export function useChangeNotifier(): number {
  const [tick, setTick] = useState(0);
  useEffect(() => {
    const onChange = () => setTick((v) => v + 1);
    window.addEventListener(CHANGE_EVENT, onChange);
    window.addEventListener('storage', onChange); // 跨 tab 同步
    return () => {
      window.removeEventListener(CHANGE_EVENT, onChange);
      window.removeEventListener('storage', onChange);
    };
  }, []);
  return tick;
}

/**
 * useSkillDetailCache — 按需加载 skill 数据面详情缓存。
 *
 * 背景：asset/list-accessible 接口返回的资产列表只含 asset 层字段
 *（version 恒为 1，无 owner_agent_id），skill 数据面的真实 version 和
 * owner_agent_id 需要调 getSkill() 获取。旧实现在列表加载后对每条 skill
 * 并发 N 次 getSkill()（N+1），用户还没点开任何一条就把全部详情拉回来。
 *
 * 本 hook 改为按需：列表先用 asset 层默认值渲染，当用户选中某条 skill
 * 后才补拉那一条的数据面详情并写入缓存，后续同一 skill 再次命中直接读缓存。
 *
 * 使用方式（父组件）：
 *   const { getFromCache, preload, applyCachedDetail } = useSkillDetailCache(activeTeamId);
 *   useEffect(() => { if (selectedId) void preload(selectedId); }, [selectedId]);
 *   列表渲染：const s = applyCachedDetail(skill);
 */

import { useRef, useState, useCallback } from 'react';
import { getSkill } from '@/lib/api/skill-api';

export interface CachedSkillDetail {
  version: number;
  owner_agent_id: string;
}

export function useSkillDetailCache(teamId: string | null | undefined) {
  /** skill_id → 已拉取的数据面详情（version + owner_agent_id）。 */
  const cacheRef = useRef(new Map<string, CachedSkillDetail>());

  /** 正在请求中的 skill_id 集合，防止同一 skill 并发重复请求。 */
  const inFlightRef = useRef(new Set<string>());

  /** 每次缓存写入后 +1，父组件依赖此值在 useMemo 中重算列表项。 */
  const [cacheVersion, setCacheVersion] = useState(0);

  /** 同步读取缓存（不会触发请求）。 */
  const getFromCache = useCallback((skillId: string): CachedSkillDetail | undefined => {
    return cacheRef.current.get(skillId);
  }, []);

  /** 预加载一条 skill 的数据面详情（幂等，已缓存或正在请求的直接跳过）。 */
  const preload = useCallback(async (skillId: string) => {
    if (!teamId || !skillId) return;
    if (cacheRef.current.has(skillId) || inFlightRef.current.has(skillId)) return;
    inFlightRef.current.add(skillId);
    try {
      const full = await getSkill({
        skill_id: skillId,
        team_id: teamId,
        include_content: false,
        include_manifest: false,
      });
      cacheRef.current.set(skillId, {
        version: full.version,
        owner_agent_id: full.owner_agent_id,
      });
      setCacheVersion((n) => n + 1);
    } catch {
      // 静默失败：列表仍用 asset 默认值（v1 / 空 owner_agent_id）
    } finally {
      inFlightRef.current.delete(skillId);
    }
  }, [teamId]);

  /**
   * 用缓存里的最新值覆盖 skill 对象的 version / owner_agent_id 字段。
   * 缓存 miss 则原样返回，不影响渲染。
   */
  const applyCachedDetail = useCallback(<T extends { skill_id: string; version: number; owner_agent_id: string }>(
    skill: T,
  ): T => {
    const cached = cacheRef.current.get(skill.skill_id);
    if (!cached) return skill;
    return { ...skill, version: cached.version, owner_agent_id: cached.owner_agent_id };
  }, []);

  return { getFromCache, preload, applyCachedDetail, cacheRef, cacheVersion };
}

/**
 * useCurrentRole — 获取当前登录用户的角色
 *
 * 返回 'admin' | 'member' | 'reviewer' | null（null = 未登录）。
 *
 * 角色模型（唯一权威口径，勿再改回"按 team 成员表判断 admin"）：
 *   - admin  是**全局角色**，与是否创建/加入任何 team 无关（哪怕当前没有任何 team，也始终是 admin）。
 *     admin 的职责是管理 team（建团队、录入成员），不管理具体资源。
 *   - member 是**team 内角色**，即某个 team 的成员，负责在 team 内管理资源（agent/skill/wiki/code/memory）。
 *   - 因此判断顺序必须是：先判是不是全局 admin；不是，才去查其在 active team 里的成员角色。
 *     反过来"先查 team 成员表、查不到就当无角色"是错的——会导致"admin 账号下没有 team 时
 *     被误判为非 admin（甚至 null）"。
 */
import { useMemo } from 'react';
import { useTeams, roleInTeam, isGlobalAdmin } from '@/services';
import { useAuthStore } from '@/stores/auth';

export type TeamRole = 'admin' | 'member' | 'reviewer';

export function useCurrentRole(): TeamRole | null {
  const { auth } = useAuthStore();
  const { activeTeam } = useTeams();
  return useMemo(() => {
    if (!auth) return null;
    // 全局 admin：独立于 team，始终是 admin（不依赖 activeTeam / team.members 查询结果）
    // isAdmin 来自 auth/verify 的 user_type === 'system_admin'，是唯一权威字段。
    if (isGlobalAdmin(auth.user, auth.isAdmin)) return 'admin';
    // 非 admin：角色取决于其在当前 active team 里的成员记录（一般就是 'member'）
    return roleInTeam(activeTeam, auth.user_id);
  }, [activeTeam, auth]);
}

/**
 * user-asset-store.ts — 用户自建资产（skill / memory）的本地 localStorage 层。
 *
 * 从原 demoStore.ts 中抽出。
 *
 * 用户可以创建自己的 skill 或 memory 资产：
 *   - scope = 'team'    → 团队内共享，所有成员可见并可分配给自己的 Agent
 *   - scope = 'private' → 仅自己可见，只有 owner 可分配给自己的 Agent
 *
 * 团队资产 = 所有成员设为 'team' 的资产合集
 * 固定资产 = 从团队/个人资产中选择分配给具体 Agent 的资产
 *
 * 注：全部资产已切换到真实后端 API，本文件仅保留 localStorage 读写能力
 * 供 ChatMemoryPanel 等组件使用。
 */

import { emitChange, safeParse } from './storage-utils';

const USER_ASSETS_KEY = 'tdai-memory.userAssets.v1';

export type UserAssetKind = 'skill' | 'memory';

export interface UserAsset {
  asset_id: string;
  kind: UserAssetKind;
  owner_user_id: string;
  team_id: string;
  title: string;
  description: string;
  scope: 'team' | 'private';
  created_at_ms: number;
  updated_at_ms: number;
}

function readUserAssets(): UserAsset[] {
  if (typeof window === 'undefined') return [];
  return safeParse<UserAsset[]>(localStorage.getItem(USER_ASSETS_KEY), []);
}

function writeUserAssets(assets: UserAsset[]): void {
  try {
    localStorage.setItem(USER_ASSETS_KEY, JSON.stringify(assets));
  } catch {
    /* ignore */
  }
  emitChange();
}

/** 创建用户自建资产 */
export function createUserAsset(input: {
  kind: UserAssetKind;
  owner_user_id: string;
  team_id: string;
  title: string;
  description?: string;
  scope?: 'team' | 'private';
}): UserAsset {
  const assets = readUserAssets();
  const now = Date.now();
  const asset: UserAsset = {
    asset_id: `ua_${now}_${Math.random().toString(36).slice(2, 8)}`,
    kind: input.kind,
    owner_user_id: input.owner_user_id,
    team_id: input.team_id,
    title: input.title.trim(),
    description: (input.description ?? '').trim(),
    scope: input.scope ?? 'team',
    created_at_ms: now,
    updated_at_ms: now,
  };
  assets.push(asset);
  writeUserAssets(assets);
  return asset;
}

/** 更新用户自建资产（只有 owner 可调用） */
export function updateUserAsset(
  asset_id: string,
  patch: Partial<Pick<UserAsset, 'title' | 'description' | 'scope'>>
): void {
  const assets = readUserAssets();
  const target = assets.find((a) => a.asset_id === asset_id);
  if (!target) return;
  if (patch.title !== undefined) target.title = patch.title.trim();
  if (patch.description !== undefined) target.description = patch.description.trim();
  if (patch.scope !== undefined) target.scope = patch.scope;
  target.updated_at_ms = Date.now();
  writeUserAssets(assets);
}

/** 删除用户自建资产 */
export function deleteUserAsset(asset_id: string): void {
  const assets = readUserAssets().filter((a) => a.asset_id !== asset_id);
  writeUserAssets(assets);
}

/** 读取某用户拥有的资产（按 kind 过滤） */
export function getUserAssetsByOwner(owner_user_id: string, kind: UserAssetKind, team_id?: string): UserAsset[] {
  return readUserAssets().filter(
    (a) => a.owner_user_id === owner_user_id && a.kind === kind && (!team_id || a.team_id === team_id)
  );
}

/** 读取团队可见资产 = 该 team 内所有成员设为 scope='team' 的资产 + 当前用户自己的私密资产。
 *  team_id 为空时不按 team 过滤（返回所有 team 的可见资产）。 */
export function getTeamVisibleAssets(
  team_id: string | null | undefined,
  kind: UserAssetKind,
  currentUser?: string
): UserAsset[] {
  return readUserAssets().filter(
    (a) => (!team_id || a.team_id === team_id) && a.kind === kind && (a.scope === 'team' || a.owner_user_id === currentUser)
  );
}

/**
 * user-profile-store.ts — 用户显示名缓存。
 *
 * 从后端 usersApi.get() 拉取 display_name，内存缓存避免重复请求。
 */

import { useState, useEffect, useCallback } from 'react';

// 内存缓存：user_id → display_name
const _displayNameCache = new Map<string, string>();
const _fetching = new Set<string>();
const _subscribers = new Set<() => void>();

function notify() { _subscribers.forEach((fn) => fn()); }

/** 批量写入展示名缓存（如 team-member/list 已带 username 时）。 */
export function seedDisplayNameCache(entries: Array<{ user_id: string; username?: string }>): void {
  let changed = false;
  for (const { user_id, username } of entries) {
    if (!user_id || !username?.trim()) continue;
    const name = username.trim();
    if (_displayNameCache.get(user_id) === name) continue;
    _displayNameCache.set(user_id, name);
    changed = true;
  }
  if (changed) notify();
}

/**
 * 订阅指定 user 的显示名。优先用内存缓存；未缓存时异步从后端拉取。
 */
export function useUserDisplayName(user_id: string | null | undefined): string {
  const [, force] = useState(0);
  useEffect(() => {
    const sub = () => force((n) => n + 1);
    _subscribers.add(sub);
    return () => { _subscribers.delete(sub); };
  }, []);

  if (!user_id) return '';
  const cached = _displayNameCache.get(user_id);
  if (cached) return cached;

  // 未缓存 → 异步拉取
  if (!_fetching.has(user_id)) {
    _fetching.add(user_id);
    import('@/lib/teamApi').then(({ usersApi }) => {
      usersApi.get(user_id)
        .then((u) => {
          const name = u.display_name || u.username || user_id;
          _displayNameCache.set(user_id, name);
          notify();
        })
        .catch(() => { /* 静默失败 */ })
        .finally(() => { _fetching.delete(user_id); });
    });
  }

  return user_id; // 拉取完成前显示 user_id
}

/**
 * 批量场景（如列表 tooltip 需要 join 多个用户名）的解析器。
 * 返回稳定函数引用；渲染期触发未缓存 id 的拉取，缓存就绪后经订阅触发重渲染。
 * 与 useUserDisplayName 同套缓存/订阅，二者解析结果一致。
 */
export function useDisplayNameResolver(): (userId: string) => string {
  const [, force] = useState(0);
  useEffect(() => {
    const sub = () => force((n) => n + 1);
    _subscribers.add(sub);
    return () => { _subscribers.delete(sub); };
  }, []);

  return useCallback((userId: string) => {
    if (!userId) return '';
    const cached = _displayNameCache.get(userId);
    if (cached) return cached;
    if (!_fetching.has(userId)) {
      _fetching.add(userId);
      import('@/lib/teamApi').then(({ usersApi }) => {
        usersApi.get(userId)
          .then((u) => {
            const name = u.display_name || u.username || userId;
            _displayNameCache.set(userId, name);
            notify();
          })
          .catch(() => { /* 静默失败 */ })
          .finally(() => { _fetching.delete(userId); });
      });
    }
    return userId;
  }, []);
}

/**
 * Auth Store (zustand)
 *
 * 对接新面板 Control（无 Cookie、无状态代理，见 09 设计文档 §3.3）。
 * 登录凭证（instance_id + user_key）缓存在 localStorage（lib/panelSession.ts），
 * "退出登录"/"会话失效"都只是清本地缓存，Control 无登出 API、无服务端会话表。
 *
 * 多 tab 同步：通过 storage 事件监听 localStorage 变化。
 *   - 其他 tab 登录 → 本 tab 自动恢复登录态（checkSession）
 *   - 其他 tab 登出 / 401 → 本 tab 自动退出到 LoginGate
 *
 * auth 三态：
 *   - null      检测登录态中（App 启动时调 checkSession 读取 localStorage 缓存）
 *   - undefined 确认未登录 → 渲染 LoginGate
 *   - AuthState 已登录 → 渲染主界面
 */
import { create } from 'zustand';
import { readAuth, clearAuth, resumeSession, type AuthState } from '@/components/LoginGate';
import { onUnauthorized } from '@/lib/teamApi';
import { clearBackendCache, writeActiveTeamId } from '@/services';

const PANEL_SESSION_KEY = 'tdai-panel.session';

interface AuthStore {
  auth: AuthState | null | undefined;
  /** 登录成功后写入（LoginGate 的 onLoggedIn 回调） */
  setAuth: (auth: AuthState) => void;
  /** 退出登录：清本地 localStorage 会话，回到 LoginGate（无后端调用） */
  logout: () => Promise<void>;
  /** App 启动时读取 localStorage 缓存；不管结果如何都会把 auth 从 null 推进到确定态 */
  checkSession: () => Promise<void>;
}

export const useAuthStore = create<AuthStore>((set) => ({
  auth: null,

  setAuth: (auth) => {
    set({ auth });
  },

  logout: async () => {
    // 新面板无服务端会话，登出即清本地缓存，无需（也没有）后端登出接口。
    // 清模块级后端缓存（teams/agents/tasks），避免新用户登录后短暂看到上一个用户的列表。
    // 用 clearBackendCache 而非 invalidateBackendCache：后者会广播事件触发已挂载页面的
    // refetch listener，此时还在用旧 session Header 发请求，会把旧数据重新拉回来；
    // 这里只清缓存，让新用户登录挂载组件时自然走首次拉取。
    clearBackendCache();
    // activeTeamId 可能指向旧用户才有权限的 team，清掉避免新用户登录后选了一个没权限的 team。
    writeActiveTeamId(null);
    clearAuth();
    set({ auth: undefined });
  },

  checkSession: async () => {
    const cached = readAuth();
    if (cached) {
      set({ auth: cached });
      return;
    }
    const auth = await resumeSession();
    set({ auth: auth ?? undefined });
  },
}));

/**
 * 跨 tab 同步：监听 localStorage 的 storage 事件。
 *
 * storage 事件只在"其他 tab"修改 localStorage 时触发（本 tab 的写入不会触发），
 * 非常适合做跨 tab 状态同步。
 *
 *   - 其他 tab 登录（写入 tdai-panel.session）→ 本 tab 恢复登录态
 *   - 其他 tab 登出 / 401（删除 tdai-panel.session）→ 本 tab 退出到 LoginGate
 */
if (typeof window !== 'undefined') {
  window.addEventListener('storage', (e) => {
    if (e.key !== PANEL_SESSION_KEY) return;

    if (e.newValue === null) {
      // 其他 tab 登出了 → 本 tab 同步退出
      clearBackendCache();
      writeActiveTeamId(null);
      clearAuth();
      useAuthStore.setState({ auth: undefined });
    } else {
      // 其他 tab 登录了 → 本 tab 恢复登录态
      void useAuthStore.getState().checkSession();
    }
  });
}

// 任意 meta 请求返回 HTTP 401 时（如 Control 校验错误落在该码），全局清会话回到登录页。
// 新面板下这不是主要的登出触发路径（主动登出走 logout()），仅作兜底。
// 与 logout() 一样清缓存，否则 401 重登后仍会短暂看到上个用户的列表。
// 只需在 store 模块加载时注册一次。
onUnauthorized(() => {
  clearBackendCache();
  writeActiveTeamId(null);
  clearAuth();
  useAuthStore.setState({ auth: undefined });
});

/**
 * stores/backend.ts — 全局后端数据 store（zustand）。
 *
 * 取代 backendStore.ts 里的模块级变量（_cachedTeams / _cachedAgentsMap / _inflightTeams …）。
 *
 * 核心设计：
 *   - teamsLoaded / agentsLoadedTeamIds：标记"已加载过"，
 *     避免每个组件挂载都重复 fetch。
 *   - invalidate()：写操作后调，清所有缓存 + 广播 BACKEND_REFRESH_EVENT。
 *   - invalidateTeam(teamId)：切 team 时只清当前 team 的 agents/tasks 缓存。
 *   - useTeams / useAgents / useTasks：从 store 读数据 + 触发 fetch，多组件共享同一份状态。
 */

import { create } from 'zustand';
import { useEffect, useState } from 'react';
import {
  teamsApi,
  membersApi,
  agentsApi,
  tasksApi,
  type TeamMember as BackendMember,
} from '@/lib/teamApi';
import { tea } from '@/lib/tea-bridge';
import i18n from '@/i18n';
import { seedDisplayNameCache } from '@/services/user-profile-store';

// 从 backendStore.ts re-import 纯函数（adapters / types），避免循环依赖
import {
  type Team,
  type Agent,
  type Task,
  adaptTeam,
  adaptMember,
  adaptAgent,
  adaptTask,
  readActiveTeamId,
  writeActiveTeamId,
  ensureValidActiveTeamId,
} from '@/services/backendStore';

// ========================= 事件常量 =========================

const BACKEND_REFRESH_EVENT = 'tdai-memory.backend-refresh';
const LOCAL_CHANGE_EVENT = 'tdai-memory.demo-store-change';

function emitBackendRefresh() {
  try { window.dispatchEvent(new Event(BACKEND_REFRESH_EVENT)); } catch { /* ignore */ }
}

// ========================= Store 类型 =========================

interface BackendState {
  // 数据
  teams: Team[];
  activeTeamId: string | null;
  agentsByTeam: Record<string, Agent[]>;
  // 全量总数（内核返回的 total），前端分页基于此计算总页数
  tasksTotalByTeam: Record<string, number>;
  // 后端分页缓存：tasksPagesByTeam[teamId]["offset:limit"] = Task[]
  tasksPagesByTeam: Record<string, Record<string, Task[]>>;
  // loaded 标记（避免重复 fetch）
  teamsLoaded: boolean;
  teamsLoading: boolean;
  agentsLoadedTeamIds: Set<string>;
  // in-flight 去重
  inflightTeams: Promise<void> | null;
  inflightAgents: Record<string, Promise<Agent[]>>;
  inflightTasks: Record<string, Promise<Task[]> | undefined>;

  // actions
  fetchTeams: () => Promise<void>;
  /**
   * 强制重新拉取 team 列表（忽略 teamsLoaded 缓存，保留 in-flight 去重）。
   * `silent: true` 时不在 UI 层翻转 teamsLoading —— 用于下拉框展开等后台保新鲜
   * 场景，避免 TeamManagementPanel 等消费方因 teamsLoading=true 而整体进入
   * loading 占位（表现为"点一下下拉框页面就刷新"）。
   */
  refreshTeams: (opts?: { silent?: boolean }) => Promise<void>;
  fetchAgents: (teamId: string) => Promise<Agent[]>;
  fetchTasks: (teamId: string, params?: { limit?: number; offset?: number; force?: boolean }) => Promise<Task[]>;
  setActiveTeamId: (teamId: string | null) => void;
  invalidate: () => void;
  invalidateTeam: (teamId: string) => void;
  clearAll: () => void;
}

// ========================= Store 实现 =========================

export const useBackendStore = create<BackendState>((set, get) => ({
  teams: [],
  activeTeamId: readActiveTeamId(),
  agentsByTeam: {},
  tasksTotalByTeam: {},
  tasksPagesByTeam: {},
  teamsLoaded: false,
  teamsLoading: false,
  agentsLoadedTeamIds: new Set(),
  inflightTeams: null,
  inflightAgents: {},
  inflightTasks: {},

  fetchTeams: async () => {
    const state = get();
    // 已加载过 → 不重复 fetch（只有 invalidate / clearAll 后才会重新拉）
    if (state.teamsLoaded) return;
    await get().refreshTeams();
  },

  refreshTeams: async (opts?: { silent?: boolean }) => {
    const state = get();
    // in-flight 去重：多个组件同时挂载时只发一次
    if (state.inflightTeams) { await state.inflightTeams; return; }

    const silent = opts?.silent === true;
    const promise = (async () => {
      // 静默刷新不翻转 teamsLoading —— 消费方（TeamManagementPanel 等）依赖它
      // 显示 loading 占位；下拉框展开这类后台保新鲜场景翻转它会导致
      // "点一下下拉框整个页面闪成 loading 再恢复"。
      if (!silent) set({ teamsLoading: true });
      try {
        const backendTeams = await teamsApi.list();
        // 批量拉 members（N+1 → N，但这是后端 API 限制，无批量接口）
        const memberResults = await Promise.all(
          backendTeams.map((t) => membersApi.list(t.team_id).catch(() => [] as BackendMember[]))
        );
        const adapted = backendTeams.map((bt, i) =>
          adaptTeam(bt, memberResults[i].map(adaptMember))
        );
        seedDisplayNameCache(adapted.flatMap((t) => t.members));
        ensureValidActiveTeamId(adapted);
        set({
          teams: adapted,
          teamsLoaded: true,
          teamsLoading: false,
          activeTeamId: readActiveTeamId(),
        });
      } catch (err) {
        console.error('[backend store] refreshTeams failed:', err);
        set({ teamsLoading: false });
        tea.notify.error(i18n.t('backend.loadTeamsFailed'));
      } finally {
        set({ inflightTeams: null });
      }
    })();

    set({ inflightTeams: promise });
    await promise;
  },

  fetchAgents: async (teamId: string) => {
    const state = get();
    // 已加载过 → 直接返回缓存
    if (state.agentsLoadedTeamIds.has(teamId)) {
      return state.agentsByTeam[teamId] ?? [];
    }
    // in-flight 去重
    if (state.inflightAgents[teamId] != null) {
      return state.inflightAgents[teamId];
    }

    const promise = (async () => {
      try {
        const backendAgents = await agentsApi.list(teamId);
        const adapted = backendAgents.map((ba, i) => adaptAgent(ba, i));
        set((s) => ({
          agentsByTeam: { ...s.agentsByTeam, [teamId]: adapted },
          agentsLoadedTeamIds: new Set(s.agentsLoadedTeamIds).add(teamId),
          inflightAgents: Object.fromEntries(
            Object.entries(s.inflightAgents).filter(([k]) => k !== teamId)
          ),
        }));
        return adapted;
      } catch (err) {
        console.error('[backend store] fetchAgents failed:', err);
        set((s) => ({
          inflightAgents: Object.fromEntries(
            Object.entries(s.inflightAgents).filter(([k]) => k !== teamId)
          ),
        }));
        tea.notify.error(i18n.t('backend.loadAgentsFailed'));
        return [];
      }
    })();

    set((s) => ({ inflightAgents: { ...s.inflightAgents, [teamId]: promise } }));
    return promise;
  },

  fetchTasks: async (teamId: string, params?: { limit?: number; offset?: number; force?: boolean }) => {
    const state = get();
    const limit = params?.limit ?? 20;
    const offset = params?.offset ?? 0;
    // 缓存 key：按 (offset, limit) 粒度（teamId 已在 tasksPagesByTeam[teamId] 这层隔离）
    const cacheKey = `${offset}:${limit}`;
    // 已缓存且非强制刷新 → 直接返回
    if (!params?.force && state.tasksPagesByTeam[teamId]?.[cacheKey]) {
      return state.tasksPagesByTeam[teamId][cacheKey];
    }
    // in-flight 去重
    if (state.inflightTasks[cacheKey]) { await state.inflightTasks[cacheKey]; return get().tasksPagesByTeam[teamId]?.[cacheKey] ?? []; }

    const promise = (async () => {
      try {
        const { items: tasksWithAgents, total } = await tasksApi.listWithAgents(teamId, { limit, offset });
        const adapted = tasksWithAgents.map((t) =>
          adaptTask(t, t.agents.filter((a) => a.status === 'active').map((a) => a.agent_id))
        );
        set((s) => {
          const teamPages = s.tasksPagesByTeam[teamId] ?? {};
          return {
            tasksPagesByTeam: { ...s.tasksPagesByTeam, [teamId]: { ...teamPages, [cacheKey]: adapted } },
            tasksTotalByTeam: { ...s.tasksTotalByTeam, [teamId]: total },
            inflightTasks: Object.fromEntries(
              Object.entries(s.inflightTasks).filter(([k]) => k !== cacheKey)
            ),
          };
        });
        return adapted;
      } catch (err) {
        console.error('[backend store] fetchTasks failed:', err);
        set((s) => ({
          inflightTasks: Object.fromEntries(
            Object.entries(s.inflightTasks).filter(([k]) => k !== cacheKey)
          ),
        }));
        tea.notify.error(i18n.t('backend.loadTasksFailed'));
        return [];
      }
    })();

    set((s) => ({ inflightTasks: { ...s.inflightTasks, [cacheKey]: promise } }));
    return promise;
  },

  setActiveTeamId: (teamId) => {
    writeActiveTeamId(teamId);
    set({ activeTeamId: teamId });
  },

  // 写操作后调：清所有缓存 + 广播刷新
  invalidate: () => {
    set({
      teams: [],
      teamsLoaded: false,
      teamsLoading: false,
      agentsByTeam: {},
      tasksTotalByTeam: {},
      tasksPagesByTeam: {},
      agentsLoadedTeamIds: new Set(),
      inflightTeams: null,
      inflightAgents: {},
      inflightTasks: {},
    });
    emitBackendRefresh();
  },

  // 切 team 时调：只清当前 team 的 agents/tasks 缓存
  invalidateTeam: (teamId) => {
    set((s) => {
      const agentsLoadedTeamIds = new Set(s.agentsLoadedTeamIds);
      agentsLoadedTeamIds.delete(teamId);
      const agentsByTeam = { ...s.agentsByTeam };
      delete agentsByTeam[teamId];
      const tasksPagesByTeam = { ...s.tasksPagesByTeam };
      delete tasksPagesByTeam[teamId];
      const tasksTotalByTeam = { ...s.tasksTotalByTeam };
      delete tasksTotalByTeam[teamId];
      return { agentsLoadedTeamIds, agentsByTeam, tasksPagesByTeam, tasksTotalByTeam };
    });
    emitBackendRefresh();
  },

  // 登出 / 401 时调：清所有缓存但不广播事件
  clearAll: () => {
    set({
      teams: [],
      teamsLoaded: false,
      teamsLoading: false,
      agentsByTeam: {},
      tasksTotalByTeam: {},
      tasksPagesByTeam: {},
      agentsLoadedTeamIds: new Set(),
      inflightTeams: null,
      inflightAgents: {},
      inflightTasks: {},
    });
  },
}));

// ========================= React Hooks =========================

/**
 * useTeams — 从 store 读 team 列表 + activeTeamId。
 *
 * 多个组件调 useTeams() 只会触发一次 fetchTeams（teamsLoaded 标记 + in-flight 去重）。
 * 写操作后调 invalidate() → teamsLoaded=false → 下次组件挂载/渲染时重新 fetch。
 * 切 team 通过 setActiveTeamId → 写 localStorage + 更新 state。
 */
export function useTeams(): {
  teams: Team[];
  activeTeamId: string | null;
  activeTeam: Team | null;
  loading: boolean;
} {
  const teams = useBackendStore((s) => s.teams);
  const teamsLoaded = useBackendStore((s) => s.teamsLoaded);
  const teamsLoading = useBackendStore((s) => s.teamsLoading);
  const activeTeamId = useBackendStore((s) => s.activeTeamId);
  const fetchTeams = useBackendStore((s) => s.fetchTeams);

  useEffect(() => {
    if (!teamsLoaded && !teamsLoading) {
      void fetchTeams();
    }
  }, [teamsLoaded, teamsLoading, fetchTeams]);

  // 监听 localStorage 变化（TeamSwitcher 写 activeTeamId 时触发）
  const [, force] = useState(0);
  useEffect(() => {
    const onLocalChange = () => {
      useBackendStore.setState({ activeTeamId: readActiveTeamId() });
      force((n) => n + 1);
    };
    window.addEventListener(LOCAL_CHANGE_EVENT, onLocalChange);
    return () => window.removeEventListener(LOCAL_CHANGE_EVENT, onLocalChange);
  }, []);

  const activeTeam = teams.find((t) => t.team_id === activeTeamId) ?? null;
  return { teams, activeTeamId, activeTeam, loading: teamsLoading };
}

const EMPTY_AGENTS: Agent[] = [];
const EMPTY_TASKS: Task[] = [];

/**
 * useAgents — 从 store 读指定 team 的 agent 列表。
 *
 * 同一 teamId 多个组件调用只触发一次 fetch。
 * invalidate() 或 invalidateTeam(teamId) 后才会重新拉。
 */
export function useAgents(teamId: string | null | undefined): {
  agents: Agent[];
  loading: boolean;
} {
  // 用 ref 缓存上次的 teamId，避免 selector 每次返回不同引用
  const agents = useBackendStore((s) =>
    teamId ? (s.agentsByTeam[teamId] ?? EMPTY_AGENTS) : EMPTY_AGENTS
  );
  const loaded = useBackendStore((s) => (teamId ? s.agentsLoadedTeamIds.has(teamId) : true));
  const fetchAgents = useBackendStore((s) => s.fetchAgents);

  useEffect(() => {
    if (!teamId) return;
    if (!loaded) {
      void fetchAgents(teamId);
    }
  }, [teamId, loaded, fetchAgents]);

  return { agents, loading: !!teamId && !loaded };
}

/**
 * useTasks — 从 store 读指定 team 的 task 列表。
 */
export function useTasks(teamId: string | null | undefined, page: number = 1, pageSize: number = 12): {
  tasks: Task[];
  total: number;
  loading: boolean;
} {
  const offset = (page - 1) * pageSize;
  const cacheKey = `${offset}:${pageSize}`;
  const tasks = useBackendStore((s) =>
    teamId ? (s.tasksPagesByTeam[teamId]?.[cacheKey] ?? EMPTY_TASKS) : EMPTY_TASKS
  );
  const total = useBackendStore((s) =>
    teamId ? (s.tasksTotalByTeam[teamId] ?? 0) : 0
  );
  const loaded = useBackendStore((s) =>
    teamId ? !!s.tasksPagesByTeam[teamId]?.[cacheKey] : true
  );
  const fetchTasks = useBackendStore((s) => s.fetchTasks);

  useEffect(() => {
    if (!teamId || loaded) return;
    void fetchTasks(teamId, { limit: pageSize, offset });
  }, [teamId, offset, pageSize, loaded, fetchTasks]);

  return { tasks, total, loading: !!teamId && !loaded };
}

/**
 * readActiveTeamAgents — 同步读缓存的 agent 列表（不触发请求）。
 * 供 SkillsPanel 等仅需"引用列表"的场景使用。
 */
export function readActiveTeamAgents(teamId: string | null): Array<{ id: string; name: string }> {
  if (!teamId) return [];
  const cached = useBackendStore.getState().agentsByTeam[teamId];
  if (cached) return cached.map((a) => ({ id: a.agent_id, name: a.name }));
  // 缓存未命中：触发后台拉取
  void useBackendStore.getState().fetchAgents(teamId);
  return [];
}

// ========================= 导出 invalidate / clearAll（供 mutations 调用） =========================

export function invalidateBackendCache(): void {
  useBackendStore.getState().invalidate();
}

export function clearBackendCache(): void {
  useBackendStore.getState().clearAll();
}

export function invalidateTeamCache(teamId: string): void {
  useBackendStore.getState().invalidateTeam(teamId);
}
